@Composable
fun SplashScreen(navController: NavController, viewModel: POSViewModel) {
    val context = androidx.compose.ui.platform.LocalContext.current
    val sharedPrefs = remember { context.getSharedPreferences("pos_prefs", android.content.Context.MODE_PRIVATE) }
    val isLoggedIn = remember { sharedPrefs.getString("logged_in_phone", null) != null }

    var showNoInternetDialog by remember { mutableStateOf(false) }
    val scope = rememberCoroutineScope()

    fun checkAndProceed() {
        scope.launch {
            var loggedPhone = sharedPrefs.getString("logged_in_phone", "")

            if (loggedPhone.isNullOrEmpty()) {
                val dbAccounts = viewModel.allAccounts.value
                val activeAcc = dbAccounts.firstOrNull { it.status == "on" } ?: dbAccounts.firstOrNull()
                if (activeAcc != null) {
                    loggedPhone = activeAcc.phoneNo
                    sharedPrefs.edit().putString("logged_in_phone", loggedPhone).putString("last_registered_phone", loggedPhone).apply()
                }
            }

            if (loggedPhone.isNullOrEmpty()) {
                kotlinx.coroutines.delay(800)
                navController.navigate("login") {
                    popUpTo("splash") { inclusive = true }
                }
                return@launch
            }

            if (!viewModel.isInternetAvailable(context)) {
                val localAccount = viewModel.getLocalAccountByPhone(loggedPhone)
                val currentDeviceId = viewModel.getDeviceId(context)
                val isAccessAllowed = viewModel.checkAccessAuthorization(
                    serverStatus = localAccount?.status ?: "off",
                    localAccount = localAccount,
                    currentDeviceId = currentDeviceId
                )

                if (isAccessAllowed) {
                    kotlinx.coroutines.delay(800)
                    navController.navigate("dashboard") {
                        popUpTo("splash") { inclusive = true }
                    }
                } else {
                    showNoInternetDialog = true
                }
            } else {
                showNoInternetDialog = false
                kotlinx.coroutines.delay(800)
                val (isActive, _) = viewModel.checkUserActivationStatus(context, loggedPhone)
                val localAccount = viewModel.getLocalAccountByPhone(loggedPhone)
                val currentDeviceId = viewModel.getDeviceId(context)

                // Check authorization using strict status AND deviceId matching
                val isAccessAllowed = viewModel.checkAccessAuthorization(
                    serverIsActive = isActive,
                    localAccount = localAccount,
                    currentDeviceId = currentDeviceId
                )

                if (isAccessAllowed) {
                    val todayStr = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.getDefault()).format(java.util.Date())
                    sharedPrefs.edit().putString("last_checked_date", todayStr).apply()
                    navController.navigate("dashboard") {
                        popUpTo("splash") { inclusive = true }
                    }
                } else if (localAccount != null && (localAccount.status == "off" || localAccount.status == "pending" || localAccount.status == "device_mismatch")) {
                    navController.navigate("waiting_activation") {
                        popUpTo("splash") { inclusive = true }
                    }
                } else {
                    navController.navigate("login") {
                        popUpTo("splash") { inclusive = true }
                    }
                }
            }
        }
    }

    LaunchedEffect(Unit) {
        checkAndProceed()
    }

    if (showNoInternetDialog) {
        AlertDialog(
            onDismissRequest = { },
            title = { Text("အင်တာနက် မရှိပါ", fontWeight = FontWeight.Bold) },
            text = { Text("POS စနစ် အသုံးပြုနိုင်ရန်နှင့် အကောင့် လုံခြုံရေး စစ်ဆေးရန် အင်တာနက် ဖွင့်ပေးပါ။") },
            confirmButton = {
                Button(onClick = {
                    checkAndProceed()
                }) {
                    Text("ထပ်မံစစ်ဆေးမည် (Retry)")
                }
            }
        )
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(Color.White),
        contentAlignment = Alignment.Center
    ) {
        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Center
        ) {
            UNLogo(size = 96.dp)
            Spacer(modifier = Modifier.height(24.dp))
            Text(
                text = "UN POS",
                fontWeight = FontWeight.Bold,
                fontSize = 28.sp,
                color = AppTextColor
            )
            Spacer(modifier = Modifier.height(8.dp))
            Text(
                text = "Point of Sale Management System",
                fontSize = 14.sp,
                color = Color.Gray
            )
            Spacer(modifier = Modifier.height(48.dp))
            CircularProgressIndicator(
                color = BrandPurple,
                modifier = Modifier.size(32.dp),
                strokeWidth = 3.dp
            )
        }
    }
}

