                    .padding(bottom = 16.dp)
            ) {
                OutlinedTextField(
                    value = phone,
                    onValueChange = { phone = it },
                    placeholder = { Text("Phone No", color = Color.Gray) },
                    modifier = Modifier
                        .fillMaxWidth()
                        .testTag("phone_input"),
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedTextColor = Color(0xFF1C1B1F),
                        unfocusedTextColor = Color(0xFF1C1B1F),
                        focusedBorderColor = Color.Transparent,
                        unfocusedBorderColor = Color.Transparent
                    ),
                    singleLine = true,
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Phone)
                )
            }

            // Password input
            Card(
                colors = CardDefaults.cardColors(containerColor = Color.White),
                shape = RoundedCornerShape(12.dp),
                elevation = CardDefaults.cardElevation(2.dp),
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(bottom = 8.dp)
            ) {
                OutlinedTextField(
                    value = password,
                    onValueChange = { password = it },
                    placeholder = { Text("Password", color = Color.Gray) },
                    visualTransformation = if (passwordVisible) VisualTransformation.None else PasswordVisualTransformation(),
                    trailingIcon = {
                        IconButton(onClick = { passwordVisible = !passwordVisible }) {
                            Icon(
                                imageVector = if (passwordVisible) Icons.Filled.Visibility else Icons.Filled.VisibilityOff,
                                contentDescription = "Toggle password visibility",
                                tint = BrandPurple
                            )
                        }
                    },
                    modifier = Modifier
                        .fillMaxWidth()
                        .testTag("password_input"),
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedTextColor = Color(0xFF1C1B1F),
                        unfocusedTextColor = Color(0xFF1C1B1F),
                        focusedBorderColor = Color.Transparent,
                        unfocusedBorderColor = Color.Transparent
                    ),
                    singleLine = true,
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Password)
                )
            }

            // Forgot password link
            Text(
                text = "Forgot Password?",
                color = BrandPurple,
                fontSize = 14.sp,
                fontWeight = FontWeight.Medium,
                modifier = Modifier
                    .align(Alignment.End)
                    .clickable { showForgotPasswordSheet = true }
                    .padding(bottom = 24.dp)
            )

            if (errorMessage.isNotEmpty()) {
                Text(
                    text = errorMessage,
                    color = Color.Red,
                    fontSize = 14.sp,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.padding(bottom = 16.dp)
                )
            }

            // LOGIN BUTTON
            Button(
                onClick = {
                    if (!viewModel.isInternetAvailable(context)) {
                        showNoInternetDialog = true
                        return@Button
                    }
                    scope.launch {
                        isLoading = true
                        errorMessage = ""
                        val (success, msg, status) = viewModel.login(context, phone, password)
                        isLoading = false
                        val localAccount = viewModel.getLocalAccountByPhone(phone)
                        val currentDeviceId = viewModel.getDeviceId(context)

                        val isAccessAllowed = viewModel.checkAccessAuthorization(
                            serverStatus = status,
                            localAccount = localAccount,
                            currentDeviceId = currentDeviceId
                        )

                        if (success && status == "on") {
                            val localAccount = viewModel.getLocalAccountByPhone(phone)
                            val currentDeviceId = viewModel.getDeviceId(context)

                            val isAccessAllowed = viewModel.checkAccessAuthorization(
                                serverStatus = status,
                                localAccount = localAccount,
                                currentDeviceId = currentDeviceId
                            )

                            if (isAccessAllowed) {
                                val todayStr = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.getDefault()).format(java.util.Date())
                                context.getSharedPreferences("pos_prefs", android.content.Context.MODE_PRIVATE).edit().putString("last_checked_date", todayStr).apply()
                                navController.navigate("dashboard") {
                                    popUpTo("login") { inclusive = true }
                                }
                            } else {
                                context.getSharedPreferences("pos_prefs", android.content.Context.MODE_PRIVATE).edit().putString("logged_in_phone", phone).putString("last_registered_phone", phone).apply()
                                navController.navigate("waiting_activation") {
                                    popUpTo("login") { inclusive = true }
                                }
                            }
                        } else if (status == "device_mismatch" || status == "pending" || status == "off") {
                            context.getSharedPreferences("pos_prefs", android.content.Context.MODE_PRIVATE).edit().putString("logged_in_phone", phone).putString("last_registered_phone", phone).apply()
                            navController.navigate("waiting_activation") {
                                popUpTo("login") { inclusive = true }
                            }
                        } else {
                            errorMessage = msg.ifEmpty { "ဖုန်းနံပါတ် သို့မဟုတ် စကားဝှက် မှားယွင်းနေပါသည်" }
                        }
                    }
                },
                enabled = !isLoading,
                modifier = Modifier
                    .fillMaxWidth()
                    .height(50.dp)
                    .testTag("login_button"),
                colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                shape = RoundedCornerShape(12.dp)
            ) {
                if (isLoading) {
                    CircularProgressIndicator(color = Color.White, modifier = Modifier.size(24.dp), strokeWidth = 2.dp)
                } else {
                    Text("LOGIN", fontSize = 16.sp, fontWeight = FontWeight.Bold, color = Color.White)
                }
            }

            Spacer(modifier = Modifier.height(24.dp))

            // Help text at the bottom to trigger registration screen
            Text(
                text = "အကောင့်အသစ်ဖွင့်မည်။",
                color = BrandPurple,
                fontSize = 15.sp,
                fontWeight = FontWeight.Bold,
                modifier = Modifier
                    .clickable {
                        viewModel.selectedRole.value = "ADMIN"
                        navController.navigate("register")
                    }
                    .padding(16.dp)
            )
        }
    }
}

