@Composable
fun AccountSelectionScreen(navController: NavController, viewModel: POSViewModel) {
    LaunchedEffect(Unit) {
        viewModel.selectedRole.value = "ADMIN"
        navController.navigate("register") {
            popUpTo("account_selection") { inclusive = true }
        }
    }
    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(LightBg)
            .padding(24.dp),
        contentAlignment = Alignment.Center
    ) {
        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            modifier = Modifier.fillMaxWidth()
        ) {
            Text(
