// 3. REGISTRATION SCREEN
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RegisterScreen(navController: NavController, viewModel: POSViewModel) {
    val username by viewModel.registerUsername.collectAsState()
    val bName by viewModel.registerBusinessName.collectAsState()
    val bType by viewModel.registerBusinessType.collectAsState()
    val address by viewModel.registerAddress.collectAsState()
    val phone by viewModel.registerPhone.collectAsState()
    val password by viewModel.registerPassword.collectAsState()
    val retypePassword by viewModel.registerRetypePassword.collectAsState()
    val role by viewModel.selectedRole.collectAsState()

    var isPasswordVisible by remember { mutableStateOf(false) }
    var isRetypePasswordVisible by remember { mutableStateOf(false) }
    var errorMessage by remember { mutableStateOf<String?>(null) }
    var isSubmitting by remember { mutableStateOf(false) }
    val scope = rememberCoroutineScope()

    fun isPasswordWeak(pass: String): Boolean {
        if (pass.length < 6) return true
        val commonEasyPasswords = setOf(
            "123456", "12345678", "123456789", "000000", "111111", "222222", "333333",
            "444444", "555555", "666666", "777777", "888888", "999999", "password",
            "qwerty", "090909", "123123", "abc123"
        )
        if (commonEasyPasswords.contains(pass.lowercase())) return true
        if (pass.all { it == pass[0] }) return true
        return false
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Register Account", fontWeight = FontWeight.Bold) },
                navigationIcon = {
                    IconButton(onClick = { navController.popBackStack() }) {
                        Icon(imageVector = Icons.Filled.ArrowBack, contentDescription = "Back")
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.White)
            )
        }
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .background(LightBg)
                .padding(innerPadding)
                .verticalScroll(rememberScrollState())
                .padding(16.dp)
        ) {
            // Role info banner
            Card(
                colors = CardDefaults.cardColors(containerColor = BrandPurple),
                shape = RoundedCornerShape(12.dp),
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(bottom = 16.dp)
            ) {
                Row(
                    modifier = Modifier.padding(16.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Icon(
                        imageVector = if (role == "ADMIN") Icons.Filled.AdminPanelSettings else Icons.Filled.Person,
                        contentDescription = "Role",
                        tint = Color.White,
                        modifier = Modifier.size(28.dp)
                    )
                    Spacer(modifier = Modifier.width(12.dp))
                    Text(
                        text = "Registering as $role Account",
                        color = Color.White,
                        fontWeight = FontWeight.Bold,
                        fontSize = 15.sp
                    )
                }
            }

            // Section 1: Business Information
            Text(
                text = "လုပ်ငန်း/ဆိုင်အချက်အလက်။",
                fontSize = 14.sp,
                fontWeight = FontWeight.Bold,
                color = Color.Gray,
                modifier = Modifier.padding(bottom = 8.dp)
            )

            Card(
                colors = CardDefaults.cardColors(containerColor = Color.White),
                shape = RoundedCornerShape(16.dp),
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(bottom = 16.dp)
            ) {
                Column(modifier = Modifier.padding(16.dp)) {
                    // Username
                    OutlinedTextField(
                        value = username,
                        onValueChange = { viewModel.registerUsername.value = it },
                        label = { Text("အသုံးပြုသူအမည်* (Username)") },
                        modifier = Modifier.fillMaxWidth(),
                        singleLine = true
                    )
                    Spacer(modifier = Modifier.height(12.dp))

                    // Business Name
                    OutlinedTextField(
                        value = bName,
                        onValueChange = { viewModel.registerBusinessName.value = it },
                        label = { Text("လုပ်ငန်း/ဆိုင်အမည်* (Business Name)") },
                        modifier = Modifier.fillMaxWidth(),
                        singleLine = true
                    )
                    Spacer(modifier = Modifier.height(12.dp))

                    // Business Type
                    OutlinedTextField(
                        value = bType,
                        onValueChange = { viewModel.registerBusinessType.value = it },
                        label = { Text("လုပ်ငန်း/ဆိုင်အမျိုးအစား* (Business Type)") },
                        modifier = Modifier.fillMaxWidth(),
                        singleLine = true
                    )
                    Spacer(modifier = Modifier.height(12.dp))

                    // Address
                    OutlinedTextField(
                        value = address,
                        onValueChange = { viewModel.registerAddress.value = it },
                        label = { Text("လိပ်စာ (Address)") },
                        modifier = Modifier.fillMaxWidth(),
                        singleLine = true
                    )
                }
            }

            // Section 2: Account Details
            Text(
                text = "အကောင့်အချက်အလက်။",
                fontSize = 14.sp,
                fontWeight = FontWeight.Bold,
                color = Color.Gray,
                modifier = Modifier.padding(bottom = 8.dp)
            )

            Card(
                colors = CardDefaults.cardColors(containerColor = Color.White),
                shape = RoundedCornerShape(16.dp),
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(bottom = 24.dp)
            ) {
                Column(modifier = Modifier.padding(16.dp)) {
                    // Phone Number
                    OutlinedTextField(
                        value = phone,
                        onValueChange = { viewModel.registerPhone.value = it },
                        label = { Text("ဖုန်းနံပါတ်* (Phone Number)") },
                        placeholder = { Text("09xxxxxxxxx") },
                        modifier = Modifier.fillMaxWidth(),
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Phone),
                        singleLine = true
                    )
                    Spacer(modifier = Modifier.height(12.dp))

                    // Password
                    OutlinedTextField(
                        value = password,
                        onValueChange = { viewModel.registerPassword.value = it },
                        label = { Text("Password*") },
                        visualTransformation = if (isPasswordVisible) VisualTransformation.None else PasswordVisualTransformation(),
                        trailingIcon = {
                            IconButton(onClick = { isPasswordVisible = !isPasswordVisible }) {
                                Icon(
                                    imageVector = if (isPasswordVisible) Icons.Filled.Visibility else Icons.Filled.VisibilityOff,
                                    contentDescription = "Toggle Password Visibility",
                                    tint = BrandPurple
                                )
                            }
                        },
                        modifier = Modifier.fillMaxWidth(),
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Password),
                        singleLine = true
                    )
                    Spacer(modifier = Modifier.height(12.dp))

                    // Retype Password
                    OutlinedTextField(
                        value = retypePassword,
                        onValueChange = { viewModel.registerRetypePassword.value = it },
                        label = { Text("Retype Password*") },
                        visualTransformation = if (isRetypePasswordVisible) VisualTransformation.None else PasswordVisualTransformation(),
                        trailingIcon = {
                            IconButton(onClick = { isRetypePasswordVisible = !isRetypePasswordVisible }) {
                                Icon(
                                    imageVector = if (isRetypePasswordVisible) Icons.Filled.Visibility else Icons.Filled.VisibilityOff,
                                    contentDescription = "Toggle Retype Password Visibility",
                                    tint = BrandPurple
                                )
                            }
                        },
                        modifier = Modifier.fillMaxWidth(),
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Password),
                        singleLine = true
                    )
                }
            }

            // Terms Accept label
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(bottom = 24.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Icon(
                    imageVector = Icons.Filled.CheckCircle,
                    contentDescription = "Accepted",
                    tint = BrandPurple,
                    modifier = Modifier.size(20.dp)
                )
                Spacer(modifier = Modifier.width(8.dp))
                Text(
                    text = "စည်းကမ်းနှင့်သတ်မှတ်ချက်များကို သဘောတူညီပြီးဖြစ်ပါသည်။",
                    fontSize = 12.sp,
                    color = Color.DarkGray
                )
            }

            if (errorMessage != null) {
                Text(
                    text = errorMessage!!,
                    color = Color.Red,
                    fontSize = 13.sp,
                    fontWeight = FontWeight.Bold,
                    modifier = Modifier.padding(bottom = 16.dp)
                )
            }

            // REGISTER BUTTON
            Button(
                onClick = {
                    if (isSubmitting) return@Button
                    val trimmedPhone = phone.trim()
                    val trimmedUser = username.trim()
                    val trimmedBName = bName.trim()

                    if (trimmedUser.isEmpty() || trimmedBName.isEmpty() || trimmedPhone.isEmpty() || password.isEmpty()) {
                        errorMessage = "လိုအပ်သော အချက်အလက်များ အားလုံး ဖြည့်စွက်ပါ (Please fill all required fields)"
                    } else if (!trimmedPhone.startsWith("09")) {
                        errorMessage = "ဖုန်းနံပါတ်သည် 09 နှင့် စရပါမည် (Phone number must start with 09)"
                    } else if (trimmedPhone.length < 9) {
                        errorMessage = "ဖုန်းနံပါတ် မှန်ကန်စွာ ဖြည့်စွက်ပါ (Invalid phone number format)"
                    } else if (isPasswordWeak(password)) {
                        errorMessage = "Password သည် လွယ်လွန်းပါသည် (Password is too simple. Minimum 6 characters required, avoid patterns like 123456)"
                    } else if (password != retypePassword) {
                        errorMessage = "Password နှစ်ခု မတူညီပါ (Passwords do not match)"
                    } else {
                        isSubmitting = true
                        scope.launch {
                            val existingAcc = viewModel.getLocalAccountByPhone(trimmedPhone)
                            if (existingAcc != null) {
                                errorMessage = "ဤဖုန်းနံပါတ်ဖြင့် အကောင့်ပြုလုပ်ပြီးသားဖြစ်ပါသည် (This phone number is already registered)"
                                isSubmitting = false
                            } else {
                                errorMessage = null
                                navController.navigate("loading")
                                isSubmitting = false
                            }
                        }
                    }
                },
                enabled = !isSubmitting,
                modifier = Modifier
                    .fillMaxWidth()
                    .height(52.dp)
                    .testTag("register_button"),
                colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                shape = RoundedCornerShape(12.dp)
            ) {
                if (isSubmitting) {
                    CircularProgressIndicator(color = Color.White, modifier = Modifier.size(24.dp), strokeWidth = 2.dp)
                } else {
                    Text("REGISTER", fontSize = 16.sp, fontWeight = FontWeight.Bold, color = Color.White)
                }
            }
        }
    }
}

// 4. PROGRESS LOADING SCREEN WITH 'Successfully Finished' EXTREME POLISH
@Composable
fun LoadingScreen(navController: NavController, viewModel: POSViewModel) {
    val context = androidx.compose.ui.platform.LocalContext.current
    val progress by viewModel.registrationProgress.collectAsState()
    val status by viewModel.registrationStatus.collectAsState()

    LaunchedEffect(Unit) {
        viewModel.runRegistration(context) {
            navController.navigate("waiting_activation") {
                popUpTo("login") { inclusive = true }
            }
        }
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(LightBg),
        contentAlignment = Alignment.Center
    ) {
        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            modifier = Modifier.padding(32.dp)
        ) {
            // Centered Brand Logo
            SASLogo(modifier = Modifier.padding(bottom = 48.dp), size = 100.dp)

            // Animated Circular Progress or Custom UI
            Box(
                contentAlignment = Alignment.Center,
                modifier = Modifier.size(120.dp)
            ) {
                CircularProgressIndicator(
                    progress = progress,
                    modifier = Modifier.size(120.dp),
                    color = BrandPurple,
                    strokeWidth = 8.dp,
                    trackColor = Color.LightGray
                )

                Text(
                    text = "${(progress * 100).toInt()}%",
                    fontSize = 24.sp,
                    fontWeight = FontWeight.Bold,
                    color = BrandPurple
                )
            }

            Spacer(modifier = Modifier.height(32.dp))

            // Animated Status Text
            AnimatedContent(
                targetState = status,
                transitionSpec = {
                    fadeIn(animationSpec = tween(220)) togetherWith fadeOut(animationSpec = tween(90))
                },
                label = "statusAnimation"
            ) { targetStatus ->
                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                    if (targetStatus == "Successfully Finished") {
                        Icon(
                            imageVector = Icons.Filled.Check,
                            contentDescription = "Success",
                            tint = Color(0xFF4CAF50),
                            modifier = Modifier
                                .size(48.dp)
                                .padding(bottom = 8.dp)
                        )
                    }
                    Text(
                        text = targetStatus,
                        fontSize = 18.sp,
                        fontWeight = FontWeight.Bold,
                        color = if (targetStatus == "Successfully Finished") Color(0xFF4CAF50) else BrandPurple,
                        textAlign = TextAlign.Center
                    )
                }
            }
        }
    }
}

// WAITING ACTIVATION SCREEN
@Composable
fun WaitingActivationScreen(navController: NavController, viewModel: POSViewModel) {
    val context = androidx.compose.ui.platform.LocalContext.current
    val currentUser by viewModel.currentUser.collectAsState()
    val accounts by viewModel.allAccounts.collectAsState()
    val registerPhoneState by viewModel.registerPhone.collectAsState()
    val sharedPrefs = remember { context.getSharedPreferences("pos_prefs", android.content.Context.MODE_PRIVATE) }
    
    var phoneNo by remember { mutableStateOf("") }
    LaunchedEffect(currentUser, accounts, registerPhoneState) {
        var p = currentUser?.phoneNo
        if (p.isNullOrEmpty()) {
            p = sharedPrefs.getString("logged_in_phone", "")
        }
        if (p.isNullOrEmpty()) {
            p = sharedPrefs.getString("last_registered_phone", "")
        }
        if (p.isNullOrEmpty()) {
            p = registerPhoneState
        }
        if (p.isNullOrEmpty() && accounts.isNotEmpty()) {
            p = accounts.lastOrNull()?.phoneNo
        }
        phoneNo = p ?: ""
    }
    val deviceId = remember { viewModel.getDeviceId(context) }
    val scope = rememberCoroutineScope()

    var isChecking by remember { mutableStateOf(false) }
    var statusMessage by remember { mutableStateOf("") }
    var showNoInternetDialog by remember { mutableStateOf(false) }

    if (showNoInternetDialog) {
        AlertDialog(
            onDismissRequest = { showNoInternetDialog = false },
            title = { Text("အင်တာနက် မရှိပါ", fontWeight = FontWeight.Bold) },
            text = { Text("အကောင့် အခြေအနေ စစ်ဆေးရန်အတွက် အင်တာနက် ဖွင့်ပေးပါ။") },
            confirmButton = {
                Button(onClick = { showNoInternetDialog = false }) {
                    Text("OK")
                }
            }
        )
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(LightBg)
            .padding(24.dp),
        contentAlignment = Alignment.Center
    ) {
        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            modifier = Modifier
                .fillMaxWidth()
                .verticalScroll(rememberScrollState())
        ) {
            Icon(
                imageVector = Icons.Filled.Lock,
                contentDescription = "Waiting Activation",
                tint = Color(0xFFD32F2F),
                modifier = Modifier.size(72.dp)
            )

            Spacer(modifier = Modifier.height(16.dp))

            Text(
                text = "Waiting Activation",
                fontWeight = FontWeight.Bold,
                fontSize = 24.sp,
                color = AppTextColor
            )

            Spacer(modifier = Modifier.height(8.dp))

            Text(
                text = "အကောင့်ဖွင့်ရန် စောင့်ဆိုင်းနေပါသည်",
                fontWeight = FontWeight.Medium,
                fontSize = 16.sp,
                color = Color.Gray
            )

            Spacer(modifier = Modifier.height(24.dp))

            Card(
                colors = CardDefaults.cardColors(containerColor = Color.White),
                shape = RoundedCornerShape(16.dp),
                elevation = CardDefaults.cardElevation(2.dp),
                modifier = Modifier.fillMaxWidth()
            ) {
                Column(modifier = Modifier.padding(20.dp)) {
                    Text(
                        text = "အကောင့် အချက်အလက်များ",
                        fontWeight = FontWeight.Bold,
                        fontSize = 16.sp,
                        color = BrandPurple,
                        modifier = Modifier.padding(bottom = 12.dp)
                    )

                    HorizontalDivider(color = Color(0xFFEEEEEE), modifier = Modifier.padding(bottom = 12.dp))

                    Row(
                        modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Text("Phone No:", color = Color.Gray, fontSize = 14.sp)
                        Text(if (phoneNo.isNotEmpty()) phoneNo else "N/A", fontWeight = FontWeight.Bold, fontSize = 14.sp)
                    }

                    Row(
                        modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Text("Device ID:", color = Color.Gray, fontSize = 14.sp)
                        Text(if (deviceId.length > 12) deviceId.take(12) + "..." else deviceId, fontWeight = FontWeight.Bold, fontSize = 13.sp, color = Color(0xFF1565C0))
                    }

                    Row(
                        modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text("Status:", color = Color.Gray, fontSize = 14.sp)
                        Surface(
                            color = Color(0xFFFFEBEE),
                            shape = RoundedCornerShape(8.dp)
                        ) {
                            Text(
                                text = "OFF (မဖွင့်ရသေးပါ)",
                                color = Color(0xFFC62828),
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                modifier = Modifier.padding(horizontal = 10.dp, vertical = 4.dp)
                            )
                        }
                    }
                }
            }

            Spacer(modifier = Modifier.height(20.dp))

            Text(
                text = "လူကြီးမင်း၏ အကောင့်ကို Admin မှ စစ်ဆေးပြီး Status 'ON' ပေးမှသာ POS စနစ်ကို အသုံးပြုနိုင်မည်ဖြစ်ပါသည်။",
                fontSize = 13.sp,
                color = Color.DarkGray,
                textAlign = TextAlign.Center,
                modifier = Modifier.padding(horizontal = 8.dp)
            )

            if (statusMessage.isNotEmpty()) {
                Spacer(modifier = Modifier.height(12.dp))
                Text(
                    text = statusMessage,
                    color = Color.Red,
                    fontSize = 14.sp,
                    fontWeight = FontWeight.Medium,
                    textAlign = TextAlign.Center
                )
            }

            Spacer(modifier = Modifier.height(28.dp))

            // Activate Button
            Button(
                onClick = {
                    if (!viewModel.isInternetAvailable(context)) {
                        showNoInternetDialog = true
                        return@Button
                    }
                    scope.launch {
                        isChecking = true
                        statusMessage = ""
                        val (isActive, msg) = viewModel.checkUserActivationStatus(context, phoneNo)
                        isChecking = false
                        val localAccount = viewModel.getLocalAccountByPhone(phoneNo)
                        val currentDeviceId = viewModel.getDeviceId(context)
                        val isAccessAllowed = viewModel.checkAccessAuthorization(
                            serverIsActive = isActive,
                            localAccount = localAccount,
                            currentDeviceId = currentDeviceId
                        )
                        if (isAccessAllowed) {
                            val todayStr = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.getDefault()).format(java.util.Date())
                            sharedPrefs.edit().putString("last_checked_date", todayStr).apply()
                            navController.navigate("dashboard") {
                                popUpTo("splash") { inclusive = true }
                            }
                        } else {
                            statusMessage = msg.ifEmpty { "ဒီဖုန်းနံပါတ်သည် အခြား Device တွင် Register ပြုလုပ်ထားပါသည် (Device ID မတူညီပါ)" }
                        }
                    }
                },
                enabled = !isChecking,
                modifier = Modifier
                    .fillMaxWidth()
                    .height(50.dp),
                colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                shape = RoundedCornerShape(12.dp)
            ) {
                if (isChecking) {
                    CircularProgressIndicator(color = Color.White, modifier = Modifier.size(24.dp), strokeWidth = 2.dp)
                } else {
                    Text("ACTIVATE / စစ်ဆေးမည်", fontSize = 16.sp, fontWeight = FontWeight.Bold, color = Color.White)
                }
            }

            Spacer(modifier = Modifier.height(12.dp))

            OutlinedButton(
                onClick = {
                    sharedPrefs.edit().remove("logged_in_phone").apply()
                    navController.navigate("login") {
                        popUpTo("splash") { inclusive = true }
                    }
                },
                modifier = Modifier
                    .fillMaxWidth()
                    .height(50.dp),
                shape = RoundedCornerShape(12.dp)
            ) {
                Text("အကောင့် ထွက်မည် (Logout)", fontSize = 14.sp, fontWeight = FontWeight.Bold, color = Color.Gray)
            }
        }
    }
}

// POS MENU GRID ITEM UTILITY
data class PosMenuItem(
    val title: String,
    val icon: ImageVector,
    val route: String? = null,
    val action: (() -> Unit)? = null,
    val color: Color = BrandPurple
)

data class DailyStat(
    val dateStr: String,
    val dayName: String,
    val totalAmount: Double,
    val voucherCount: Int
)

// 5. MAIN POS DASHBOARD SCREEN
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun DashboardScreen(navController: NavController, viewModel: POSViewModel) {
    val context = androidx.compose.ui.platform.LocalContext.current
    val currentUser by viewModel.currentUser.collectAsState()
    val isOfflineSaved by viewModel.isOfflineSaved.collectAsState()
    val isUploading by viewModel.isUploading.collectAsState()
    val allVouchers by viewModel.allVouchers.collectAsState()
    val scope = rememberCoroutineScope()
    val drawerState = rememberDrawerState(initialValue = DrawerValue.Closed)

    // 7-day sales calculation for current month (static weekly chunks: 01 to 07, 07 to 13, 13 to 19, 19 to 25, 25 to end)
    val sevenDaysStats = remember(allVouchers) {
        val now = java.util.Calendar.getInstance()
        val currentYear = now.get(java.util.Calendar.YEAR)
        val currentMonth = now.get(java.util.Calendar.MONTH)
        val todayDayOfMonth = now.get(java.util.Calendar.DAY_OF_MONTH)
        val maxDaysInMonth = now.getActualMaximum(java.util.Calendar.DAY_OF_MONTH)

        val startDay = when {
            todayDayOfMonth < 7 -> 1
            todayDayOfMonth < 13 -> 7
            todayDayOfMonth < 19 -> 13
            todayDayOfMonth < 25 -> 19
            else -> 25
        }
        val endDay = (startDay + 6).coerceAtMost(maxDaysInMonth)

        val sdfDate = java.text.SimpleDateFormat("dd/MM", java.util.Locale.US)
        val sdfDay = java.text.SimpleDateFormat("EEE", java.util.Locale.US)

        (startDay..endDay).map { day ->
            val dayCal = java.util.Calendar.getInstance()
            dayCal.set(java.util.Calendar.YEAR, currentYear)
            dayCal.set(java.util.Calendar.MONTH, currentMonth)
            dayCal.set(java.util.Calendar.DAY_OF_MONTH, day)

            dayCal.set(java.util.Calendar.HOUR_OF_DAY, 0)
            dayCal.set(java.util.Calendar.MINUTE, 0)
            dayCal.set(java.util.Calendar.SECOND, 0)
            dayCal.set(java.util.Calendar.MILLISECOND, 0)
            val startMs = dayCal.timeInMillis

            dayCal.set(java.util.Calendar.HOUR_OF_DAY, 23)
            dayCal.set(java.util.Calendar.MINUTE, 59)
            dayCal.set(java.util.Calendar.SECOND, 59)
            dayCal.set(java.util.Calendar.MILLISECOND, 999)
            val endMs = dayCal.timeInMillis

            val dayVouchers = allVouchers.filter { v ->
                !v.isPurchase && v.timestamp in startMs..endMs
            }

            DailyStat(
                dateStr = sdfDate.format(dayCal.time),
                dayName = sdfDay.format(dayCal.time),
                totalAmount = dayVouchers.sumOf { it.totalAmount },
                voucherCount = dayVouchers.size
            )
        }
    }

