@Composable
fun HeroBannerCard(
    modifier: Modifier = Modifier,
    currentUser: com.example.data.UserAccount?,
    startDateLabel: String,
    endDateLabel: String,
    weeklyStats: List<DailyStat>
) {
    val maxSales = weeklyStats.maxOfOrNull { it.totalAmount }?.takeIf { it > 0 } ?: 1.0
    val barRatios = weeklyStats.map { (it.totalAmount / maxSales).toFloat().coerceIn(0.12f, 1.0f) }

    Card(
        modifier = modifier,
        shape = RoundedCornerShape(20.dp),
        colors = CardDefaults.cardColors(containerColor = Color.White),
        border = BorderStroke(1.dp, Color(0xFFF0EBF8)),
        elevation = CardDefaults.cardElevation(defaultElevation = 1.dp)
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(16.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.SpaceBetween
        ) {
            Column(modifier = Modifier.weight(1f)) {
                Text(
                    text = "Hello, ${currentUser?.username ?: "sdf"} 👋",
                    fontSize = 13.sp,
                    color = Color(0xFF757575),
                    fontWeight = FontWeight.Medium
                )
                Spacer(modifier = Modifier.height(2.dp))
                Text(
                    text = "UN Mobile POS",
                    fontSize = 20.sp,
                    fontWeight = FontWeight.Bold,
                    color = Color(0xFF1E1035)
                )
                Spacer(modifier = Modifier.height(4.dp))
                Text(
                    text = "သင့်၏လုပ်ငန်းကို လွယ်ကူမြန်ဆန်စွာ စီမံခန့်ခွဲပါ။",
                    fontSize = 12.sp,
                    color = Color(0xFF616161)
                )
            }

            Spacer(modifier = Modifier.width(12.dp))

            // Chart Illustration Box with Dynamic Data
            Box(
                modifier = Modifier
                    .width(115.dp)
                    .height(85.dp)
                    .background(Color.White, shape = RoundedCornerShape(16.dp))
                    .border(BorderStroke(1.dp, Color(0xFFEDE7F6)), shape = RoundedCornerShape(16.dp))
                    .padding(8.dp)
            ) {
                Column(modifier = Modifier.fillMaxSize()) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Row(horizontalArrangement = Arrangement.spacedBy(3.dp)) {
                            Box(modifier = Modifier.size(5.dp).background(Color(0xFFFF5252), CircleShape))
                            Box(modifier = Modifier.size(5.dp).background(Color(0xFFFFB74D), CircleShape))
                            Box(modifier = Modifier.size(5.dp).background(Color(0xFF66BB6A), CircleShape))
                        }
                        val rangeLabel = if (startDateLabel == endDateLabel) startDateLabel else "$startDateLabel-$endDateLabel"
                        Text(
                            text = rangeLabel,
                            fontSize = 8.sp,
                            color = Color(0xFF757575),
                            fontWeight = FontWeight.Medium
                        )
                    }

                    Spacer(modifier = Modifier.height(6.dp))

                    Canvas(modifier = Modifier.fillMaxSize()) {
                        val barCount = barRatios.size
                        val availableWidth = size.width - 8.dp.toPx()
                        val barWidth = (availableWidth / (barCount * 1.5f)).coerceIn(3.dp.toPx(), 10.dp.toPx())
                        val barSpacing = if (barCount > 1) (availableWidth - (barWidth * barCount)) / (barCount - 1) else 0f
                        val purpleLight = Color(0xFFD1C4E9)
                        val purpleDark = Color(0xFF5E35B1)

                        var startX = 4.dp.toPx()
                        val points = mutableListOf<androidx.compose.ui.geometry.Offset>()

                        barRatios.forEach { hRatio ->
                            val barHeight = (size.height - 2.dp.toPx()) * hRatio
                            val topY = size.height - barHeight
                            drawRoundRect(
                                color = purpleLight,
                                topLeft = androidx.compose.ui.geometry.Offset(startX, topY),
                                size = androidx.compose.ui.geometry.Size(barWidth, barHeight),
                                cornerRadius = androidx.compose.ui.geometry.CornerRadius(3.dp.toPx())
                            )
                            points.add(androidx.compose.ui.geometry.Offset(startX + barWidth / 2, topY))
                            startX += barWidth + barSpacing
                        }

                        if (points.size > 1) {
                            val path = androidx.compose.ui.graphics.Path().apply {
                                moveTo(points[0].x, points[0].y)
                                for (i in 1 until points.size) {
                                    lineTo(points[i].x, points[i].y)
                                }
                            }
                            drawPath(
                                path = path,
                                color = purpleDark,
                                style = androidx.compose.ui.graphics.drawscope.Stroke(width = 2.dp.toPx(), cap = androidx.compose.ui.graphics.StrokeCap.Round)
                            )
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun DashboardSection(
    title: String,
    items: List<PosMenuItem>,
    navController: NavController,
    columns: Int = 4
) {
    Column {
        Row(
            verticalAlignment = Alignment.CenterVertically,
            modifier = Modifier.padding(start = 2.dp, bottom = 10.dp)
        ) {
            Box(
                modifier = Modifier
                    .width(4.dp)
                    .height(18.dp)
                    .background(Color(0xFF5E35B1), shape = RoundedCornerShape(2.dp))
            )
            Spacer(modifier = Modifier.width(8.dp))
            Text(
                text = title,
                fontSize = 16.sp,
                fontWeight = FontWeight.Bold,
                color = Color(0xFF1E1035)
            )
        }

        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
            items.chunked(columns).forEach { rowItems ->
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    rowItems.forEach { item ->
                        Card(
                            colors = CardDefaults.cardColors(containerColor = Color.White),
                            shape = RoundedCornerShape(16.dp),
                            border = BorderStroke(1.dp, Color(0xFFF0EBF8)),
                            elevation = CardDefaults.cardElevation(defaultElevation = 1.dp),
                            modifier = Modifier
                                .weight(1f)
                                .clickable {
                                    if (item.route != null) {
                                        navController.navigate(item.route)
                                    } else {
                                        item.action?.invoke()
                                    }
                                }
                        ) {
                            Column(
                                horizontalAlignment = Alignment.CenterHorizontally,
                                verticalArrangement = Arrangement.Center,
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(vertical = 10.dp, horizontal = 2.dp)
                            ) {
                                val softBg = item.color.copy(alpha = 0.12f)
                                Box(
                                    modifier = Modifier
                                        .size(42.dp)
                                        .background(softBg, shape = CircleShape),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        imageVector = item.icon,
                                        contentDescription = item.title,
                                        tint = item.color,
                                        modifier = Modifier.size(20.dp)
                                    )
                                }

                                Spacer(modifier = Modifier.height(6.dp))

                                Text(
                                    text = item.title,
                                    fontSize = 11.sp,
                                    fontWeight = FontWeight.Medium,
                                    color = Color(0xFF2C2C38),
                                    textAlign = TextAlign.Center,
                                    maxLines = 2,
                                    minLines = 2,
                                    lineHeight = 13.sp,
                                    modifier = Modifier.padding(horizontal = 2.dp)
                                )

                                Spacer(modifier = Modifier.height(6.dp))

                                Box(
                                    modifier = Modifier
                                        .width(20.dp)
                                        .height(3.dp)
                                        .background(item.color, shape = RoundedCornerShape(2.dp))
                                )
                            }
                        }
                    }
                    if (rowItems.size < columns) {
                        repeat(columns - rowItems.size) {
                            Spacer(modifier = Modifier.weight(1f))
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun DashboardListSection(
    title: String,
    items: List<PosMenuItem>,
    navController: NavController,
    columns: Int = 3
) {
    Column {
        Row(
            verticalAlignment = Alignment.CenterVertically,
            modifier = Modifier.padding(start = 2.dp, bottom = 10.dp)
        ) {
            Box(
                modifier = Modifier
                    .width(4.dp)
                    .height(18.dp)
                    .background(Color(0xFF5E35B1), shape = RoundedCornerShape(2.dp))
            )
            Spacer(modifier = Modifier.width(8.dp))
            Text(
                text = title,
                fontSize = 16.sp,
                fontWeight = FontWeight.Bold,
                color = Color(0xFF1E1035)
            )
        }

        Card(
            colors = CardDefaults.cardColors(containerColor = Color.White),
            shape = RoundedCornerShape(20.dp),
            border = BorderStroke(1.dp, Color(0xFFF0EBF8)),
            elevation = CardDefaults.cardElevation(defaultElevation = 1.dp),
            modifier = Modifier.fillMaxWidth()
        ) {
            Column(modifier = Modifier.padding(8.dp)) {
                items.chunked(columns).forEach { rowItems ->
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceEvenly
                    ) {
                        rowItems.forEach { item ->
                            Column(
                                horizontalAlignment = Alignment.CenterHorizontally,
                                verticalArrangement = Arrangement.SpaceBetween,
                                modifier = Modifier
                                    .weight(1f)
                                    .padding(vertical = 10.dp, horizontal = 2.dp)
                                    .clickable {
                                        if (item.route != null) {
                                            navController.navigate(item.route)
                                        } else {
                                            item.action?.invoke()
                                        }
                                    }
                            ) {
                                val softBg = item.color.copy(alpha = 0.12f)
                                Box(
                                    modifier = Modifier
                                        .size(42.dp)
                                        .background(softBg, shape = CircleShape),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        imageVector = item.icon,
                                        contentDescription = item.title,
                                        tint = item.color,
                                        modifier = Modifier.size(20.dp)
                                    )
                                }

                                Spacer(modifier = Modifier.height(6.dp))

                                Text(
                                    text = item.title,
                                    fontSize = 11.sp,
                                    fontWeight = FontWeight.Medium,
                                    color = Color(0xFF2C2C38),
                                    textAlign = TextAlign.Center,
                                    maxLines = 2,
                                    minLines = 2,
                                    lineHeight = 13.sp,
                                    modifier = Modifier.padding(horizontal = 2.dp)
                                )

                                Spacer(modifier = Modifier.height(8.dp))

                                Box(
                                    modifier = Modifier
                                        .size(26.dp)
                                        .border(BorderStroke(1.dp, Color(0xFF7E57C2).copy(alpha = 0.4f)), shape = CircleShape)
                                        .background(Color.White, shape = CircleShape),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        imageVector = Icons.Filled.ChevronRight,
                                        contentDescription = "Go",
                                        tint = Color(0xFF5E35B1),
                                        modifier = Modifier.size(16.dp)
                                    )
                                }
                            }
                        }
                        if (rowItems.size < columns) {
                            repeat(columns - rowItems.size) {
                                Spacer(modifier = Modifier.weight(1f))
                            }
                        }
                    }
                }
            }
        }
    }
}

// 5.5 USER PROFILE SCREEN
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun UserProfileScreen(navController: NavController, viewModel: POSViewModel) {
    val context = androidx.compose.ui.platform.LocalContext.current
    val currentUser by viewModel.currentUser.collectAsState()
    val allAccounts by viewModel.allAccounts.collectAsState()
    val sharedPrefs = remember { context.getSharedPreferences("pos_prefs", android.content.Context.MODE_PRIVATE) }

    var showChangePasswordScreen by remember { mutableStateOf(false) }
    var newPassword by remember { mutableStateOf("") }
    var confirmPassword by remember { mutableStateOf("") }
    var newPasswordVisible by remember { mutableStateOf(false) }
    var confirmPasswordVisible by remember { mutableStateOf(false) }
    var passwordError by remember { mutableStateOf("") }
    var isUpdatingPassword by remember { mutableStateOf(false) }
    val coroutineScope = rememberCoroutineScope()

    val profile = remember(currentUser, allAccounts) {
        if (currentUser != null && !currentUser?.phoneNo.isNullOrEmpty()) {
            currentUser
        } else {
            var loggedPhone = sharedPrefs.getString("logged_in_phone", "")
            if (loggedPhone.isNullOrEmpty()) {
                loggedPhone = sharedPrefs.getString("last_registered_phone", "")
            }
            if (!loggedPhone.isNullOrEmpty()) {
                allAccounts.firstOrNull { it.phoneNo == loggedPhone } ?: allAccounts.lastOrNull()
            } else {
                allAccounts.lastOrNull()
            }
        }
    }

    if (showChangePasswordScreen) {
        androidx.activity.compose.BackHandler {
            if (!isUpdatingPassword) {
                showChangePasswordScreen = false
                newPassword = ""
                confirmPassword = ""
                passwordError = ""
            }
        }

        Scaffold(
            topBar = {
                TopAppBar(
                    title = { Text("စကားဝှက် ပြောင်းလဲရန်", fontWeight = FontWeight.Bold, fontSize = 18.sp, color = AppTextColor) },
                    navigationIcon = {
                        IconButton(onClick = {
                            if (!isUpdatingPassword) {
                                showChangePasswordScreen = false
                                newPassword = ""
                                confirmPassword = ""
                                passwordError = ""
                            }
                        }) {
                            Icon(imageVector = Icons.Filled.ArrowBack, contentDescription = "Back", tint = AppTextColor)
                        }
                    },
                    colors = TopAppBarDefaults.topAppBarColors(containerColor = AppSurfaceColor)
                )
            },
            containerColor = LightBg
        ) { innerPadding ->
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(innerPadding)
                    .padding(20.dp),
                verticalArrangement = Arrangement.SpaceBetween
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .verticalScroll(rememberScrollState())
                ) {
                    if (passwordError.isNotEmpty()) {
                        Card(
                            colors = CardDefaults.cardColors(containerColor = Color(0xFFFFEBEE)),
                            shape = RoundedCornerShape(8.dp),
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(bottom = 16.dp)
                        ) {
                            Text(
                                text = passwordError,
                                color = Color.Red,
                                fontSize = 13.sp,
                                modifier = Modifier.padding(12.dp)
                            )
                        }
                    }

                    // New Password
                    Text("New Password (စကားဝှက်သစ်)", fontSize = 14.sp, fontWeight = FontWeight.SemiBold, color = AppTextColor)
                    Spacer(modifier = Modifier.height(6.dp))
                    OutlinedTextField(
                        value = newPassword,
                        onValueChange = {
                            newPassword = it
                            passwordError = ""
                        },
                        modifier = Modifier.fillMaxWidth(),
                        singleLine = true,
                        placeholder = { Text("New Password ရိုက်ထည့်ပါ") },
                        visualTransformation = if (newPasswordVisible) androidx.compose.ui.text.input.VisualTransformation.None else androidx.compose.ui.text.input.PasswordVisualTransformation(),
                        trailingIcon = {
                            IconButton(onClick = { newPasswordVisible = !newPasswordVisible }) {
                                Icon(
                                    imageVector = if (newPasswordVisible) Icons.Filled.Visibility else Icons.Filled.VisibilityOff,
                                    contentDescription = "Toggle password visibility"
                                )
                            }
                        },
                        shape = RoundedCornerShape(12.dp)
                    )

                    Spacer(modifier = Modifier.height(16.dp))

                    // Confirm Password
                    Text("Confirm Password (စကားဝှက် အတည်ပြုရန်)", fontSize = 14.sp, fontWeight = FontWeight.SemiBold, color = AppTextColor)
                    Spacer(modifier = Modifier.height(6.dp))
                    OutlinedTextField(
                        value = confirmPassword,
                        onValueChange = {
                            confirmPassword = it
                            passwordError = ""
                        },
                        modifier = Modifier.fillMaxWidth(),
                        singleLine = true,
                        placeholder = { Text("Confirm Password ထပ်မံရိုက်ထည့်ပါ") },
                        visualTransformation = if (confirmPasswordVisible) androidx.compose.ui.text.input.VisualTransformation.None else androidx.compose.ui.text.input.PasswordVisualTransformation(),
                        trailingIcon = {
                            IconButton(onClick = { confirmPasswordVisible = !confirmPasswordVisible }) {
                                Icon(
                                    imageVector = if (confirmPasswordVisible) Icons.Filled.Visibility else Icons.Filled.VisibilityOff,
                                    contentDescription = "Toggle password visibility"
                                )
                            }
                        },
                        shape = RoundedCornerShape(12.dp)
                    )
                }

                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(bottom = 16.dp)
                ) {
                    Button(
                        onClick = {
                            if (newPassword.isBlank()) {
                                passwordError = "New Password (စကားဝှက်သစ်) ရိုက်ထည့်ပါ"
                                return@Button
                            }
                            if (confirmPassword.isBlank()) {
                                passwordError = "Confirm Password (စကားဝှက် အတည်ပြုရန်) ရိုက်ထည့်ပါ"
                                return@Button
                            }
                            if (newPassword != confirmPassword) {
                                passwordError = "စကားဝှက် နှစ်ခု မတူညီပါ"
                                return@Button
                            }

                            val userPhone = profile?.phoneNo ?: ""
                            if (userPhone.isEmpty()) {
                                passwordError = "ဖုန်းနံပါတ် ရှာမတွေ့ပါ"
                                return@Button
                            }

                            isUpdatingPassword = true
                            coroutineScope.launch {
                                val (success, msg) = viewModel.updatePasswordDirectly(userPhone, newPassword)
                                isUpdatingPassword = false
                                if (success) {
                                    android.widget.Toast.makeText(context, "စကားဝှက် ပြောင်းလဲပြီးပါပြီ", android.widget.Toast.LENGTH_SHORT).show()
                                    showChangePasswordScreen = false
                                    newPassword = ""
                                    confirmPassword = ""
                                    passwordError = ""
                                } else {
                                    passwordError = msg
                                }
                            }
                        },
                        enabled = !isUpdatingPassword,
                        colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                        shape = RoundedCornerShape(12.dp),
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(50.dp)
                    ) {
                        if (isUpdatingPassword) {
                            CircularProgressIndicator(color = Color.White, modifier = Modifier.size(24.dp), strokeWidth = 2.dp)
                        } else {
                            Text("Confirm (အတည်ပြုမည်)", fontWeight = FontWeight.Bold, fontSize = 16.sp, color = Color.White)
                        }
                    }
                }
            }
        }
    } else {
        Scaffold(
            topBar = {
                TopAppBar(
                    title = { Text("အကောင့် အချက်အလက်များ", fontWeight = FontWeight.Bold, fontSize = 18.sp, color = AppTextColor) },
                    navigationIcon = {
                        IconButton(onClick = { navController.popBackStack() }) {
                            Icon(imageVector = Icons.Filled.ArrowBack, contentDescription = "Back", tint = AppTextColor)
                        }
                    },
                    actions = {
                        IconButton(onClick = {
                            passwordError = ""
                            newPassword = ""
                            confirmPassword = ""
                            showChangePasswordScreen = true
                        }) {
                            Text(
                                text = "***",
                                fontWeight = FontWeight.ExtraBold,
                                fontSize = 22.sp,
                                color = AppTextColor
                            )
                        }
                    },
                    colors = TopAppBarDefaults.topAppBarColors(containerColor = AppSurfaceColor)
                )
            },
            containerColor = LightBg
        ) { innerPadding ->
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(innerPadding)
                    .verticalScroll(rememberScrollState())
                    .padding(16.dp),
                verticalArrangement = Arrangement.SpaceBetween
            ) {
                Card(
                    colors = CardDefaults.cardColors(containerColor = AppSurfaceColor),
                    shape = RoundedCornerShape(16.dp),
                    elevation = CardDefaults.cardElevation(2.dp),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Column(
                        modifier = Modifier.padding(16.dp)
                    ) {
                        // profile is derived above

                        @Composable
                        fun DetailItem(label: String, value: String) {
                            Column(modifier = Modifier.fillMaxWidth().padding(vertical = 6.dp)) {
                                Text(text = label, fontSize = 12.sp, color = AppSubTextColor)
                                Spacer(modifier = Modifier.height(2.dp))
                                Text(text = value, fontSize = 16.sp, fontWeight = FontWeight.SemiBold, color = AppTextColor)
                            }
                        }

                        DetailItem(label = "လုပ်ငန်း/ဆိုင်အမည်", value = profile?.businessName?.ifEmpty { "N/A" } ?: "N/A")
                        HorizontalDivider(color = if (globalIsDarkTheme) Color(0xFF33323B) else Color(0xFFEEEEEE), modifier = Modifier.padding(vertical = 4.dp))

                        DetailItem(label = "လုပ်ငန်း/ဆိုင်အမျိုးအစား", value = profile?.businessType?.ifEmpty { "N/A" } ?: "N/A")
                        HorizontalDivider(color = if (globalIsDarkTheme) Color(0xFF33323B) else Color(0xFFEEEEEE), modifier = Modifier.padding(vertical = 4.dp))

                        DetailItem(label = "လိပ်စာ", value = profile?.address?.ifEmpty { "N/A" } ?: "N/A")
                        HorizontalDivider(color = if (globalIsDarkTheme) Color(0xFF33323B) else Color(0xFFEEEEEE), modifier = Modifier.padding(vertical = 4.dp))

                        DetailItem(label = "အသုံးပြုသူအမည်", value = profile?.username?.ifEmpty { "N/A" } ?: "N/A")
                        HorizontalDivider(color = if (globalIsDarkTheme) Color(0xFF33323B) else Color(0xFFEEEEEE), modifier = Modifier.padding(vertical = 4.dp))

                        DetailItem(label = "အကောင့်အမျိုးအစား", value = profile?.role?.ifEmpty { "ADMIN" } ?: "ADMIN")
                        HorizontalDivider(color = if (globalIsDarkTheme) Color(0xFF33323B) else Color(0xFFEEEEEE), modifier = Modifier.padding(vertical = 4.dp))

                        DetailItem(label = "ဖုန်းနံပါတ်", value = profile?.phoneNo?.ifEmpty { "N/A" } ?: "N/A")
                    }
                }

                Spacer(modifier = Modifier.height(24.dp))

                Button(
                    onClick = {
                        viewModel.logout()
                        navController.navigate("login") {
                            popUpTo("dashboard") { inclusive = true }
                        }
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFFFEBEE)),
                    shape = RoundedCornerShape(12.dp),
                    modifier = Modifier.fillMaxWidth().height(48.dp)
                ) {
                    Icon(imageVector = Icons.Filled.ExitToApp, contentDescription = "Logout", tint = Color.Red, modifier = Modifier.size(20.dp))
                    Spacer(modifier = Modifier.width(8.dp))
                    Text("Logout (အကောင့်ထွက်မည်)", color = Color.Red, fontWeight = FontWeight.Bold, fontSize = 15.sp)
                }
            }
        }
    }
}

// 6. ACCOUNTS SCREEN
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AccountsScreen(navController: NavController, viewModel: POSViewModel) {
    val context = androidx.compose.ui.platform.LocalContext.current
    val accounts by viewModel.allAccounts.collectAsState()
    val currentUser by viewModel.currentUser.collectAsState()
    val sharedPrefs = remember { context.getSharedPreferences("pos_prefs", android.content.Context.MODE_PRIVATE) }

    val currentAcc = remember(currentUser, accounts) {
        if (currentUser != null && !currentUser?.phoneNo.isNullOrEmpty()) {
            currentUser
        } else {
            var loggedPhone = sharedPrefs.getString("logged_in_phone", "")
            if (loggedPhone.isNullOrEmpty()) {
                loggedPhone = sharedPrefs.getString("last_registered_phone", "")
            }
            if (!loggedPhone.isNullOrEmpty()) {
                accounts.firstOrNull { it.phoneNo == loggedPhone } ?: accounts.lastOrNull()
            } else {
                accounts.lastOrNull()
            }
        }
    }

    val displayAccounts = remember(accounts, currentAcc) {
        if (accounts.isNotEmpty()) {
            val loggedPhone = currentAcc?.phoneNo
            if (!loggedPhone.isNullOrEmpty()) {
                val filtered = accounts.filter { account ->
                    account.phoneNo == loggedPhone || (account.role == "CASHIER" && (currentAcc?.role == "ADMIN" || account.businessName == currentAcc?.businessName))
                }
                if (filtered.isNotEmpty()) filtered else accounts
            } else {
                accounts
            }
        } else if (currentAcc != null) {
            listOf(currentAcc!!)
        } else {
            emptyList()
        }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Accounts", fontWeight = FontWeight.Bold) },
                navigationIcon = {
                    IconButton(onClick = { navController.popBackStack() }) {
                        Icon(imageVector = Icons.Filled.ArrowBack, contentDescription = "Back")
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.White)
            )
        }
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .background(LightBg)
                .padding(innerPadding)
                .padding(16.dp)
        ) {
            // Accounts List Title
            Text(
                text = "${displayAccounts.size} Account(s) In Shop",
                fontWeight = FontWeight.Bold,
                fontSize = 14.sp,
                color = Color.Gray,
                modifier = Modifier.padding(bottom = 8.dp)
            )

            LazyColumn(modifier = Modifier.fillMaxWidth()) {
                items(displayAccounts) { account ->
                    Card(
                        colors = CardDefaults.cardColors(containerColor = Color.White),
                        shape = RoundedCornerShape(12.dp),
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 4.dp),
                        elevation = CardDefaults.cardElevation(1.dp)
                    ) {
                        Row(
                            modifier = Modifier.padding(16.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(40.dp)
                                    .background(LightBg, shape = CircleShape),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = if (account.role == "ADMIN") Icons.Filled.AdminPanelSettings else Icons.Filled.Person,
                                    contentDescription = "User",
                                    tint = BrandPurple
                                )
                            }
                            Spacer(modifier = Modifier.width(16.dp))
                            Column(modifier = Modifier.weight(1f)) {
                                Text(account.username, fontWeight = FontWeight.Bold, fontSize = 15.sp)
                                Text(account.role, color = BrandPurple, fontWeight = FontWeight.Bold, fontSize = 11.sp)
                            }
                            Text(account.phoneNo, color = Color.Gray, fontSize = 13.sp)
                        }
                    }
                }
            }
        }
    }
}

// 7. PRODUCTS LIST SCREEN
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun ProductsListScreen(navController: NavController, viewModel: POSViewModel) {
    val products by viewModel.allProducts.collectAsState()
    val groups by viewModel.allGroups.collectAsState()
    val stockReportMode by viewModel.stockReportMode.collectAsState()
    val selectedCurrency by viewModel.selectedCurrency.collectAsState()
    val numberFormat = remember { NumberFormat.getNumberInstance(Locale.US) }

    val screenTitle = when (stockReportMode) {
        "PURCHASE_VALUE" -> "ကုန်ပစ္စည်းလက်ကျန်အဝယ်တန်ဖိုး"
        "SELLING_VALUE" -> "ကုန်ပစ္စည်းလက်ကျန်ရောင်းတန်ဖိုး"
        "STOCK_REPORT" -> "ကုန်ပစ္စည်းလက်ကျန်"
        else -> "ကုန်စည်များ"
    }

    var selectedGroup by remember { mutableStateOf<String?>(null) }
    var sortBy by remember { mutableStateOf("0-9") }
    var filterAvailability by remember { mutableStateOf<String?>(null) }
    var filterNearExpired by remember { mutableStateOf(false) }
    var showFilterSheet by remember { mutableStateOf(false) }
    val isGridView by viewModel.isProductGridView.collectAsState()

    var showQuantityDrawer by remember { mutableStateOf(false) }
    var selectedProductForQty by remember { mutableStateOf<Product?>(null) }

    var isSearching by remember { mutableStateOf(false) }
    var searchQuery by remember { mutableStateOf("") }

    // Filter & Sort Products
    val displayedProducts = remember(products, selectedGroup, sortBy, filterAvailability, filterNearExpired, searchQuery) {
        var list = if (selectedGroup == null) {
            products
        } else {
            products.filter { prod ->
                prod.groupName.split(",").map { it.trim() }.any { g -> g.equals(selectedGroup, ignoreCase = true) }
            }
        }

        if (searchQuery.isNotEmpty()) {
            list = list.filter {
                it.name.contains(searchQuery, ignoreCase = true) ||
                it.barcode.contains(searchQuery, ignoreCase = true) ||
                it.groupName.contains(searchQuery, ignoreCase = true)
            }
        }

        // Availability filter
        if (filterAvailability == "available") {
            list = list.filter { !it.trackStock || it.quantity > 0 }
        } else if (filterAvailability == "unavailable") {
            list = list.filter { it.trackStock && it.quantity <= 0 }
        }

        // Sort
        list = when (sortBy) {
            "A-Z" -> list.sortedBy { it.name.lowercase() }
            "Z-A" -> list.sortedByDescending { it.name.lowercase() }
            "0-9" -> list.sortedBy { it.id }
            "9-0" -> list.sortedByDescending { it.id }
            else -> list
        }

        list
    }

    if (showQuantityDrawer && selectedProductForQty != null) {
        var qtyString by remember(selectedProductForQty) { mutableStateOf(selectedProductForQty!!.quantity.toString()) }
        
        ModalBottomSheet(
            onDismissRequest = {
                showQuantityDrawer = false
                selectedProductForQty = null
            },
            containerColor = Color.White,
            shape = RoundedCornerShape(topStart = 24.dp, topEnd = 24.dp)
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .navigationBarsPadding()
                    .padding(horizontal = 24.dp)
                    .padding(bottom = 32.dp),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                Text(
                    text = "လက်ကျန်အရေအတွက် ပြင်ဆင်ရန်",
                    fontSize = 18.sp,
                    fontWeight = FontWeight.Bold,
                    color = Color.Black
                )
                
                Spacer(modifier = Modifier.height(8.dp))
                
                Text(
                    text = selectedProductForQty!!.name,
                    fontSize = 15.sp,
                    color = Color.Gray,
                    textAlign = TextAlign.Center
                )
                
                Spacer(modifier = Modifier.height(24.dp))
                
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.Center,
                    modifier = Modifier.fillMaxWidth()
                ) {
                    IconButton(
                        onClick = {
                            val currentVal = qtyString.toIntOrNull() ?: 0
                            if (currentVal > 0) {
                                qtyString = (currentVal - 1).toString()
                            }
                        },
                        modifier = Modifier
                            .size(48.dp)
                            .background(Color(0xFFEDE7F6), shape = CircleShape)
                    ) {
                        Icon(imageVector = Icons.Filled.Remove, contentDescription = "Decrease", tint = BrandPurple)
                    }
                    
                    Spacer(modifier = Modifier.width(24.dp))
                    
                    OutlinedTextField(
                        value = qtyString,
                        onValueChange = { newValue ->
                            if (newValue.all { it.isDigit() || newValue.isEmpty() }) {
                                qtyString = newValue
                            }
                        },
                        singleLine = true,
                        textStyle = androidx.compose.ui.text.TextStyle(
                            fontSize = 20.sp,
                            fontWeight = FontWeight.Bold,
                            textAlign = TextAlign.Center
                        ),
                        keyboardOptions = androidx.compose.foundation.text.KeyboardOptions(
                            keyboardType = androidx.compose.ui.text.input.KeyboardType.Number
                        ),
                        modifier = Modifier.width(120.dp)
                    )
                    
                    Spacer(modifier = Modifier.width(24.dp))
                    
                    IconButton(
                        onClick = {
                            val currentVal = qtyString.toIntOrNull() ?: 0
                            qtyString = (currentVal + 1).toString()
                        },
                        modifier = Modifier
                            .size(48.dp)
                            .background(Color(0xFFEDE7F6), shape = CircleShape)
                    ) {
                        Icon(imageVector = Icons.Filled.Add, contentDescription = "Increase", tint = BrandPurple)
                    }
                }
                
                Spacer(modifier = Modifier.height(24.dp))
                
                Button(
                    onClick = {
                        val newQty = qtyString.toIntOrNull() ?: 0
                        viewModel.updateProductStock(selectedProductForQty!!.id, newQty)
                        showQuantityDrawer = false
                        selectedProductForQty = null
                    },
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(50.dp),
                    colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Text("ပြင်ဆင်မည်", color = Color.White, fontSize = 16.sp, fontWeight = FontWeight.Bold)
                }
            }
        }
    }

    Scaffold(
        topBar = {
            if (isSearching) {
                TopAppBar(
                    title = {
                        OutlinedTextField(
                            value = searchQuery,
                            onValueChange = { searchQuery = it },
                            placeholder = { Text("Search", color = Color.LightGray) },
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(vertical = 4.dp),
                            singleLine = true,
                            colors = OutlinedTextFieldDefaults.colors(
                                focusedContainerColor = Color.Transparent,
                                unfocusedContainerColor = Color.Transparent,
                                disabledContainerColor = Color.Transparent,
                                focusedBorderColor = Color.Transparent,
                                unfocusedBorderColor = Color.Transparent,
                            ),
                            trailingIcon = {
                                if (searchQuery.isNotEmpty()) {
                                    IconButton(onClick = { searchQuery = "" }) {
                                        Icon(imageVector = Icons.Filled.Close, contentDescription = "Clear", tint = Color.Gray)
                                    }
                                }
                            }
                        )
                    },
                    navigationIcon = {
                        IconButton(onClick = { 
                            isSearching = false
                            searchQuery = ""
                        }) {
                            Icon(imageVector = Icons.Filled.Close, contentDescription = "Close Search", tint = AppTextColor)
                        }
                    },
                    colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.White)
                )
            } else {
                TopAppBar(
                    title = { Text(screenTitle, fontWeight = FontWeight.Bold) },
                    navigationIcon = {
                        IconButton(onClick = { navController.popBackStack() }) {
                            Icon(imageVector = Icons.Filled.ArrowBack, contentDescription = "Back")
                        }
                    },
                    actions = {
                        IconButton(onClick = { isSearching = true }) {
                            Icon(imageVector = Icons.Filled.Search, contentDescription = "Search", tint = BrandPurple)
                        }
                        IconButton(onClick = { viewModel.isProductGridView.value = !isGridView }) {
                            Icon(
                                imageVector = if (isGridView) Icons.Filled.List else Icons.Filled.GridView,
                                contentDescription = "Toggle Grid/List",
                                tint = BrandPurple
                            )
                        }
                        IconButton(onClick = { showFilterSheet = true }) {
                            Icon(imageVector = Icons.Filled.FilterList, contentDescription = "Filter", tint = BrandPurple)
                        }
                    },
                    colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.White)
                )
            }
        },
        floatingActionButton = {
            if (stockReportMode == "DEFAULT") {
                FloatingActionButton(
                    onClick = {
                        viewModel.editingProduct.value = null
                        viewModel.clearProductForm()
                        navController.navigate("add_product")
                    },
                    containerColor = BrandPurple,
                    contentColor = Color.White
                ) {
                    Icon(imageVector = Icons.Filled.Add, contentDescription = "Add Product")
                }
            }
        },
        bottomBar = {
            if (stockReportMode == "PURCHASE_VALUE" || stockReportMode == "SELLING_VALUE") {
                val totalPurchaseValue = products.sumOf { it.purchasePrice * it.quantity }
                val totalSalesValue = products.sumOf { it.sellingPrice * it.quantity }
                Card(
                    colors = CardDefaults.cardColors(containerColor = Color(0xFFFDFBFE)),
                    shape = RoundedCornerShape(topStart = 16.dp, topEnd = 16.dp),
                    border = BorderStroke(1.dp, Color(0xFFEDE7F6)),
                    modifier = Modifier.fillMaxWidth(),
                    elevation = CardDefaults.cardElevation(defaultElevation = 8.dp)
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .navigationBarsPadding()
                            .padding(16.dp),
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        if (stockReportMode == "PURCHASE_VALUE") {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween
                            ) {
                                Text(
                                    text = "လက်ကျန်စုစုပေါင်း အဝယ်တန်ဖိုး-",
                                    fontSize = 14.sp,
                                    color = Color.Gray,
                                    fontWeight = FontWeight.Medium
                                )
                                Text(
                                    text = "${numberFormat.format(totalPurchaseValue.toInt())} $selectedCurrency",
                                    fontSize = 15.sp,
                                    color = Color.Black,
                                    fontWeight = FontWeight.Bold
                                )
                            }
                        }
                        if (stockReportMode == "SELLING_VALUE") {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween
                            ) {
                                Text(
                                    text = "လက်ကျန်စုစုပေါင်း အရောင်းတန်ဖိုး-",
                                    fontSize = 14.sp,
                                    color = Color.Gray,
                                    fontWeight = FontWeight.Medium
                                )
                                Text(
                                    text = "${numberFormat.format(totalSalesValue.toInt())} $selectedCurrency",
                                    fontSize = 15.sp,
                                    color = BrandPurple,
                                    fontWeight = FontWeight.Bold
                                )
                            }
                        }
                    }
                }
            }
        }
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .background(LightBg)
                .padding(innerPadding)
        ) {
            // Horizontally Scrollable Category Chips
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .horizontalScroll(rememberScrollState())
                    .padding(horizontal = 16.dp, vertical = 12.dp),
                horizontalArrangement = Arrangement.spacedBy(8.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                // All Chip
                val allLabel = if (products.isEmpty()) {
                    "အားလုံး(0)"
                } else {
                    "အားလုံး(${products.size} item${if (products.size > 1) "s" else ""})"
                }
                val isAllSelected = selectedGroup == null
                Button(
                    onClick = { selectedGroup = null },
                    colors = ButtonDefaults.buttonColors(
                        containerColor = if (isAllSelected) BrandPurple else Color(0xFFE8E5F3),
                        contentColor = if (isAllSelected) Color.White else BrandPurple
                    ),
                    shape = RoundedCornerShape(12.dp),
                    contentPadding = PaddingValues(horizontal = 16.dp, vertical = 8.dp),
                    modifier = Modifier.height(38.dp)
                ) {
                    Text(allLabel, fontWeight = FontWeight.Bold, fontSize = 13.sp)
                }

                // Group Chips - split joined category names into clean individual categories
                val groupNamesFromDb = groups.map { it.name.trim() }.flatMap { it.split(",") }.map { it.trim() }.filter { it.isNotEmpty() }
                val groupNamesFromProducts = products.flatMap { it.groupName.split(",") }.map { it.trim() }.filter { it.isNotEmpty() }
                val displayGroups = (groupNamesFromDb + groupNamesFromProducts).distinct()

                displayGroups.forEach { groupName ->
                    val isSelected = selectedGroup == groupName
                    val count = products.count { prod ->
                        prod.groupName.split(",").map { it.trim() }.any { g -> g.equals(groupName, ignoreCase = true) }
                    }
                    val label = if (count > 0) "$groupName($count item${if (count > 1) "s" else ""})" else groupName

                    Button(
                        onClick = { selectedGroup = groupName },
                        colors = ButtonDefaults.buttonColors(
                            containerColor = if (isSelected) BrandPurple else Color(0xFFE8E5F3),
                            contentColor = if (isSelected) Color.White else BrandPurple
                        ),
                        shape = RoundedCornerShape(12.dp),
                        contentPadding = PaddingValues(horizontal = 16.dp, vertical = 8.dp),
                        modifier = Modifier.height(38.dp)
                    ) {
                        Text(label, fontWeight = FontWeight.Bold, fontSize = 13.sp)
                    }
                }
            }

            // Products Content Area
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .weight(1f)
            ) {
                if (displayedProducts.isEmpty()) {
                    Column(
                        modifier = Modifier
                            .fillMaxSize()
                            .padding(24.dp),
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.Center
                    ) {
                        Box(
                            modifier = Modifier
                                .size(100.dp)
                                .background(Color(0xFFE8E5F3), shape = CircleShape),
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(
                                imageVector = Icons.Filled.Inventory,
                                contentDescription = "No Products",
                                tint = BrandPurple,
                                modifier = Modifier.size(48.dp)
                            )
                        }
                        Spacer(modifier = Modifier.height(24.dp))
                        Text(
                            text = "No Products Found",
                            fontWeight = FontWeight.Bold,
                            fontSize = 18.sp,
                            color = Color.DarkGray
                        )
                    }
                } else {
                    if (isGridView) {
                        LazyVerticalGrid(
                            columns = GridCells.Adaptive(minSize = 105.dp),
                            modifier = Modifier
                                .fillMaxSize()
                                .padding(horizontal = 6.dp)
                        ) {
                            items(displayedProducts) { product ->
                                Card(
                                    colors = CardDefaults.cardColors(containerColor = Color.White),
                                    shape = RoundedCornerShape(12.dp),
                                    border = BorderStroke(1.dp, Color(0xFFE2DDF0)),
                                    elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .height(130.dp)
                                        .padding(3.dp)
                                        .clickable(enabled = stockReportMode == "DEFAULT" || stockReportMode == "STOCK_REPORT") {
                                            if (stockReportMode == "DEFAULT") {
                                                viewModel.loadProductToForm(product)
                                                navController.navigate("add_product")
                                            } else if (stockReportMode == "STOCK_REPORT") {
                                                selectedProductForQty = product
                                                showQuantityDrawer = true
                                            }
                                        }
                                ) {
                                    Box(modifier = Modifier.fillMaxSize()) {
                                        if (product.imageUri.isNotEmpty()) {
                                            coil.compose.AsyncImage(
                                                model = product.imageUri,
                                                contentDescription = product.name,
                                                modifier = Modifier.fillMaxSize(),
                                                contentScale = androidx.compose.ui.layout.ContentScale.Crop
                                            )
                                        } else {
                                            Box(
                                                modifier = Modifier
                                                    .fillMaxSize()
                                                    .background(Color(0xFFD3C2FE)),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Filled.Inventory,
                                                    contentDescription = "Product",
                                                    tint = Color(0xFF533B78),
                                                    modifier = Modifier.size(32.dp)
                                                )
                                            }
                                        }

                                        // Dark purple bottom bar as in screenshot showing item name only
                                        Box(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .align(Alignment.BottomCenter)
                                                .background(Color(0xFF533B78))
                                                .padding(horizontal = 4.dp, vertical = 6.dp),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Text(
                                                text = product.name,
                                                fontWeight = FontWeight.Medium,
                                                fontSize = 12.sp,
                                                color = Color.White,
                                                textAlign = TextAlign.Center,
                                                maxLines = 1,
                                                overflow = TextOverflow.Ellipsis
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    } else {
                        LazyColumn(
                            modifier = Modifier
                                .fillMaxSize()
                                .padding(horizontal = 16.dp)
                        ) {
                            items(displayedProducts) { product ->
                                Card(
                                    colors = CardDefaults.cardColors(containerColor = Color.White),
                                    shape = RoundedCornerShape(16.dp),
                                    border = BorderStroke(1.dp, Color(0xFFE2DDF0)),
                                    elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(vertical = 6.dp)
                                        .clickable(enabled = stockReportMode == "DEFAULT" || stockReportMode == "STOCK_REPORT") {
                                            if (stockReportMode == "DEFAULT") {
                                                viewModel.loadProductToForm(product)
                                                navController.navigate("add_product")
                                            } else if (stockReportMode == "STOCK_REPORT") {
                                                selectedProductForQty = product
                                                showQuantityDrawer = true
                                            }
                                        }
                                ) {
                                    Row(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .padding(16.dp),
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.SpaceBetween
                                    ) {
                                        Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.weight(1f)) {
                                            Box(
                                                modifier = Modifier
                                                    .size(44.dp)
                                                    .background(Color(0xFFEDE7F6), shape = RoundedCornerShape(12.dp)),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Filled.Inbox,
                                                    contentDescription = "Product",
                                                    tint = Color(0xFF5E35B1),
                                                    modifier = Modifier.size(22.dp)
                                                )
                                            }
                                            Spacer(modifier = Modifier.width(12.dp))
                                            Column {
                                                Row(verticalAlignment = Alignment.CenterVertically) {
                                                    val dotColor = when (product.id % 3) {
                                                        0L -> Color(0xFFFFB74D)
                                                        1L -> Color(0xFF7E57C2)
                                                        else -> Color(0xFF66BB6A)
                                                    }
                                                    Box(
                                                        modifier = Modifier
                                                            .size(8.dp)
                                                            .background(dotColor, shape = CircleShape)
                                                    )
                                                    Spacer(modifier = Modifier.width(6.dp))
                                                    Text(
                                                        text = product.name,
                                                        fontWeight = FontWeight.Bold,
                                                        fontSize = 16.sp,
                                                        color = Color(0xFF1C1B1F)
                                                    )
                                                }
                                                Spacer(modifier = Modifier.height(4.dp))
                                                
                                                when (stockReportMode) {
                                                    "PURCHASE_VALUE" -> {
                                                        Text(
                                                            text = "${product.quantity} ${product.unit} x ${numberFormat.format(product.purchasePrice.toInt())} $selectedCurrency",
                                                            fontSize = 13.sp,
                                                            color = Color(0xFF757575)
                                                        )
                                                    }
                                                    "SELLING_VALUE" -> {
                                                        Text(
                                                            text = "${product.quantity} ${product.unit} x ${numberFormat.format(product.sellingPrice.toInt())} $selectedCurrency",
                                                            fontSize = 13.sp,
                                                            color = Color(0xFF757575)
                                                        )
                                                    }
                                                    else -> {
                                                        if (stockReportMode == "DEFAULT") {
                                                            Text(
                                                                text = "လက်ကျန်: ${product.quantity}",
                                                                fontSize = 13.sp,
                                                                color = Color(0xFF757575)
                                                            )
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                        Row(verticalAlignment = Alignment.CenterVertically) {
                                            if (stockReportMode != "DEFAULT") {
                                                Column(horizontalAlignment = Alignment.End) {
                                                    val displayText = when (stockReportMode) {
                                                        "PURCHASE_VALUE" -> {
                                                            val displayPrice = product.quantity * product.purchasePrice.toInt()
                                                            "${numberFormat.format(displayPrice)} $selectedCurrency"
                                                        }
                                                        "SELLING_VALUE" -> {
                                                            val displayPrice = product.quantity * product.sellingPrice.toInt()
                                                            "${numberFormat.format(displayPrice)} $selectedCurrency"
                                                        }
                                                        else -> {
                                                            "${product.quantity} ${product.unit}"
                                                        }
                                                    }
                                                    val textColor = if (stockReportMode == "PURCHASE_VALUE") Color.Black else Color(0xFF1E1035)
                                                    Text(
                                                        text = displayText,
                                                        fontWeight = FontWeight.Bold,
                                                        color = textColor,
                                                        fontSize = 15.sp
                                                    )
                                                }
                                            }
                                            if (stockReportMode == "DEFAULT") {
                                                Text(
                                                    text = "${numberFormat.format(product.sellingPrice.toInt())} $selectedCurrency",
                                                    fontWeight = FontWeight.Bold,
                                                    fontSize = 16.sp,
                                                    color = Color(0xFF1E1035)
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }


        // Beautiful filter bottom sheet exactly as in the video
        if (showFilterSheet) {
            ModalBottomSheet(
                onDismissRequest = { showFilterSheet = false },
                containerColor = Color.White,
                shape = RoundedCornerShape(topStart = 24.dp, topEnd = 24.dp)
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 24.dp, vertical = 16.dp)
                ) {
                    // Title: Sort By
                    Text("Sort By", fontWeight = FontWeight.Bold, fontSize = 16.sp, color = Color.Gray)
                    Spacer(modifier = Modifier.height(12.dp))

                    // Buttons arranged in a clean grid
                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(12.dp)) {
                        Button(
                            onClick = { sortBy = "A-Z" },
                            modifier = Modifier.weight(1f).height(50.dp),
                            shape = RoundedCornerShape(12.dp),
                            colors = ButtonDefaults.buttonColors(
                                containerColor = if (sortBy == "A-Z") BrandPurple else Color(0xFFF3F0F8),
                                contentColor = if (sortBy == "A-Z") Color.White else Color.Gray
                            )
                        ) {
                            Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                Text("A-Z", fontWeight = FontWeight.Bold, fontSize = 14.sp)
                                Text("အမည်", fontSize = 10.sp)
                            }
                        }
                        Button(
                            onClick = { sortBy = "Z-A" },
                            modifier = Modifier.weight(1f).height(50.dp),
                            shape = RoundedCornerShape(12.dp),
                            colors = ButtonDefaults.buttonColors(
                                containerColor = if (sortBy == "Z-A") BrandPurple else Color(0xFFF3F0F8),
                                contentColor = if (sortBy == "Z-A") Color.White else Color.Gray
                            )
                        ) {
                            Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                Text("Z-A", fontWeight = FontWeight.Bold, fontSize = 14.sp)
                                Text("အမည်", fontSize = 10.sp)
                            }
                        }
                    }
                    Spacer(modifier = Modifier.height(12.dp))
                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(12.dp)) {
                        Button(
                            onClick = { sortBy = "0-9" },
                            modifier = Modifier.weight(1f).height(50.dp),
                            shape = RoundedCornerShape(12.dp),
                            colors = ButtonDefaults.buttonColors(
                                containerColor = if (sortBy == "0-9") BrandPurple else Color(0xFFF3F0F8),
                                contentColor = if (sortBy == "0-9") Color.White else Color.Gray
                            )
                        ) {
                            Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                Text("0-9", fontWeight = FontWeight.Bold, fontSize = 14.sp)
                                Text("အချိန်", fontSize = 10.sp)
                            }
                        }
                        Button(
                            onClick = { sortBy = "9-0" },
                            modifier = Modifier.weight(1f).height(50.dp),
                            shape = RoundedCornerShape(12.dp),
                            colors = ButtonDefaults.buttonColors(
                                containerColor = if (sortBy == "9-0") BrandPurple else Color(0xFFF3F0F8),
                                contentColor = if (sortBy == "9-0") Color.White else Color.Gray
                            )
                        ) {
                            Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                Text("9-0", fontWeight = FontWeight.Bold, fontSize = 14.sp)
                                Text("အချိန်", fontSize = 10.sp)
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(24.dp))
                }
            }
        }
    }

// Helper for Video Style Fields
@Composable
fun CustomProductField(
    label: String,
    modifier: Modifier = Modifier,
    content: @Composable () -> Unit
) {
    Column(modifier = modifier.fillMaxWidth()) {
        Text(
            text = label,
            fontWeight = FontWeight.Bold,
            color = Color(0xFF4A4A4A),
            fontSize = 14.sp,
            modifier = Modifier.padding(start = 4.dp, bottom = 6.dp)
        )
        content()
    }
}

// 8. ADD PRODUCT SCREEN
@OptIn(ExperimentalMaterial3Api::class, ExperimentalLayoutApi::class)
@Composable
fun AddProductScreen(navController: NavController, viewModel: POSViewModel) {
    val name by viewModel.prodName.collectAsState()
    val group by viewModel.prodGroup.collectAsState()
    val purchasePrice by viewModel.prodPurchasePrice.collectAsState()
    val sellingPrice by viewModel.prodSellingPrice.collectAsState()
    val unit by viewModel.prodUnit.collectAsState()
    val note by viewModel.prodNote.collectAsState()
    val trackStock by viewModel.prodTrackStock.collectAsState()
    val barcode by viewModel.prodBarcode.collectAsState()
    val qty by viewModel.prodQty.collectAsState()
    val alertQty by viewModel.prodAlertQty.collectAsState()

    val editingProduct by viewModel.editingProduct.collectAsState()
    var showDeleteConfirm by remember { mutableStateOf(false) }
    var groupExpanded by remember { mutableStateOf(false) }
    var unitExpanded by remember { mutableStateOf(false) }
    val groupsList by viewModel.allGroups.collectAsState()
    val unitsList by viewModel.allUnits.collectAsState()

    val context = LocalContext.current

    val prodImageUri by viewModel.prodImageUri.collectAsState()

    val productPhotoLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.GetContent()
    ) { uri: android.net.Uri? ->
        if (uri != null) {
            try {
                context.contentResolver.takePersistableUriPermission(
                    uri,
                    android.content.Intent.FLAG_GRANT_READ_URI_PERMISSION
                )
            } catch (e: Exception) {
                // Ignore
            }
            viewModel.prodImageUri.value = uri.toString()
        }
    }



    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text(if (editingProduct == null) "ကုန်စည်အသစ်" else "ပြင်ရန်", fontWeight = FontWeight.Bold) },
                navigationIcon = {
                    IconButton(onClick = { navController.popBackStack() }) {
                        Icon(imageVector = Icons.Filled.ArrowBack, contentDescription = "Back")
                    }
                },
                actions = {
                    if (editingProduct != null) {
                        IconButton(onClick = { showDeleteConfirm = true }) {
                            Icon(imageVector = Icons.Filled.Delete, contentDescription = "Delete", tint = Color.Red)
                        }
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.White)
            )
        }
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .background(LightBg)
                .padding(innerPadding)
                .verticalScroll(rememberScrollState())
                .padding(16.dp)
        ) {
            // Basic Product Information Section
            Column(modifier = Modifier.fillMaxWidth().padding(bottom = 16.dp)) {
                Text(
                    text = "အခြေခံအချက်အလက်များ",
                    fontSize = 15.sp,
                    fontWeight = FontWeight.Bold,
                    color = BrandPurple,
                    modifier = Modifier.padding(bottom = 12.dp)
                )

                // 0. ကုန်စည် ဓာတ်ပုံ
                CustomProductField(label = "ကုန်စည် ဓာတ်ပုံ") {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Box(
                            modifier = Modifier
                                .size(90.dp)
                                .clip(RoundedCornerShape(14.dp))
                                .background(Color.White)
                                .border(1.5.dp, if (prodImageUri.isNotEmpty()) BrandPurple else Color(0xFFE0E0E0), RoundedCornerShape(14.dp))
                                .clickable { productPhotoLauncher.launch("image/*") },
                            contentAlignment = Alignment.Center
                        ) {
                            if (prodImageUri.isNotEmpty()) {
                                coil.compose.AsyncImage(
                                    model = prodImageUri,
                                    contentDescription = "Product Image",
                                    modifier = Modifier.fillMaxSize(),
                                    contentScale = androidx.compose.ui.layout.ContentScale.Crop
                                )
                            } else {
                                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                    Icon(
                                        imageVector = Icons.Filled.AddAPhoto,
                                        contentDescription = "Add Photo",
                                        tint = BrandPurple,
                                        modifier = Modifier.size(28.dp)
                                    )
                                    Spacer(modifier = Modifier.height(4.dp))
                                    Text(
                                        text = "ဓာတ်ပုံထည့်ရန်",
                                        fontSize = 11.sp,
                                        color = BrandPurple,
                                        fontWeight = FontWeight.Medium
                                    )
                                }
                            }
                        }

                        if (prodImageUri.isNotEmpty()) {
                            Spacer(modifier = Modifier.width(16.dp))
                            OutlinedButton(
                                onClick = { viewModel.prodImageUri.value = "" },
                                colors = ButtonDefaults.outlinedButtonColors(contentColor = Color.Red),
                                border = BorderStroke(1.dp, Color(0xFFFFCDD2)),
                                shape = RoundedCornerShape(10.dp)
                            ) {
                                Icon(
                                    imageVector = Icons.Filled.Delete,
                                    contentDescription = "Remove Photo",
                                    modifier = Modifier.size(16.dp)
                                )
                                Spacer(modifier = Modifier.width(4.dp))
                                Text("ဓာတ်ပုံပယ်ဖျက်မည်", fontSize = 12.sp)
                            }
                        }
                    }
                }
                Spacer(modifier = Modifier.height(16.dp))

                // 1. ကုန်စည်အမည်*
                CustomProductField(label = "ကုန်စည်အမည်*") {
                    OutlinedTextField(
                        value = name,
                        onValueChange = { viewModel.prodName.value = it },
                        modifier = Modifier
                            .fillMaxWidth()
                            .testTag("prod_name_input"),
                        singleLine = true,
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedTextColor = Color(0xFF1C1B1F),
                            unfocusedTextColor = Color(0xFF1C1B1F),
                            focusedContainerColor = Color.White,
                            unfocusedContainerColor = Color.White,
                            focusedBorderColor = BrandPurple,
                            unfocusedBorderColor = Color(0xFFE0E0E0)
                        ),
                        shape = RoundedCornerShape(12.dp)
                    )
                }
                Spacer(modifier = Modifier.height(16.dp))

                // 2. ကုန်အုပ်စု (Video Matching Chip UI)
                CustomProductField(label = "ကုန်အုပ်စု") {
                    val groupList = remember(group) {
                        group.split(",").map { it.trim() }.filter { it.isNotEmpty() }
                    }
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(Color.White, shape = RoundedCornerShape(12.dp)).border(1.dp, Color(0xFFE0E0E0), shape = RoundedCornerShape(12.dp))
                            .clickable {
                                navController.navigate("groups_list_select")
                            }
                            .padding(12.dp)
                    ) {
                        FlowRow(
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                            verticalArrangement = Arrangement.spacedBy(8.dp),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            // Selected Group Chips
                            groupList.forEach { grpName ->
                                Surface(
                                    shape = RoundedCornerShape(20.dp),
                                    color = Color.White,
                                    border = BorderStroke(1.dp, Color(0xFFD0C9E8)),
                                    modifier = Modifier.padding(2.dp)
                                ) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        modifier = Modifier.padding(horizontal = 10.dp, vertical = 6.dp)
                                    ) {
                                        Text(
                                            text = grpName,
                                            fontSize = 14.sp,
                                            fontWeight = FontWeight.Medium,
                                            color = Color(0xFF1C1B1F)
                                        )
                                        Spacer(modifier = Modifier.width(6.dp))
                                        Icon(
                                            imageVector = Icons.Filled.Close,
                                            contentDescription = "Remove $grpName",
                                            tint = Color.Gray,
                                            modifier = Modifier
                                                .size(16.dp)
                                                .clickable {
                                                    val updatedList = groupList.filter { it != grpName }
                                                    viewModel.prodGroup.value = updatedList.joinToString(", ")
                                                }
                                        )
                                    }
                                }
                            }

                            // Join Group Button (+ Join Group)
                            Surface(
                                shape = RoundedCornerShape(20.dp),
                                color = Color.White,
                                border = BorderStroke(1.dp, Color(0xFFD0C9E8)),
                                modifier = Modifier
                                    .padding(2.dp)
                                    .clickable { navController.navigate("groups_list_select") }
                            ) {
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    modifier = Modifier.padding(horizontal = 12.dp, vertical = 6.dp)
                                ) {
                                    Icon(
                                        imageVector = Icons.Filled.Add,
                                        contentDescription = "Join Group",
                                        tint = Color(0xFF4A4458),
                                        modifier = Modifier.size(18.dp)
                                    )
                                    Spacer(modifier = Modifier.width(6.dp))
                                    Text(
                                        text = "Join Group",
                                        fontSize = 14.sp,
                                        fontWeight = FontWeight.Medium,
                                        color = Color(0xFF4A4458)
                                    )
                                }
                            }
                        }
                    }
                }
                Spacer(modifier = Modifier.height(16.dp))

                // 3. ဝယ်ဈေး*
                CustomProductField(label = "ဝယ်ဈေး*") {
                    OutlinedTextField(
                        value = purchasePrice,
                        onValueChange = { viewModel.prodPurchasePrice.value = it },
                        modifier = Modifier
                            .fillMaxWidth()
                            .testTag("prod_purchase_price"),
                        singleLine = true,
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedTextColor = Color(0xFF1C1B1F),
                            unfocusedTextColor = Color(0xFF1C1B1F),
                            focusedContainerColor = Color.White,
                            unfocusedContainerColor = Color.White,
                            focusedBorderColor = BrandPurple,
                            unfocusedBorderColor = Color(0xFFE0E0E0)
                        ),
                        shape = RoundedCornerShape(12.dp)
                    )
                }
                Spacer(modifier = Modifier.height(16.dp))

                // 4. ရောင်းဈေး*
                CustomProductField(label = "ရောင်းဈေး*") {
                    OutlinedTextField(
                        value = sellingPrice,
                        onValueChange = { viewModel.prodSellingPrice.value = it },
                        modifier = Modifier
                            .fillMaxWidth()
                            .testTag("prod_selling_price"),
                        singleLine = true,
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedTextColor = Color(0xFF1C1B1F),
                            unfocusedTextColor = Color(0xFF1C1B1F),
                            focusedContainerColor = Color.White,
                            unfocusedContainerColor = Color.White,
                            focusedBorderColor = BrandPurple,
                            unfocusedBorderColor = Color(0xFFE0E0E0)
                        ),
                        shape = RoundedCornerShape(12.dp)
                    )
                }
                Spacer(modifier = Modifier.height(16.dp))

                // 5. ယူနစ် (Video Matching Selectable Container)
                CustomProductField(label = "ယူနစ်") {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(Color.White, shape = RoundedCornerShape(12.dp)).border(1.dp, Color(0xFFE0E0E0), shape = RoundedCornerShape(12.dp))
                            .clickable { navController.navigate("units_list_select") }
                            .padding(14.dp)
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(
                                text = if (unit.isEmpty()) "ယူနစ် ရွေးချယ်ပါ" else unit,
                                color = if (unit.isEmpty()) Color.Gray else Color(0xFF1C1B1F),
                                fontSize = 15.sp,
                                fontWeight = FontWeight.Medium
                            )
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                if (unit.isNotEmpty()) {
                                    IconButton(
                                        onClick = { viewModel.prodUnit.value = "" },
                                        modifier = Modifier.size(24.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Filled.Close,
                                            contentDescription = "Clear Unit",
                                            tint = Color.Gray,
                                            modifier = Modifier.size(18.dp)
                                        )
                                    }
                                    Spacer(modifier = Modifier.width(8.dp))
                                }
                                Icon(
                                    imageVector = Icons.Filled.ArrowDropDown,
                                    contentDescription = "Select Unit",
                                    tint = BrandPurple
                                )
                            }
                        }
                    }
                }
            }

            Spacer(modifier = Modifier.height(24.dp))

            // Section 2: Stock & Notes
            Column(modifier = Modifier.fillMaxWidth().padding(bottom = 24.dp)) {
                Text(
                    text = "စတော့အခြေအနေနှင့် မှတ်ချက်",
                    fontSize = 15.sp,
                    fontWeight = FontWeight.Bold,
                    color = BrandPurple,
                    modifier = Modifier.padding(bottom = 12.dp)
                )

                    // 6. မှတ်ချက်
                    CustomProductField(label = "မှတ်ချက်") {
                        OutlinedTextField(
                            value = note,
                            onValueChange = { viewModel.prodNote.value = it },
                            modifier = Modifier
                                .fillMaxWidth()
                                .testTag("prod_note"),
                            singleLine = true,
                            colors = OutlinedTextFieldDefaults.colors(
                                focusedTextColor = Color(0xFF1C1B1F),
                                unfocusedTextColor = Color(0xFF1C1B1F),
                                focusedContainerColor = Color.White,
                                unfocusedContainerColor = Color.White,
                                focusedBorderColor = Color.Transparent,
                                unfocusedBorderColor = Color.Transparent
                            ),
                            shape = RoundedCornerShape(12.dp)
                        )
                    }
                    Spacer(modifier = Modifier.height(16.dp))

                    // Track Stock Row
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 8.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Column {
                            Text("Track Stock", fontWeight = FontWeight.Bold, color = Color(0xFF1C1B1F))
                            Text("Manage stock quantities", fontSize = 12.sp, color = Color.Gray)
                        }
                        Switch(
                            checked = trackStock,
                            onCheckedChange = { viewModel.prodTrackStock.value = it },
                            colors = SwitchDefaults.colors(
                                checkedThumbColor = Color.White,
                                checkedTrackColor = BrandPurple,
                                uncheckedThumbColor = Color.Gray,
                                uncheckedTrackColor = Color.LightGray
                            )
                        )
                    }

                    if (trackStock) {
                        Spacer(modifier = Modifier.height(16.dp))

                        // 7. ဘားကုဒ်
                        CustomProductField(label = "ဘားကုဒ်") {
                            OutlinedTextField(
                                value = barcode,
                                onValueChange = { viewModel.prodBarcode.value = it },
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .testTag("prod_barcode"),
                                singleLine = true,
                                colors = OutlinedTextFieldDefaults.colors(
                                    focusedTextColor = Color(0xFF1C1B1F),
                                    unfocusedTextColor = Color(0xFF1C1B1F),
                                    focusedContainerColor = Color.White,
                                    unfocusedContainerColor = Color.White,
                                    focusedBorderColor = Color.Transparent,
                                    unfocusedBorderColor = Color.Transparent
                                ),
                                shape = RoundedCornerShape(12.dp)
                            )
                        }
                        Spacer(modifier = Modifier.height(16.dp))

                        // 8. အရေအတွက်
                        CustomProductField(label = "အရေအတွက်") {
                            OutlinedTextField(
                                value = qty,
                                onValueChange = { viewModel.prodQty.value = it },
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .testTag("prod_qty"),
                                singleLine = true,
                                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                                colors = OutlinedTextFieldDefaults.colors(
                                    focusedTextColor = Color(0xFF1C1B1F),
                                    unfocusedTextColor = Color(0xFF1C1B1F),
                                    focusedContainerColor = Color.White,
                                    unfocusedContainerColor = Color.White,
                                    focusedBorderColor = Color.Transparent,
                                    unfocusedBorderColor = Color.Transparent
                                ),
                                shape = RoundedCornerShape(12.dp)
                            )
                        }
                        Spacer(modifier = Modifier.height(16.dp))

                        // 9. သတိပေးမည့်အရေအတွက်
                        CustomProductField(label = "သတိပေးမည့်အရေအတွက်") {
                            OutlinedTextField(
                                value = alertQty,
                                onValueChange = { viewModel.prodAlertQty.value = it },
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .testTag("prod_alert_qty"),
                                singleLine = true,
                                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                                colors = OutlinedTextFieldDefaults.colors(
                                    focusedTextColor = Color(0xFF1C1B1F),
                                    unfocusedTextColor = Color(0xFF1C1B1F),
                                    focusedContainerColor = Color.White,
                                    unfocusedContainerColor = Color.White,
                                    focusedBorderColor = Color.Transparent,
                                    unfocusedBorderColor = Color.Transparent
                                ),
                                shape = RoundedCornerShape(12.dp)
                            )
                        }
                    }
                }

            Spacer(modifier = Modifier.height(8.dp))

            // SAVE Button
            Button(
                onClick = {
                    if (name.isNotEmpty() && sellingPrice.isNotEmpty()) {
                        viewModel.addProduct { savedProduct ->
                            android.widget.Toast.makeText(context, "သိမ်းပြီးပါပြီ။", android.widget.Toast.LENGTH_SHORT).show()
                            if (viewModel.isFromSalesFlow && savedProduct != null) {
                                viewModel.isFromSalesFlow = false
                            }
                            navController.popBackStack()
                        }
                    } else {
                        android.widget.Toast.makeText(context, "ကျေးဇူးပြု၍ လိုအပ်သောအချက်အလက်များ ဖြည့်စွက်ပါ", android.widget.Toast.LENGTH_SHORT).show()
                    }
                },
                modifier = Modifier
                    .fillMaxWidth()
                    .height(54.dp)
                    .testTag("save_product_button"),
                shape = RoundedCornerShape(12.dp),
                colors = ButtonDefaults.buttonColors(containerColor = BrandPurple)
            ) {
                Text(
                    text = "SAVE",
                    fontWeight = FontWeight.Bold,
                    fontSize = 16.sp,
                    color = Color.White
                )
            }
        }
    }

    if (showDeleteConfirm) {
        AlertDialog(
            onDismissRequest = { showDeleteConfirm = false },
            title = { Text("ကုန်စည်ကို ဖျက်ရန်", fontWeight = FontWeight.Bold) },
            text = { Text("ဤကုန်စည်ကို စာရင်းထဲမှ အပြီးဖျက်ပါမည်။ သေချာပါသလား?") },
            confirmButton = {
                Button(
                    onClick = {
                        editingProduct?.let {
                            viewModel.deleteProduct(it) {
                                showDeleteConfirm = false
                                android.widget.Toast.makeText(context, "ဖျက်ပြီးပါပြီ။", android.widget.Toast.LENGTH_SHORT).show()
                                navController.popBackStack()
                            }
                        }
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color.Red)
                ) {
                    Text("Delete")
                }
            },
            dismissButton = {
                TextButton(onClick = { showDeleteConfirm = false }) {
                    Text("Cancel", color = BrandPurple)
                }
            }
        )
    }
}

// 8a. GROUPS SELECT SCREEN FOR PRODUCTS
@OptIn(ExperimentalMaterial3Api::class, ExperimentalFoundationApi::class)
@Composable
fun GroupsSelectScreen(navController: NavController, viewModel: POSViewModel) {
    val groups by viewModel.allGroups.collectAsState()
    var isSearching by remember { mutableStateOf(false) }
    var searchQuery by remember { mutableStateOf("") }
    var showAddDialog by remember { mutableStateOf(false) }
    var newGroupName by remember { mutableStateOf("") }
    var showEditDialog by remember { mutableStateOf<ProductGroup?>(null) }
    var editGroupName by remember { mutableStateOf("") }
    var showDeleteConfirm by remember { mutableStateOf<ProductGroup?>(null) }

    val prodGroupState by viewModel.prodGroup.collectAsState()
    val selectedGroups = remember(prodGroupState) {
        prodGroupState.split(",")
            .map { it.trim() }
            .filter { it.isNotEmpty() }
            .toSet()
    }

    val filteredGroups = remember(groups, searchQuery) {
        if (searchQuery.isEmpty()) groups else {
            groups.filter { it.name.contains(searchQuery, ignoreCase = true) }
        }
    }

    Scaffold(
        topBar = {
            if (isSearching) {
                TopAppBar(
                    title = {
                        TextField(
                            value = searchQuery,
                            onValueChange = { searchQuery = it },
                            placeholder = { Text("ရှာဖွေရန်...", color = Color.Gray) },
                            colors = TextFieldDefaults.colors(
                                focusedContainerColor = Color.Transparent,
                                unfocusedContainerColor = Color.Transparent,
                                focusedIndicatorColor = Color.Transparent,
                                unfocusedIndicatorColor = Color.Transparent,
                                focusedTextColor = AppTextColor,
                                unfocusedTextColor = AppTextColor
                            ),
                            singleLine = true
                        )
                    },
                    navigationIcon = {
                        IconButton(onClick = {
                            isSearching = false
                            searchQuery = ""
                        }) {
                            Icon(imageVector = Icons.Filled.Close, contentDescription = "Close Search", tint = AppTextColor)
                        }
                    },
                    colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.White)
                )
            } else {
                TopAppBar(
                    title = { Text("အုပ်စုရွေးချယ်ရန်", fontWeight = FontWeight.Bold, color = AppTextColor) },
                    navigationIcon = {
                        IconButton(onClick = { navController.popBackStack() }) {
                            Icon(imageVector = Icons.Filled.ArrowBack, contentDescription = "Back", tint = AppTextColor)
                        }
                    },
                    actions = {
                        IconButton(onClick = { isSearching = true }) {
                            Icon(imageVector = Icons.Filled.Search, contentDescription = "Search", tint = BrandPurple)
                        }
                    },
                    colors = TopAppBarDefaults.topAppBarColors(
                        containerColor = Color.White,
                        navigationIconContentColor = AppTextColor,
                        titleContentColor = AppTextColor
                    )
                )
            }
        },
        floatingActionButton = {
            FloatingActionButton(
                onClick = { showAddDialog = true },
                containerColor = BrandPurple,
                contentColor = Color.White,
                shape = CircleShape
            ) {
                Icon(imageVector = Icons.Filled.Add, contentDescription = "Add Group")
            }
        }
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .background(Color.White)
                .padding(innerPadding)
        ) {
            if (filteredGroups.isEmpty()) {
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .weight(1f),
                    contentAlignment = Alignment.Center
                ) {
                    Column(
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.Center
                    ) {
                        Box(
                            modifier = Modifier
                                .size(100.dp)
                                .background(Color(0xFFE8E5F3), shape = CircleShape),
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(
                                imageVector = Icons.Filled.Folder,
                                contentDescription = "No Groups",
                                tint = BrandPurple,
                                modifier = Modifier.size(48.dp)
                            )
                        }
                        Spacer(modifier = Modifier.height(16.dp))
                        Text(
                            text = "အုပ်စုများ ရှာမတွေ့ပါ",
                            fontWeight = FontWeight.Bold,
                            fontSize = 16.sp,
                            color = Color.Gray
                        )
                    }
                }
            } else {
                LazyColumn(
                    modifier = Modifier
                        .fillMaxSize()
                        .weight(1f)
                ) {
                    items(filteredGroups) { group ->
                        val isSelected = selectedGroups.contains(group.name)
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .combinedClickable(
                                    onClick = {
                                        val updated = if (isSelected) {
                                            selectedGroups - group.name
                                        } else {
                                            selectedGroups + group.name
                                        }
                                        viewModel.prodGroup.value = updated.joinToString(", ")
                                        navController.popBackStack()
                                    },
                                    onLongClick = {
                                        showDeleteConfirm = group
                                    }
                                )
                        ) {
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(horizontal = 16.dp, vertical = 12.dp),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.SpaceBetween
                            ) {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Box(
                                        modifier = Modifier
                                            .size(40.dp)
                                            .background(if (isSelected) BrandPurple else Color(0xFFE8E5F3), shape = RoundedCornerShape(10.dp)),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Icon(
                                            imageVector = Icons.Filled.Folder,
                                            contentDescription = "Folder",
                                            tint = if (isSelected) Color.White else BrandPurple,
                                            modifier = Modifier.size(22.dp)
                                        )
                                    }
                                    Spacer(modifier = Modifier.width(16.dp))
                                    Text(
                                        text = group.name,
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 16.sp,
                                        color = AppTextColor
                                    )
                                }
                                if (isSelected) {
                                    Icon(
                                        imageVector = Icons.Filled.Check,
                                        contentDescription = "Selected",
                                        tint = BrandPurple,
                                        modifier = Modifier.size(22.dp)
                                    )
                                }
                            }
                            HorizontalDivider(
                                modifier = Modifier.padding(start = 72.dp),
                                color = Color(0xFFEEEEEE),
                                thickness = 1.dp
                            )
                        }
                    }
                }
            }

            // Edit Group Dialog
            showEditDialog?.let { group ->
                AlertDialog(
                    onDismissRequest = { showEditDialog = null },
                    title = { Text("အုပ်စုအမည် ပြင်ရန်", fontWeight = FontWeight.Bold, color = AppTextColor) },
                    text = {
                        OutlinedTextField(
                            value = editGroupName,
                            onValueChange = { editGroupName = it },
                            label = { Text("အုပ်စုအမည်") },
                            modifier = Modifier.fillMaxWidth(),
                            singleLine = true,
                            colors = OutlinedTextFieldDefaults.colors(
                                focusedTextColor = AppTextColor,
                                unfocusedTextColor = AppTextColor
                            )
                        )
                    },
                    confirmButton = {
                        Button(
                            onClick = {
                                if (editGroupName.isNotEmpty()) {
                                    val newG = editGroupName.trim()
                                    viewModel.updateProductGroup(group, newG)
                                    if (selectedGroups.contains(group.name)) {
                                        val updated = (selectedGroups - group.name) + newG
                                        viewModel.prodGroup.value = updated.joinToString(", ")
                                    }
                                    showEditDialog = null
                                }
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = BrandPurple)
                        ) {
                            Text("ပြင်မည်", color = Color.White)
                        }
                    },
                    dismissButton = {
                        TextButton(onClick = { showEditDialog = null }) {
                            Text("Cancel", color = BrandPurple)
                        }
                    }
                )
            }

            if (showAddDialog) {
                AlertDialog(
                    onDismissRequest = { showAddDialog = false },
                    title = {
                        Text(
                            text = "Add New Group",
                            fontWeight = FontWeight.Bold,
                            fontSize = 22.sp,
                            color = AppTextColor
                        )
                    },
                    text = {
                        TextField(
                            value = newGroupName,
                            onValueChange = { newGroupName = it },
                            placeholder = { Text("Group name...", color = Color.Gray) },
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(vertical = 8.dp),
                            singleLine = true,
                            colors = TextFieldDefaults.colors(
                                focusedContainerColor = Color(0xFFF1F0F5),
                                unfocusedContainerColor = Color(0xFFF1F0F5),
                                focusedIndicatorColor = Color.Transparent,
                                unfocusedIndicatorColor = Color.Transparent,
                                focusedTextColor = AppTextColor,
                                unfocusedTextColor = AppTextColor
                            ),
                            shape = RoundedCornerShape(12.dp)
                        )
                    },
                    confirmButton = {
                        Button(
                            onClick = {
                                if (newGroupName.isNotEmpty()) {
                                    val gName = newGroupName.trim()
                                    viewModel.addProductGroup(gName)
                                    val updated = selectedGroups + gName
                                    viewModel.prodGroup.value = updated.joinToString(", ")
                                    navController.popBackStack()
                                    newGroupName = ""
                                    showAddDialog = false
                                }
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                            shape = RoundedCornerShape(24.dp)
                        ) {
                            Text("SAVE", fontWeight = FontWeight.Bold, color = Color.White)
                        }
                    },
                    dismissButton = {
                        TextButton(onClick = { showAddDialog = false }) {
                            Text("Cancel", color = BrandPurple, fontWeight = FontWeight.SemiBold)
                        }
                    },
                    shape = RoundedCornerShape(24.dp),
                    containerColor = Color.White
                )
            }

            // Delete confirmation dialog
            showDeleteConfirm?.let { group ->
                AlertDialog(
                    onDismissRequest = { showDeleteConfirm = null },
                    title = { Text("ဖျက်ရန်", fontWeight = FontWeight.Bold, color = AppTextColor) },
                    text = { Text("${group.name} ဖျက်ရန်အတည်ပြုပါ။", fontSize = 15.sp, color = AppTextColor) },
                    confirmButton = {
                        Button(
                            onClick = {
                                viewModel.deleteProductGroup(group)
                                showDeleteConfirm = null
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = Color.Red)
                        ) {
                            Text("Delete", color = Color.White)
                        }
                    },
                    dismissButton = {
                        TextButton(onClick = { showDeleteConfirm = null }) {
                            Text("Cancel", color = BrandPurple)
                        }
                    }
                )
            }
        }
    }
}

// 8b. UNITS SELECT SCREEN FOR PRODUCTS
@OptIn(ExperimentalMaterial3Api::class, ExperimentalFoundationApi::class)
@Composable
fun UnitsSelectScreen(navController: NavController, viewModel: POSViewModel) {
    val units by viewModel.allUnits.collectAsState()
