                    } else {
                        LazyColumn(
                            modifier = Modifier
                                .fillMaxWidth()
                                .weight(1f)
                        ) {
                            items(unpaidVouchers) { v ->
                                Card(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(vertical = 6.dp)
                                        .clickable {
                                            viewModel.loadDraftVoucher(v)
                                            screenState = "select_products"
                                        },
                                    colors = CardDefaults.cardColors(containerColor = Color.White),
                                    shape = RoundedCornerShape(12.dp),
                                    elevation = CardDefaults.cardElevation(2.dp)
                                ) {
                                    Row(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .padding(16.dp),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Column(modifier = Modifier.weight(1f)) {
                                            Text(
                                                text = "ReceiptNo ${v.receiptNo}",
                                                fontWeight = FontWeight.Bold,
                                                fontSize = 15.sp,
                                                color = AppTextColor
                                            )
                                            Spacer(modifier = Modifier.height(4.dp))
                                            val dateStr = SimpleDateFormat("dd/MM/yyyy hh:mm a", Locale.getDefault()).format(Date(v.timestamp))
                                            val formattedDate = dateStr.replace(" AM", "AM").replace(" PM", "PM")
                                            Text(
                                                text = formattedDate,
                                                fontSize = 12.sp,
                                                color = Color.Gray
                                            )
                                        }
                                        Text(
                                            text = formatTimeAgo(v.timestamp),
                                            color = BrandPurple,
                                            fontWeight = FontWeight.Bold,
                                            fontSize = 12.sp
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        "select_products" -> {
            val isGridView by viewModel.isProductGridView.collectAsState()
            Scaffold(
                topBar = {
                    TopAppBar(
                        title = {
                            if (isSearchExpanded) {
                                OutlinedTextField(
                                    value = searchQuery,
                                    onValueChange = { searchQuery = it },
                                    placeholder = { Text("Search", fontSize = 18.sp, fontWeight = FontWeight.Bold, color = Color.Gray) },
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .height(52.dp),
                                    colors = OutlinedTextFieldDefaults.colors(
                                        focusedContainerColor = Color.Transparent,
                                        unfocusedContainerColor = Color.Transparent,
                                        focusedBorderColor = Color.Transparent,
                                        unfocusedBorderColor = Color.Transparent
                                    ),
                                    singleLine = true,
                                    textStyle = androidx.compose.ui.text.TextStyle(fontSize = 18.sp, fontWeight = FontWeight.Bold, color = AppTextColor),
                                    trailingIcon = {
                                        if (searchQuery.isNotEmpty()) {
                                            IconButton(onClick = { searchQuery = "" }) {
                                                Icon(imageVector = Icons.Filled.Close, contentDescription = "Clear", tint = Color.Gray)
                                            }
                                        }
                                    }
                                )
                            } else {
                                Text("ကုန်စည်များ", fontWeight = FontWeight.Bold, color = Color.Black)
                            }
                        },
                        navigationIcon = {
                            if (isSearchExpanded) {
                                IconButton(onClick = {
                                    searchQuery = ""
                                    isSearchExpanded = false
                                }) {
                                    Icon(imageVector = Icons.Filled.Close, contentDescription = "Close Search", tint = Color.Black)
                                }
                            } else {
                                IconButton(onClick = { screenState = "select_mode" }) {
                                    Icon(imageVector = Icons.Filled.ArrowBack, contentDescription = "Back", tint = Color.Black)
                                }
                            }
                        },
                        actions = {
                            if (!isSearchExpanded) {
                                IconButton(onClick = { viewModel.isProductGridView.value = !isGridView }) {
                                    Icon(
                                        imageVector = if (isGridView) Icons.Filled.List else Icons.Filled.GridView,
                                        contentDescription = "Toggle Grid/List",
                                        tint = Color.DarkGray
                                    )
                                }
                                IconButton(onClick = { showCategoryRow = !showCategoryRow }) {
                                    Icon(
                                        imageVector = Icons.Filled.Sell,
                                        contentDescription = "Toggle Categories",
                                        tint = Color.DarkGray
                                    )
                                }
                                IconButton(onClick = { isSearchExpanded = true }) {
                                    Icon(
                                        imageVector = Icons.Filled.Search,
                                        contentDescription = "Search",
                                        tint = Color.DarkGray
                                    )
                                }
                            }
                        },
                        colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.White)
                    )
                },
                floatingActionButton = {
                    FloatingActionButton(
                        onClick = {
                            viewModel.editingProduct.value = null
                            viewModel.clearProductForm()
                            viewModel.isFromSalesFlow = true
                            navController.navigate("add_product")
                        },
                        containerColor = Color(0xFFE8E2FF),
                        contentColor = BrandPurple,
                        shape = RoundedCornerShape(16.dp),
                        modifier = Modifier.padding(bottom = 16.dp, end = 8.dp)
                    ) {
                        Icon(imageVector = Icons.Filled.Add, contentDescription = "Add Product", modifier = Modifier.size(24.dp))
                    }
                }
            ) { innerPadding ->
                Column(
                    modifier = Modifier
                        .fillMaxSize()
                        .background(LightBg)
                        .padding(innerPadding)
                        .padding(16.dp)
                ) {
                    // Header Cart Status Card
                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(bottom = 16.dp)
                            .clickable {
                                screenState = "voucher_detail"
                            },
                        colors = CardDefaults.cardColors(containerColor = Color.White),
                        shape = RoundedCornerShape(16.dp),
                        elevation = CardDefaults.cardElevation(2.dp)
                    ) {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(16.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            // Circular Cart Icon
                            Box(
                                modifier = Modifier
                                    .size(48.dp)
                                    .background(Color(0xFFF2F0F7), shape = CircleShape),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Filled.ShoppingCart,
                                    contentDescription = "Cart",
                                    tint = BrandPurple
                                )
                            }
                            
                            Spacer(modifier = Modifier.width(12.dp))
                            
                            Column(modifier = Modifier.weight(1f)) {
                                Text(
                                    text = "စုစုပေါင်း: ${totalAmount.toInt()} $selectedCurrency",
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 16.sp,
                                    color = AppTextColor
                                )
                                Text(
                                    text = "ကုန်စည် $totalItems Item",
                                    fontSize = 13.sp,
                                    color = Color.Gray
                                )
                            }
                            
                            // Checkmark circular button
                            Box(
                                modifier = Modifier
                                    .size(36.dp)
                                    .background(
                                        BrandPurple,
                                        shape = CircleShape
                                    ),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Filled.Check,
                                    contentDescription = "Confirm",
                                    tint = Color.White,
                                    modifier = Modifier.size(18.dp)
                                )
                            }
                        }
                    }

                    // Categories/Groups Horizontal Row
                    if (showCategoryRow) {
                        val groupsList by viewModel.allGroups.collectAsState()
                        val rawCategories = (groupsList.map { it.name } + products.map { it.groupName })
                            .flatMap { it.split(",") }
                            .map { it.trim() }
                            .filter { it.isNotEmpty() }
                            .distinct()
                        val categories = remember(groupsList, products) { listOf("အားလုံး") + rawCategories }
                        
                        LazyRow(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(bottom = 12.dp),
                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            items(categories) { cat ->
                                val isSelected = selectedGroup == cat
                                val chipCount = if (cat == "အားလုံး") products.size else products.count { prod ->
                                    prod.groupName.split(",").map { it.trim() }.any { g -> g.equals(cat, ignoreCase = true) || g == cat }
                                }
                                val labelText = if (cat == "အားလုံး") "အားလုံး(${chipCount} Item)" else cat
                                
                                FilterChip(
                                    selected = isSelected,
                                    onClick = { selectedGroup = cat },
                                    label = { Text(labelText) },
                                    colors = FilterChipDefaults.filterChipColors(
                                        selectedContainerColor = BrandPurple.copy(alpha = 0.15f),
                                        selectedLabelColor = BrandPurple,
                                        containerColor = Color.White,
                                        labelColor = Color.DarkGray
                                    )
                                )
                            }
                        }
                    }

                    // Filtered products list based on query AND category
                    val displayedProducts = remember(filteredProducts, selectedGroup) {
                        if (selectedGroup == "အားလုံး") filteredProducts else {
                            filteredProducts.filter { prod ->
                                prod.groupName.split(",").map { it.trim() }.any { g -> g.equals(selectedGroup, ignoreCase = true) || g == selectedGroup }
                            }
                        }
                    }

                    if (displayedProducts.isEmpty()) {
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .weight(1f),
                            contentAlignment = Alignment.Center
                        ) {
                            Text("လတ်တလော ကုန်စည်မရှိသေးပါ။", color = Color.Gray)
                        }
                    } else {
                        if (isGridView) {
                            LazyVerticalGrid(
                                columns = GridCells.Adaptive(minSize = 105.dp),
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .weight(1f),
                                contentPadding = PaddingValues(vertical = 4.dp),
                                horizontalArrangement = Arrangement.spacedBy(8.dp),
                                verticalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                items(displayedProducts) { prod ->
                                    val cartItem = cart.find { it.product.id == prod.id }
                                    val cartQty = cartItem?.quantity ?: 0
                                    
                                    Card(
                                        colors = CardDefaults.cardColors(containerColor = Color.White),
                                        shape = RoundedCornerShape(12.dp),
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .height(150.dp)
                                            .combinedClickable(
                                                onClick = {
                                                    tryAddToCart(prod)
                                                },
                                                onLongClick = {
                                                    val currentCart = viewModel.cart.value
                                                    val existingIndex = currentCart.indexOfFirst { it.product.id == prod.id }
                                                    val idx = if (existingIndex != -1) {
                                                        existingIndex
                                                    } else {
                                                        if (!isPurchaseMode && (prod.quantity <= 0 || (prod.trackStock && cartQty >= prod.quantity))) {
                                                            showOutOfStockDialogFor = prod
                                                            -1
                                                        } else {
                                                            viewModel.addToCart(prod)
                                                            viewModel.cart.value.size - 1
                                                        }
                                                    }
                                                    if (idx != -1) {
                                                        val item = viewModel.cart.value.getOrNull(idx)
                                                        if (item != null) {
                                                            selectedCartItemIndex = idx
                                                            tempQty = item.quantity
                                                            asDifferentItem = false
                                                            showAdvanced = false
                                                            isNewCartItemPending = (existingIndex == -1)
                                                            editCartItemReturnState = "select_products"
                                                            screenState = "edit_cart_item"
                                                        }
                                                    }
                                                }
                                            ),
                                        elevation = CardDefaults.cardElevation(1.dp)
                                    ) {
                                        Box(modifier = Modifier.fillMaxSize()) {
                                            if (prod.imageUri.isNotEmpty()) {
                                                coil.compose.AsyncImage(
                                                    model = prod.imageUri,
                                                    contentDescription = prod.name,
                                                    modifier = Modifier.fillMaxSize(),
                                                    contentScale = androidx.compose.ui.layout.ContentScale.Crop
                                                )
                                            } else {
                                                Box(
                                                    modifier = Modifier
                                                        .fillMaxSize()
                                                        .background(Color(0xFFD3C2FE)),
                                                    contentAlignment = Alignment.Center
                                                ) {
                                                    Icon(
                                                        imageVector = Icons.Filled.Layers,
                                                        contentDescription = "Product icon",
                                                        tint = Color(0xFF533B78),
                                                        modifier = Modifier.size(38.dp)
                                                    )
                                                }
                                            }

                                            // Cart Quantity Badge on top-right if in cart
                                            if (cartQty > 0) {
                                                Box(
                                                    modifier = Modifier
                                                        .align(Alignment.TopEnd)
                                                        .padding(6.dp)
                                                        .background(BrandPurple, shape = RoundedCornerShape(12.dp))
                                                        .padding(horizontal = 8.dp, vertical = 2.dp)
                                                ) {
                                                    Text(
                                                        text = "$cartQty",
                                                        color = Color.White,
                                                        fontWeight = FontWeight.Bold,
                                                        fontSize = 11.sp
                                                    )
                                                }
                                            }

                                            // Dark purple bottom bar showing item name only
                                            Box(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .align(Alignment.BottomCenter)
                                                    .background(Color(0xFF533B78))
                                                    .padding(horizontal = 8.dp, vertical = 10.dp),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                Text(
                                                    text = prod.name,
                                                    fontWeight = FontWeight.Medium,
                                                    fontSize = 13.sp,
                                                    color = Color.White,
                                                    textAlign = TextAlign.Center,
                                                    maxLines = 1,
                                                    overflow = TextOverflow.Ellipsis
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        } else {
                            LazyColumn(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .weight(1f)
                            ) {
                                items(displayedProducts) { prod ->
                                    val cartItem = cart.find { it.product.id == prod.id }
                                    val cartQty = cartItem?.quantity ?: 0

                                    Card(
                                        colors = CardDefaults.cardColors(containerColor = Color.White),
                                        shape = RoundedCornerShape(12.dp),
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .padding(vertical = 4.dp)
                                            .combinedClickable(
                                                onClick = {
                                                    tryAddToCart(prod)
                                                },
                                                onLongClick = {
                                                    val currentCart = viewModel.cart.value
                                                    val existingIndex = currentCart.indexOfFirst { it.product.id == prod.id }
                                                    val idx = if (existingIndex != -1) {
                                                        existingIndex
                                                    } else {
                                                        if (!isPurchaseMode && (prod.quantity <= 0 || (prod.trackStock && cartQty >= prod.quantity))) {
                                                            showOutOfStockDialogFor = prod
                                                            -1
                                                        } else {
                                                            viewModel.addToCart(prod)
                                                            viewModel.cart.value.size - 1
                                                        }
                                                    }
                                                    if (idx != -1) {
                                                        val item = viewModel.cart.value.getOrNull(idx)
                                                        if (item != null) {
                                                            selectedCartItemIndex = idx
                                                            tempQty = item.quantity
                                                            asDifferentItem = false
                                                            showAdvanced = false
                                                            isNewCartItemPending = (existingIndex == -1)
                                                            editCartItemReturnState = "select_products"
                                                            screenState = "edit_cart_item"
                                                        }
                                                    }
                                                }
                                            ),
                                        elevation = CardDefaults.cardElevation(1.dp)
                                    ) {
                                        Row(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .padding(12.dp),
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Box(
                                                modifier = Modifier
                                                    .size(44.dp)
                                                    .clip(RoundedCornerShape(8.dp))
                                                    .background(Color(0xFFE8E7EC)),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                if (prod.imageUri.isNotEmpty()) {
                                                    coil.compose.AsyncImage(
                                                        model = prod.imageUri,
                                                        contentDescription = prod.name,
                                                        modifier = Modifier.fillMaxSize(),
                                                        contentScale = androidx.compose.ui.layout.ContentScale.Crop
                                                    )
                                                } else {
                                                    Icon(
                                                        imageVector = Icons.Filled.Layers,
                                                        contentDescription = "Product icon",
                                                        tint = BrandPurple,
                                                        modifier = Modifier.size(20.dp)
                                                    )
                                                }
                                            }

                                            Spacer(modifier = Modifier.width(12.dp))

                                            Column(modifier = Modifier.weight(1f)) {
                                                Text(prod.name, fontWeight = FontWeight.Bold, fontSize = 15.sp, color = AppTextColor)
                                                Spacer(modifier = Modifier.height(4.dp))
                                                Text("${(if (isPurchaseMode) prod.purchasePrice else prod.sellingPrice).toInt()} $selectedCurrency", fontSize = 13.sp, color = Color.Gray)
                                            }

                                            if (cartQty > 0) {
                                                Box(
                                                    modifier = Modifier
                                                        .size(8.dp)
                                                        .background(BrandPurple, shape = CircleShape)
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        "voucher_detail" -> {
            val finalDiscount = if (printDiscount) discountAmount else 0.0
            val finalFee = if (printFee) feeAmount else 0.0
            val finalAmount = (totalAmount - discountAmount + feeAmount).coerceAtLeast(0.0)
            Scaffold(
                topBar = {
                    TopAppBar(
                        title = { Text(if (isPurchaseMode) "အဝယ်" else "အရောင်း", fontWeight = FontWeight.Bold, color = Color.Black) },
                        navigationIcon = {
                            IconButton(
                                onClick = {
                                    screenState = "select_products"
                                }
                            ) {
                                Icon(imageVector = Icons.Filled.ArrowBack, contentDescription = "Back", tint = Color.Black)
                            }
                        },
                        actions = {
                            TextButton(
                                onClick = {
                                    viewModel.startNewVoucher()
                                    screenState = "select_products"
                                }
                            ) {
                                Text("+ ဘောက်ချာအသစ်", color = BrandPurple, fontWeight = FontWeight.Bold, fontSize = 14.sp)
                            }
                        },
                        colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.White)
                    )
                }
            ) { innerPadding ->
                Column(
                    modifier = Modifier
                        .fillMaxSize()
                        .background(LightBg)
                        .padding(innerPadding)
                        .padding(16.dp)
                        .verticalScroll(rememberScrollState())
                ) {
                    // Receipt Info Card (Lavender Background)
                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(bottom = 12.dp),
                        colors = CardDefaults.cardColors(containerColor = Color(0xFFF0ECFC)),
                        shape = RoundedCornerShape(16.dp),
                        elevation = CardDefaults.cardElevation(1.dp)
                    ) {
                        Column(
                            modifier = Modifier.padding(16.dp)
                        ) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text("Receipt No:", fontSize = 13.sp, color = Color.Gray)
                                Text(activeVoucherId ?: "", fontWeight = FontWeight.Bold, fontSize = 14.sp, color = BrandPurple)
                            }
                            
                            HorizontalDivider(modifier = Modifier.padding(vertical = 12.dp), color = Color(0xFFE0DAF5))

                            // Customer Row
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable { showCustomerDialog = true },
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(32.dp)
                                        .background(Color.White.copy(alpha = 0.6f), shape = CircleShape),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(imageVector = Icons.Filled.Person, contentDescription = "Customer", tint = BrandPurple, modifier = Modifier.size(18.dp))
                                }
                                Spacer(modifier = Modifier.width(12.dp))
                                Column(modifier = Modifier.weight(1f)) {
                                    Text(if (isPurchaseMode) "ကုန်သွင်းသူများ" else "ဈေးဝယ်သူ", fontSize = 11.sp, color = Color.Gray)
                                    Text(activeCustomerName, fontWeight = FontWeight.Bold, fontSize = 13.sp, color = Color.DarkGray)
                                }
                                Icon(imageVector = Icons.Filled.Edit, contentDescription = "Edit Customer", tint = Color.Gray, modifier = Modifier.size(16.dp))
                            }
                            
                            Spacer(modifier = Modifier.height(12.dp))

                            // Payment Method Row
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable { showPaymentDialog = true },
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(32.dp)
                                        .background(Color.White.copy(alpha = 0.6f), shape = CircleShape),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(imageVector = Icons.Filled.Payments, contentDescription = "Payment", tint = BrandPurple, modifier = Modifier.size(18.dp))
                                }
                                Spacer(modifier = Modifier.width(12.dp))
                                Column(modifier = Modifier.weight(1f)) {
                                    Text("ငွေပေးချေမှု", fontSize = 11.sp, color = Color.Gray)
                                    Text(activePaymentMethod, fontWeight = FontWeight.Bold, fontSize = 13.sp, color = Color.DarkGray)
                                }
                                Icon(imageVector = Icons.Filled.Edit, contentDescription = "Edit Payment", tint = Color.Gray, modifier = Modifier.size(16.dp))
                            }
                        }
                    }

                    // Bar Code decoration card (Clean White)
                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(bottom = 16.dp),
                        colors = CardDefaults.cardColors(containerColor = Color.White),
                        shape = RoundedCornerShape(12.dp),
                        elevation = CardDefaults.cardElevation(1.dp)
                    ) {
                        var inlineBarcode by remember { mutableStateOf("") }
                        OutlinedTextField(
                            value = inlineBarcode,
                            onValueChange = { inlineBarcode = it },
                            placeholder = { Text("ဘားကုဒ် ရိုက်ထည့်ပါ / ဖတ်ပါ", fontSize = 14.sp, color = Color.Gray) },
                            leadingIcon = {
                                Icon(imageVector = Icons.Filled.CropFree, contentDescription = "Scan", tint = BrandPurple)
                            },
                            trailingIcon = {
                                if (inlineBarcode.isNotEmpty()) {
                                    IconButton(onClick = {
                                        if (processScannedBarcode(inlineBarcode)) {
                                            inlineBarcode = ""
                                        }
                                    }) {
                                        Icon(imageVector = Icons.Filled.ArrowForward, contentDescription = "Enter", tint = BrandPurple)
                                    }
                                }
                            },
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(8.dp)
                                .onKeyEvent { keyEvent ->
                                    if (keyEvent.type == KeyEventType.KeyDown && (keyEvent.key == Key.Enter || keyEvent.key == Key.NumPadEnter)) {
                                        if (processScannedBarcode(inlineBarcode)) {
                                            inlineBarcode = ""
                                        }
                                        true
                                    } else false
                                },
                            keyboardOptions = KeyboardOptions(imeAction = ImeAction.Done),
                            keyboardActions = KeyboardActions(
                                onDone = {
                                    if (processScannedBarcode(inlineBarcode)) {
                                        inlineBarcode = ""
                                    }
                                }
                            ),
                            singleLine = true,
                            colors = OutlinedTextFieldDefaults.colors(
                                focusedBorderColor = BrandPurple,
                                unfocusedBorderColor = Color(0xFFE0E0E0),
                                focusedContainerColor = Color.White,
                                unfocusedContainerColor = Color.White
                            )
                        )
                    }

                    // Table Header
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(horizontal = 8.dp, vertical = 4.dp),
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Text("အမည်", fontWeight = FontWeight.Bold, fontSize = 13.sp, color = Color.Gray, modifier = Modifier.weight(1.5f))
                        Text("ဈေးနှုန်း", fontWeight = FontWeight.Bold, fontSize = 13.sp, color = Color.Gray, modifier = Modifier.weight(1.2f), textAlign = TextAlign.Center)
                        Text("သင့်ငွေ", fontWeight = FontWeight.Bold, fontSize = 13.sp, color = Color.Gray, modifier = Modifier.weight(1f), textAlign = TextAlign.End)
                    }

                    HorizontalDivider(modifier = Modifier.padding(vertical = 4.dp), color = Color(0xFFE5E5E5))

                    // Cart Items list
                    cart.forEachIndexed { idx, item ->
                        val isSelected = idx == selectedCartItemIndex
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(if (isSelected) Color(0xFFF0ECFC) else Color.White, shape = RoundedCornerShape(8.dp))
                                .then(
                                    if (isSelected) Modifier.border(
                                        width = 1.5.dp,
                                        color = BrandPurple,
                                        shape = RoundedCornerShape(8.dp)
                                    ) else Modifier
                                )
                                .clickable {
                                    selectedCartItemIndex = idx
                                    tempQty = item.quantity
                                    asDifferentItem = false
                                    showAdvanced = false
                                    editCartItemReturnState = "voucher_detail"
                                    screenState = "edit_cart_item"
                                }
                                .padding(horizontal = 12.dp, vertical = 12.dp)
                                .padding(bottom = 4.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Row(modifier = Modifier.weight(1.5f), verticalAlignment = Alignment.CenterVertically) {
                                Box(
                                    modifier = Modifier
                                        .size(6.dp)
                                        .background(BrandPurple, shape = CircleShape)
                                )
                                Spacer(modifier = Modifier.width(8.dp))
                                Text(item.product.name, fontWeight = FontWeight.SemiBold, fontSize = 14.sp, color = Color.DarkGray)
                            }
                            Text(
                                text = "${(if (isPurchaseMode) item.product.purchasePrice else item.product.sellingPrice).toInt()} $selectedCurrency x${item.quantity}",
                                fontSize = 13.sp,
                                color = Color.Gray,
                                modifier = Modifier.weight(1.2f),
                                textAlign = TextAlign.Center
                            )
                            Text(
                                text = "${((if (isPurchaseMode) item.product.purchasePrice else item.product.sellingPrice) * item.quantity).toInt()} $selectedCurrency",
                                fontWeight = FontWeight.Bold,
                                fontSize = 13.sp,
                                color = Color.DarkGray,
                                modifier = Modifier.weight(1f),
                                textAlign = TextAlign.End
                            )
                        }
                        Spacer(modifier = Modifier.height(4.dp))
                    }

                    HorizontalDivider(modifier = Modifier.padding(vertical = 12.dp), color = Color(0xFFE5E5E5))

                    // Subtotal amount (စုစုပေါင်း)
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(horizontal = 8.dp, vertical = 4.dp),
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Text("စုစုပေါင်း", fontWeight = FontWeight.Bold, fontSize = 14.sp, color = Color.Gray)
                        Text("${totalAmount.toInt()} $selectedCurrency", fontWeight = FontWeight.Bold, fontSize = 15.sp, color = Color.DarkGray)
                    }

                    // Discount row (if any)
                    if (discountAmount > 0.0) {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(horizontal = 8.dp, vertical = 4.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                Text(noteText.ifEmpty { "Discount" }, fontWeight = FontWeight.Bold, fontSize = 14.sp, color = Color.Gray)
                                Spacer(modifier = Modifier.width(4.dp))
                                IconButton(
                                    onClick = {
                                        discountAmount = 0.0
                                        noteText = ""
                                    },
                                    modifier = Modifier.size(24.dp)
                                ) {
                                    Icon(
                                        imageVector = Icons.Filled.Cancel,
                                        contentDescription = "Remove Discount",
                                        tint = Color.Red,
                                        modifier = Modifier.size(16.dp)
                                    )
                                }
                            }
                            Text("-${discountAmount.toInt()} $selectedCurrency", fontWeight = FontWeight.Bold, fontSize = 15.sp, color = BrandPurple)
                        }
                    }

                    // Fee row (if any)
                    if (feeAmount > 0.0) {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(horizontal = 8.dp, vertical = 4.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                Text("ဝန်ဆောင်ခ", fontWeight = FontWeight.Bold, fontSize = 14.sp, color = Color.Gray)
                                Spacer(modifier = Modifier.width(4.dp))
                                IconButton(
                                    onClick = {
                                        feeAmount = 0.0
                                    },
                                    modifier = Modifier.size(24.dp)
                                ) {
                                    Icon(
                                        imageVector = Icons.Filled.Cancel,
                                        contentDescription = "Remove Fee",
                                        tint = Color.Red,
                                        modifier = Modifier.size(16.dp)
                                    )
                                }
                            }
                            Text("+${feeAmount.toInt()} $selectedCurrency", fontWeight = FontWeight.Bold, fontSize = 15.sp, color = Color.DarkGray)
                        }
                    }

                    // Total to pay (စုစုပေါင်းကျသင့်ငွေ)
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(horizontal = 8.dp, vertical = 4.dp),
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Text("စုစုပေါင်းကျသင့်ငွေ", fontWeight = FontWeight.Bold, fontSize = 14.sp, color = Color.Gray)
                        Text("${finalAmount.toInt()} $selectedCurrency", fontWeight = FontWeight.Bold, fontSize = 15.sp, color = BrandPurple)
                    }

                    // Print switcher
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(horizontal = 8.dp, vertical = 4.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text("ပို၍", fontWeight = FontWeight.Bold, fontSize = 14.sp, color = Color.DarkGray)
                        Switch(
                            checked = printVoucher,
                            onCheckedChange = { printVoucher = it },
                            colors = SwitchDefaults.colors(
                                checkedThumbColor = Color.White,
                                checkedTrackColor = BrandPurple,
                                uncheckedThumbColor = Color.Gray,
                                uncheckedTrackColor = Color.LightGray
                            )
                        )
                    }

                    // Conditionally show print settings details when Print is toggled ON
                    if (printVoucher) {
                        Card(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(vertical = 12.dp),
                            colors = CardDefaults.cardColors(containerColor = Color.White),
                            shape = RoundedCornerShape(12.dp),
                            elevation = CardDefaults.cardElevation(1.dp)
                        ) {
                            Column(modifier = Modifier.padding(16.dp)) {
                                // Date Row
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable { showDatePicker() },
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                        Icon(imageVector = Icons.Filled.CalendarMonth, contentDescription = "Calendar", tint = Color.Gray, modifier = Modifier.size(18.dp))
                                        Spacer(modifier = Modifier.width(8.dp))
                                        Text("ရက်စွဲ", fontSize = 13.sp, color = Color.DarkGray)
                                    }
                                    val dateStr = SimpleDateFormat("yyyy-MM-dd", Locale.getDefault()).format(selectedCalendar.value.time)
                                    Text(dateStr, fontWeight = FontWeight.Medium, fontSize = 13.sp, color = Color.DarkGray)
                                }
                                
                                Spacer(modifier = Modifier.height(12.dp))
                                
                                // Time Row
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable { showTimePicker() },
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                        Icon(imageVector = Icons.Filled.Schedule, contentDescription = "Time", tint = Color.Gray, modifier = Modifier.size(18.dp))
                                        Spacer(modifier = Modifier.width(8.dp))
                                        Text("အချိန်", fontSize = 13.sp, color = Color.DarkGray)
                                    }
                                    val timeStr = SimpleDateFormat("hh:mm a", Locale.getDefault()).format(selectedCalendar.value.time)
                                    Text(timeStr, fontWeight = FontWeight.Medium, fontSize = 13.sp, color = Color.DarkGray)
                                }
                                
                                HorizontalDivider(modifier = Modifier.padding(vertical = 12.dp), color = Color(0xFFF2F2F2))
                                
                                // Discount Row
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable { showDiscountFeeSheet = true },
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                        Icon(imageVector = Icons.Filled.AddCircleOutline, contentDescription = "Discount", tint = BrandPurple, modifier = Modifier.size(18.dp))
                                        Spacer(modifier = Modifier.width(8.dp))
                                        Text("Discount (လျော့စျေး)", fontSize = 13.sp, color = Color.DarkGray)
                                    }
                                    Text("${discountAmount.toInt()} $selectedCurrency", fontWeight = FontWeight.Bold, fontSize = 13.sp, color = BrandPurple)
                                }
                                
                                Spacer(modifier = Modifier.height(12.dp))
                                
                                // Fee Row
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable { showDiscountFeeSheet = true },
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                        Icon(imageVector = Icons.Filled.AddCircleOutline, contentDescription = "Fee", tint = BrandPurple, modifier = Modifier.size(18.dp))
                                        Spacer(modifier = Modifier.width(8.dp))
                                        Text("Fee (ဝန်ဆောင်ခ)", fontSize = 13.sp, color = Color.DarkGray)
                                    }
                                    Text("${feeAmount.toInt()} $selectedCurrency", fontWeight = FontWeight.Bold, fontSize = 13.sp, color = Color.DarkGray)
                                }
                                
                                HorizontalDivider(modifier = Modifier.padding(vertical = 12.dp), color = Color(0xFFF2F2F2))
                                
                                // Note Row
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable { showDiscountFeeSheet = true },
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                        Icon(imageVector = Icons.Filled.Chat, contentDescription = "Note", tint = Color.Gray, modifier = Modifier.size(18.dp))
                                        Spacer(modifier = Modifier.width(8.dp))
                                        Text("မှတ်ချက်", fontSize = 13.sp, color = Color.DarkGray)
                                    }
                                    Text(if (noteText.isEmpty()) "မှတ်ချက်ထည့်ရန်" else noteText, fontSize = 13.sp, color = if (noteText.isEmpty()) Color.LightGray else Color.DarkGray, maxLines = 1)
                                }
                                
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(24.dp))

                    // Complete / Checkout Button
                    Button(
                        onClick = {
                            completedVoucherId = activeVoucherId ?: ""
                            completedCustomerName = activeCustomerName ?: "Not Register"
                            completedPaymentMethod = activePaymentMethod ?: "CASH"
                            completedTotalAmount = finalAmount
                            completedItems = cart.toList()
                            completedTimestamp = selectedCalendar.value.timeInMillis
                            paidAmountString = if (activePaymentMethod.equals("CREDIT", ignoreCase = true)) "0" else finalAmount.toInt().toString()
                            screenState = "checkout_payment"
                        },
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(54.dp),
                        colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                        shape = RoundedCornerShape(14.dp)
                    ) {
                        Icon(imageVector = Icons.Filled.Check, contentDescription = "Done", tint = Color.White)
                        Spacer(modifier = Modifier.width(8.dp))
                        val buttonLabel = if (activePaymentMethod.equals("CREDIT", ignoreCase = true)) {
                            "Pay and Later ${finalAmount.toInt()} $selectedCurrency"
                        } else {
                            "ရှင်းမည် ${finalAmount.toInt()} $selectedCurrency"
                        }
                        Text(buttonLabel, color = Color.White, fontWeight = FontWeight.Bold, fontSize = 16.sp)
                    }
                }
            }


        }
        "edit_cart_item" -> {
            val selectedItem = cart.getOrNull(selectedCartItemIndex)
            if (selectedItem == null) {
                LaunchedEffect(Unit) {
                    selectedCartItemIndex = -1
                    screenState = editCartItemReturnState
                }
            } else {
                Scaffold(
                    topBar = {
                        TopAppBar(
                            title = {
                                Text(if (isPurchaseMode) "အဝယ်" else "အရောင်း", fontWeight = FontWeight.Bold, color = Color.DarkGray, fontSize = 20.sp)
                            },
                            navigationIcon = {
                                IconButton(
                                    onClick = {
                                        if (isNewCartItemPending && selectedCartItemIndex != -1) {
                                            viewModel.updateCartItemQuantityByIndex(selectedCartItemIndex, 0)
                                            isNewCartItemPending = false
                                        }
                                        selectedCartItemIndex = -1
                                        screenState = editCartItemReturnState
                                    }
                                ) {
                                    Icon(imageVector = Icons.Filled.ArrowBack, contentDescription = "Back", tint = Color.DarkGray)
                                }
                            },
                            actions = {
                                IconButton(
                                    onClick = {
                                        showDeleteItemConfirmDialog = true
                                    }
                                ) {
                                    Icon(imageVector = Icons.Filled.Delete, contentDescription = "Delete", tint = Color.DarkGray)
                                }
                            },
                            colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.White)
                        )
                    },
                    bottomBar = {
                        Button(
                            onClick = {
                                val finalName = itemEditName.ifBlank { selectedItem.product.name }
                                val finalPurchasePrice = itemEditPurchasePrice.toDoubleOrNull() ?: selectedItem.product.purchasePrice
                                val finalSellingPrice = itemEditSellingPrice.toDoubleOrNull() ?: selectedItem.product.sellingPrice

                                if (asDifferentItem && showAdvanced) {
                                    val duplicatedIndex = viewModel.duplicateCartItem(selectedCartItemIndex)
                                    viewModel.updateCartItemQuantityByIndex(duplicatedIndex, tempQty)
                                    viewModel.updateCartItemNameByIndex(duplicatedIndex, finalName)
                                    if (isPurchaseMode) {
                                        viewModel.updateCartItemPurchasePriceByIndex(duplicatedIndex, finalPurchasePrice)
                                    }
                                    viewModel.updateCartItemPriceByIndex(duplicatedIndex, finalSellingPrice)
                                } else {
                                    viewModel.updateCartItemQuantityByIndex(selectedCartItemIndex, tempQty)
                                    viewModel.updateCartItemNameByIndex(selectedCartItemIndex, finalName)
                                    if (isPurchaseMode) {
                                        viewModel.updateCartItemPurchasePriceByIndex(selectedCartItemIndex, finalPurchasePrice)
                                    }
                                    viewModel.updateCartItemPriceByIndex(selectedCartItemIndex, finalSellingPrice)
                                }

                                if (isPurchaseMode) {
                                    viewModel.updateProductPricesInDb(
                                        productId = selectedItem.product.id,
                                        newPurchasePrice = finalPurchasePrice,
                                        newSellingPrice = finalSellingPrice
                                    )
                                }

                                isNewCartItemPending = false
                                selectedCartItemIndex = -1
                                screenState = editCartItemReturnState
                            },
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(16.dp)
                                .height(50.dp),
                            shape = RoundedCornerShape(8.dp),
                            colors = ButtonDefaults.buttonColors(containerColor = BrandPurple)
                        ) {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Filled.CheckCircle,
                                    contentDescription = "Check",
                                    tint = Color.White,
                                    modifier = Modifier.size(20.dp)
                                )
                                Spacer(modifier = Modifier.width(8.dp))
                                Text(
                                    text = "ADD",
                                    fontWeight = FontWeight.Bold,
                                    color = Color.White,
                                    fontSize = 16.sp
                                )
                            }
                        }
                    }
                ) { innerPadding ->
                    Column(
                        modifier = Modifier
                            .fillMaxSize()
                            .background(Color.White)
                            .padding(innerPadding)
                            .padding(16.dp),
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.Top
                    ) {
                        // "ပို၍" Switch row
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(vertical = 12.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(
                                text = "ပို၍",
                                fontWeight = FontWeight.SemiBold,
                                fontSize = 16.sp,
                                color = Color.DarkGray
                            )
                            Switch(
                                checked = showAdvanced,
                                onCheckedChange = { showAdvanced = it },
                                colors = SwitchDefaults.colors(
                                    checkedThumbColor = Color.White,
                                    checkedTrackColor = BrandPurple,
                                    uncheckedThumbColor = Color.Gray,
                                    uncheckedTrackColor = Color.LightGray
                                )
                            )
                        }

                        if (showAdvanced) {
                            Card(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(vertical = 12.dp),
                                colors = CardDefaults.cardColors(containerColor = Color(0xFFF3EFFF)),
                                shape = RoundedCornerShape(12.dp)
                            ) {
                                Column(
                                    modifier = Modifier.padding(16.dp),
                                    verticalArrangement = Arrangement.spacedBy(16.dp)
                                ) {
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Text("As Different Item", fontSize = 14.sp, color = Color.DarkGray)
                                        Checkbox(
                                            checked = asDifferentItem,
                                            onCheckedChange = { asDifferentItem = it },
                                            colors = CheckboxDefaults.colors(checkedColor = BrandPurple)
                                        )
                                    }

                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Text("ကုန်စည်အမည်", fontSize = 14.sp, color = Color.Gray, modifier = Modifier.weight(1f))
                                        BasicTextField(
                                            value = itemEditName,
                                            onValueChange = { itemEditName = it },
                                            textStyle = TextStyle(
                                                fontSize = 15.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = BrandPurple,
                                                textAlign = TextAlign.End
                                            ),
                                            singleLine = true,
                                            modifier = Modifier.weight(1.5f),
                                            cursorBrush = SolidColor(BrandPurple)
                                        )
                                    }

                                    if (isPurchaseMode) {
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Text("ဝယ်ဈေး", fontSize = 14.sp, color = Color.Gray, modifier = Modifier.weight(1f))
                                            BasicTextField(
                                                value = itemEditPurchasePrice,
                                                onValueChange = { newValue ->
                                                    itemEditPurchasePrice = newValue.filter { it.isDigit() || it == '.' }
                                                },
                                                textStyle = TextStyle(
                                                    fontSize = 15.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = Color.DarkGray,
                                                    textAlign = TextAlign.End
                                                ),
                                                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                                                singleLine = true,
                                                modifier = Modifier.weight(1.5f),
                                                cursorBrush = SolidColor(BrandPurple)
                                            )
                                        }
                                    }

                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Text("ရောင်းဈေး", fontSize = 14.sp, color = Color.Gray, modifier = Modifier.weight(1f))
                                        BasicTextField(
                                            value = itemEditSellingPrice,
                                            onValueChange = { newValue ->
                                                itemEditSellingPrice = newValue.filter { it.isDigit() || it == '.' }
                                            },
                                            textStyle = TextStyle(
                                                fontSize = 15.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = Color.DarkGray,
                                                textAlign = TextAlign.End
                                            ),
                                            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                                            singleLine = true,
                                            modifier = Modifier.weight(1.5f),
                                            cursorBrush = SolidColor(BrandPurple)
                                        )
                                    }
                                }
                            }
                        }

                        Spacer(modifier = Modifier.height(16.dp))

                        // Quantity Editor
                        Column(
                            horizontalAlignment = Alignment.CenterHorizontally,
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Text("အရေအတွက်", fontSize = 14.sp, color = Color.Gray)
                            Spacer(modifier = Modifier.height(8.dp))
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.Center,
                                modifier = Modifier.fillMaxWidth()
                            ) {
                                IconButton(
                                    onClick = {
                                        if (tempQty > 1) {
                                            tempQty--
                                        }
                                    },
                                    modifier = Modifier
                                        .size(48.dp)
                                        .background(Color(0xFFE8E7EC), shape = RoundedCornerShape(8.dp))
                                ) {
                                    Icon(imageVector = Icons.Filled.Remove, contentDescription = "Minus", tint = Color.DarkGray)
                                }
                                
                                var qtyText by remember(tempQty) { mutableStateOf(tempQty.toString()) }

                                androidx.compose.foundation.text.BasicTextField(
                                    value = qtyText,
                                    onValueChange = { newValue ->
                                        val filtered = newValue.filter { it.isDigit() }
                                        val parsed = filtered.toIntOrNull()
                                        val maxQty = if (isPurchaseMode) Int.MAX_VALUE else maxOf(1, selectedItem.product.quantity)
                                        if (parsed != null) {
                                            if (parsed > maxQty) {
                                                tempQty = maxQty
                                                qtyText = maxQty.toString()
                                            } else {
                                                tempQty = parsed
                                                qtyText = filtered
                                            }
                                        } else {
                                            qtyText = filtered
                                            if (filtered.isEmpty()) {
                                                tempQty = 1
                                            }
                                        }
                                    },
                                    textStyle = androidx.compose.ui.text.TextStyle(
                                        textAlign = TextAlign.Center,
                                        fontSize = 28.sp,
                                        color = Color.DarkGray,
                                        fontWeight = FontWeight.Normal
                                    ),
                                    keyboardOptions = KeyboardOptions(
                                        keyboardType = KeyboardType.Number
                                    ),
                                    modifier = Modifier
                                        .width(160.dp)
                                        .padding(horizontal = 16.dp)
                                        .drawBehind {
                                            val strokeWidth = 1.dp.toPx()
                                            val y = size.height - strokeWidth / 2
                                            drawLine(
                                                color = Color.LightGray,
                                                start = Offset(0f, y),
                                                end = Offset(size.width, y),
                                                strokeWidth = strokeWidth
                                            )
                                        }
                                        .padding(bottom = 4.dp)
                                )
                                
                                IconButton(
                                    onClick = {
                                        val maxQty = if (isPurchaseMode) Int.MAX_VALUE else maxOf(1, selectedItem.product.quantity)
                                        if (tempQty < maxQty) {
                                            tempQty++
                                        }
                                    },
                                    modifier = Modifier
                                        .size(48.dp)
                                        .background(Color(0xFFE8E7EC), shape = RoundedCornerShape(8.dp))
                                ) {
                                    Icon(imageVector = Icons.Filled.Add, contentDescription = "Plus", tint = Color.DarkGray)
                                }
                            }
                        }
                        
                        Spacer(modifier = Modifier.height(24.dp))
                        
                        // BY TOTAL check

                    }
                }
            }
        }
        "checkout_payment" -> {
            val context = LocalContext.current
            val numberFormat = NumberFormat.getNumberInstance(Locale.US)
            val labelPaidVal by viewModel.labelPaid.collectAsState()
            val labelDueVal by viewModel.labelDue.collectAsState()
            val currentTotal = completedTotalAmount
            val paidVal = paidAmountString.toDoubleOrNull() ?: 0.0
            val changeVal = paidVal - currentTotal

            Scaffold(
                topBar = {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(Color.White)
                            .padding(horizontal = 8.dp, vertical = 8.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        IconButton(onClick = { screenState = "voucher_detail" }) {
                            Icon(
                                imageVector = Icons.Filled.ArrowBack,
                                contentDescription = "Back",
                                tint = Color.DarkGray
                            )
                        }
                    }
                },
                containerColor = Color.White
            ) { innerPadding ->
                val focusRequester = remember { FocusRequester() }
                val keyboardController = androidx.compose.ui.platform.LocalSoftwareKeyboardController.current

                Column(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(innerPadding)
                        .padding(horizontal = 24.dp),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    Spacer(modifier = Modifier.height(16.dp))
                    Text(
                        text = "TOTAL:",
                        fontSize = 14.sp,
                        fontWeight = FontWeight.Medium,
                        color = Color.Gray
                    )
                    Spacer(modifier = Modifier.height(4.dp))
                    Text(
                        text = "${numberFormat.format(currentTotal)} $selectedCurrency",
                        fontSize = 32.sp,
                        fontWeight = FontWeight.Bold,
                        color = AppTextColor
                    )

                    Spacer(modifier = Modifier.height(24.dp))

                    // Box 1: ပေးငွေ :
                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(64.dp)
                            .clickable {
                                focusRequester.requestFocus()
                                keyboardController?.show()
                            },
                        colors = CardDefaults.cardColors(containerColor = Color(0xFFF2F0F7)),
                        shape = RoundedCornerShape(12.dp)
                    ) {
                        Row(
                            modifier = Modifier
                                .fillMaxSize()
                                .padding(horizontal = 16.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                Text(
                                    text = "$labelPaidVal : ",
                                    fontSize = 18.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = Color.DarkGray
                                )
                                Text(
                                    text = if (paidAmountString.isNotEmpty()) numberFormat.format(paidVal) else "",
                                    fontSize = 18.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = Color(0xFF3B1F9F)
                                )
                            }
                            if (paidAmountString.isNotEmpty()) {
                                IconButton(onClick = { paidAmountString = "" }) {
                                    Icon(
                                        imageVector = Icons.Filled.Cancel,
                                        contentDescription = "Clear",
                                        tint = Color.Gray
                                    )
                                }
                            }
                        }
                        // Hidden BasicTextField for receiving system keyboard inputs
                        androidx.compose.foundation.text.BasicTextField(
                            value = paidAmountString,
                            onValueChange = { newValue ->
                                if (newValue.all { it.isDigit() || newValue.isEmpty() }) {
                                    paidAmountString = newValue
                                }
                            },
                            keyboardOptions = androidx.compose.foundation.text.KeyboardOptions(
                                keyboardType = androidx.compose.ui.text.input.KeyboardType.Number
                            ),
                            modifier = Modifier
                                .size(1.dp)
                                .focusRequester(focusRequester),
                            textStyle = androidx.compose.ui.text.TextStyle(color = Color.Transparent)
                        )
                    }

                    Spacer(modifier = Modifier.height(16.dp))

                    if (activePaymentMethod.equals("CREDIT", ignoreCase = true)) {
                        val remainingVal = (currentTotal - paidVal).coerceAtLeast(0.0)
                        val creditChangeVal = (paidVal - currentTotal).coerceAtLeast(0.0)

                        // Box 2: ကျန်ငွေ :
                        Card(
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(64.dp),
                            colors = CardDefaults.cardColors(containerColor = Color(0xFFF2F0F7)),
                            shape = RoundedCornerShape(12.dp)
                        ) {
                            Row(
                                modifier = Modifier
                                    .fillMaxSize()
                                    .padding(horizontal = 16.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = "ကျန်ငွေ : ",
                                    fontSize = 18.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = Color.DarkGray
                                )
                                Text(
                                    text = "${numberFormat.format(remainingVal)} $selectedCurrency",
                                    fontSize = 18.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = if (remainingVal > 0) Color.Red else Color.DarkGray
                                )
                            }
                        }

                        Spacer(modifier = Modifier.height(16.dp))

                        // Box 3: အမ်းငွေ :
                        Card(
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(64.dp),
                            colors = CardDefaults.cardColors(containerColor = Color(0xFFF2F0F7)),
                            shape = RoundedCornerShape(12.dp)
                        ) {
                            Row(
                                modifier = Modifier
                                    .fillMaxSize()
                                    .padding(horizontal = 16.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = "အမ်းငွေ : ",
                                    fontSize = 18.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = Color.DarkGray
                                )
                                Text(
                                    text = "${numberFormat.format(creditChangeVal)} $selectedCurrency",
                                    fontSize = 18.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = if (creditChangeVal > 0) Color(0xFF4CAF50) else Color.DarkGray
                                )
                            }
                        }
                    } else {
                        // Box 2: အမ်းငွေ :
                        Card(
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(64.dp),
                            colors = CardDefaults.cardColors(containerColor = Color(0xFFF2F0F7)),
                            shape = RoundedCornerShape(12.dp)
                        ) {
                            Row(
                                modifier = Modifier
                                    .fillMaxSize()
                                    .padding(horizontal = 16.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = "$labelDueVal : ",
                                    fontSize = 18.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = Color.DarkGray
                                )
                                val changeText = if (paidAmountString.isEmpty()) "0 $selectedCurrency" else "${numberFormat.format(changeVal)} $selectedCurrency"
                                Text(
                                    text = changeText,
                                    fontSize = 18.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = if (changeVal >= 0) Color(0xFF4CAF50) else Color.Red
                                )
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(24.dp))

                    // FINISH Button (Only visible if paidAmountString is not empty)
                    if (paidAmountString.isNotEmpty()) {
                        Button(
                            onClick = {
                                completedPaidAmount = paidVal
                                completedChangeAmount = changeVal

                                val isCredit = viewModel.activePaymentMethod.value.equals("CREDIT", ignoreCase = true)
                                val initialBalance = if (isCredit) (completedTotalAmount - paidVal).coerceAtLeast(0.0) else 0.0
                                val initialChange = if (isCredit) (paidVal - completedTotalAmount).coerceAtLeast(0.0) else changeVal
                                val initialNote = if (isCredit) {
                                    "စုစုပေါင်း: ${numberFormat.format(completedTotalAmount.toInt())} $selectedCurrency\nပေးငွေ: ${numberFormat.format(paidVal.toInt())} $selectedCurrency\nကျန်ငွေ: ${numberFormat.format(initialBalance.toInt())} $selectedCurrency"
                                } else ""

                                viewModel.saveOrUpdateVoucher(
                                    isCompleted = true,
                                    customTimestamp = completedTimestamp,
                                    customTotalAmount = completedTotalAmount,
                                    paidAmount = paidVal,
                                    changeAmount = initialChange,
                                    balanceAmount = initialBalance,
                                    note = initialNote
                                ) {
                                    screenState = "checkout_success"
                                }
                            },
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(54.dp),
                            colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                            shape = RoundedCornerShape(12.dp)
                        ) {
                            val isExactAmount = paidVal == currentTotal
                            if (isExactAmount) {
                                Icon(
                                    imageVector = Icons.Filled.Autorenew,
                                    contentDescription = "Exact",
                                    tint = Color.White
                                )
                                Spacer(modifier = Modifier.width(8.dp))
                            }
                            Text(
                                text = "FINISH",
                                fontSize = 16.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color.White
                            )
                        }
                    }

                    Spacer(modifier = Modifier.weight(1f))

                    // Custom Numeric Keypad
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(Color(0xFFF7F7FA))
                            .padding(8.dp),
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        val keyboardRows = listOf(
                            listOf("1", "2", "3", "+"),
                            listOf("4", "5", "6", "-"),
                            listOf("7", "8", "9", "C"),
                            listOf(".", "0", "00", "⌫")
                        )

                        for (row in keyboardRows) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                for (key in row) {
                                    val isSpecial = key == "⌫" || key == "C" || key == "+" || key == "-"
                                    Card(
                                        modifier = Modifier
                                            .weight(1f)
                                            .height(54.dp)
                                            .clickable {
                                                when (key) {
                                                    "⌫" -> {
                                                        if (paidAmountString.isNotEmpty()) {
                                                            paidAmountString = paidAmountString.dropLast(1)
                                                        }
                                                    }
                                                    "C" -> {
                                                        paidAmountString = ""
                                                    }
                                                    "." -> {
                                                        if (!paidAmountString.contains(".")) {
                                                            paidAmountString += "."
                                                        }
                                                    }
                                                    "00" -> {
                                                        if (paidAmountString.isNotEmpty() && paidAmountString.length < 8) {
                                                            paidAmountString += "00"
                                                        }
                                                    }
                                                    "+" -> { /* Decorative */ }
                                                    "-" -> { /* Decorative */ }
                                                    else -> {
                                                        if (paidAmountString.length < 9) {
                                                            paidAmountString += key
                                                        }
                                                    }
                                                }
                                            },
                                        colors = CardDefaults.cardColors(
                                            containerColor = if (isSpecial) Color(0xFFE8E7EC) else Color.White
                                        ),
                                        shape = RoundedCornerShape(8.dp),
                                        elevation = CardDefaults.cardElevation(1.dp)
                                    ) {
                                        Box(
                                            modifier = Modifier.fillMaxSize(),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            if (key == "⌫") {
                                                Icon(
                                                    imageVector = Icons.Filled.Backspace,
                                                    contentDescription = "Backspace",
                                                    tint = Color.DarkGray,
                                                    modifier = Modifier.size(20.dp)
                                                )
                                            } else {
                                                Text(
                                                    text = key,
                                                    fontSize = 20.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = if (isSpecial) Color.DarkGray else AppTextColor
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                    Spacer(modifier = Modifier.height(8.dp))
                }
            }
        }
        "checkout_success" -> {
            val context = LocalContext.current
            Scaffold(
                topBar = {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(Color.White)
                            .padding(horizontal = 8.dp, vertical = 8.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        IconButton(onClick = { resetVoucherState() }) {
                            Icon(
                                imageVector = Icons.Filled.Close,
                                contentDescription = "Close",
                                tint = Color.DarkGray
                            )
                        }
                    }
                },
                containerColor = Color.White
            ) { innerPadding ->
                Column(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(innerPadding)
                        .padding(horizontal = 24.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.Center
                ) {
                    Spacer(modifier = Modifier.weight(1f))

                    // Large circle with checkmark
                    Box(
                        modifier = Modifier
                            .size(120.dp)
                            .border(width = 4.dp, color = BrandPurple, shape = CircleShape),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(
                            imageVector = Icons.Filled.Check,
                            contentDescription = "Success",
                            tint = BrandPurple,
                            modifier = Modifier.size(64.dp)
                        )
                    }

                    Spacer(modifier = Modifier.height(24.dp))

                    Text(
                        text = "Successfully Finished",
                        fontSize = 22.sp,
                        fontWeight = FontWeight.Bold,
                        color = AppTextColor
                    )

                    Spacer(modifier = Modifier.weight(1.2f))

                    // Print Receipt Button
                    Button(
                        onClick = {
                            val matchedCustomer = customers.find { it.name == completedCustomerName }
                            val custPhone = matchedCustomer?.phone ?: ""
                            val custAddress = matchedCustomer?.address ?: ""
                            val bitmap = drawReceiptBitmap(
                                context = context,
                                storeName = "yyy",
                                phone = "092534",
                                receiptNo = completedVoucherId,
                                items = completedItems,
                                total = completedTotalAmount,
                                paid = completedPaidAmount,
                                change = completedChangeAmount,
                                timestamp = completedTimestamp,
                                paperWidth = viewModel.selectedPaperWidth.value,
                                printMode = viewModel.selectedPrintMode.value,
                                template = viewModel.selectedTemplate.value,
                                currency = viewModel.selectedCurrency.value,
                                customerName = completedCustomerName,
                                customerPhone = custPhone,
                                customerAddress = custAddress,
                                discount = discountAmount,
                                fee = feeAmount
                            )
                            val macAddress = viewModel.selectedPrinterMac.value
                            if (macAddress.isNotEmpty()) {
                                printBitmapToBluetoothPrinter(context, macAddress, bitmap)
                            } else {
                                android.widget.Toast.makeText(context, "Bluetooth Printer not configured in Settings. Sharing...", android.widget.Toast.LENGTH_LONG).show()
                                shareReceiptImage(context, bitmap)
                            }
                        },
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(52.dp),
                        colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                        shape = RoundedCornerShape(12.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Filled.Print,
                            contentDescription = "Print",
                            tint = Color.White
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(
                            text = "Print Receipt",
                            fontSize = 15.sp,
                            fontWeight = FontWeight.Bold,
                            color = Color.White
                        )
                    }

                    Spacer(modifier = Modifier.height(12.dp))

                    // Send Receipt Button
                    Button(
                        onClick = {
                            val matchedCustomer = customers.find { it.name == completedCustomerName }
                            val custPhone = matchedCustomer?.phone ?: ""
                            val custAddress = matchedCustomer?.address ?: ""
                            val bitmap = drawReceiptBitmap(
                                context = context,
                                storeName = "yyy",
                                phone = "092534",
                                receiptNo = completedVoucherId,
                                items = completedItems,
                                total = completedTotalAmount,
                                paid = completedPaidAmount,
                                change = completedChangeAmount,
                                timestamp = completedTimestamp,
                                paperWidth = viewModel.selectedPaperWidth.value,
                                printMode = viewModel.selectedPrintMode.value,
                                template = viewModel.selectedTemplate.value,
                                currency = viewModel.selectedCurrency.value,
                                customerName = completedCustomerName,
                                customerPhone = custPhone,
                                customerAddress = custAddress,
                                discount = discountAmount,
                                fee = feeAmount
                            )
                            shareReceiptImage(context, bitmap)
                        },
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(52.dp),
                        colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                        shape = RoundedCornerShape(12.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Filled.Send,
                            contentDescription = "Send",
                            tint = Color.White
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(
                            text = "Send Receipt",
                            fontSize = 15.sp,
                            fontWeight = FontWeight.Bold,
                            color = Color.White
                        )
                    }

                    Spacer(modifier = Modifier.height(12.dp))

                    // Finished Button
                    Button(
                        onClick = {
                            resetVoucherState()
                        },
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(52.dp),
                        colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                        shape = RoundedCornerShape(12.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Filled.Check,
                            contentDescription = "Finished",
                            tint = Color.White
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(
                            text = "Finished",
                            fontSize = 15.sp,
                            fontWeight = FontWeight.Bold,
                            color = Color.White
                        )
                    }

                    Spacer(modifier = Modifier.height(32.dp))
                }
            }
        }

    }

    // Customer Selection Dialog
    if (showCustomerDialog) {
        var customerSearchQuery by remember { mutableStateOf("") }
        var isCustomerSearching by remember { mutableStateOf(false) }

        androidx.compose.ui.window.Dialog(
            onDismissRequest = { showCustomerDialog = false },
            properties = androidx.compose.ui.window.DialogProperties(usePlatformDefaultWidth = false)
        ) {
            Scaffold(
                topBar = {
                    if (isCustomerSearching) {
                        TopAppBar(
                            title = {
                                OutlinedTextField(
                                    value = customerSearchQuery,
                                    onValueChange = { customerSearchQuery = it },
                                    placeholder = {
                                        Text(
                                            if (isPurchaseMode) "ကုန်သွင်းသူ ရှာရန်..." else "ဈေးဝယ်သူ ရှာရန်...",
                                            color = Color.LightGray,
                                            fontSize = 15.sp
                                        )
                                    },
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(vertical = 4.dp),
                                    singleLine = true,
                                    colors = OutlinedTextFieldDefaults.colors(
                                        focusedTextColor = AppTextColor,
                                        unfocusedTextColor = AppTextColor,
                                        focusedContainerColor = Color.Transparent,
                                        unfocusedContainerColor = Color.Transparent,
                                        disabledContainerColor = Color.Transparent,
                                        focusedBorderColor = Color.Transparent,
                                        unfocusedBorderColor = Color.Transparent,
                                    ),
                                    trailingIcon = {
                                        if (customerSearchQuery.isNotEmpty()) {
                                            IconButton(onClick = { customerSearchQuery = "" }) {
                                                Icon(imageVector = Icons.Filled.Close, contentDescription = "Clear", tint = Color.Gray)
                                            }
                                        }
                                    }
                                )
                            },
                            navigationIcon = {
                                IconButton(onClick = {
                                    isCustomerSearching = false
                                    customerSearchQuery = ""
                                }) {
                                    Icon(imageVector = Icons.Filled.Close, contentDescription = "Close Search", tint = AppTextColor)
                                }
                            },
                            colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.White)
                        )
                    } else {
                        TopAppBar(
                            title = {
                                Row(
                                    modifier = Modifier.fillMaxWidth().padding(end = 16.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text(if (isPurchaseMode) "ကုန်သွင်းသူများ" else "ဈေးဝယ်သူများ", fontWeight = FontWeight.Bold, fontSize = 18.sp, color = AppTextColor)
                                    val filteredCount = remember(customers, suppliers, isPurchaseMode, customerSearchQuery) {
                                        val list = if (isPurchaseMode) {
                                            listOf(Customer(name = "Not Register", phone = "", address = "")) + suppliers.map { Customer(id = it.id, name = it.name, phone = it.phone, address = it.address, note = it.note) }
                                        } else {
                                            listOf(Customer(name = "Not Register", phone = "", address = "")) + customers
                                        }
                                        if (customerSearchQuery.isEmpty()) {
                                            list.size
                                        } else {
                                            list.count { it.name.contains(customerSearchQuery, ignoreCase = true) || it.phone.contains(customerSearchQuery) }
                                        }
                                    }
                                    Text("$filteredCount item", fontSize = 13.sp, color = Color.Gray, fontWeight = FontWeight.Normal)
                                }
                            },
                            navigationIcon = {
                                IconButton(onClick = { showCustomerDialog = false }) {
                                    Icon(imageVector = Icons.Filled.ArrowBack, contentDescription = "Back")
                                }
                            },
                            actions = {
                                IconButton(onClick = { isCustomerSearching = true }) {
                                    Icon(imageVector = Icons.Filled.Search, contentDescription = "Search", tint = Color.Gray)
                                }
                            },
                            colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.White)
                        )
                    }
                },
                floatingActionButton = {
                    FloatingActionButton(
                        onClick = {
                            viewModel.editingCustomer.value = null
                            navController.navigate(if (isPurchaseMode) "add_supplier" else "add_customer")
                        },
                        containerColor = BrandPurple,
                        contentColor = Color.White,
                        shape = CircleShape,
                        modifier = Modifier.padding(bottom = 32.dp, end = 16.dp)
                    ) {
                        Icon(imageVector = Icons.Filled.Add, contentDescription = "Add")
                    }
                }
            ) { innerPadding ->
                Column(
                    modifier = Modifier
                        .fillMaxSize()
                        .background(LightBg)
                        .padding(innerPadding)
                ) {
                    val customerList = remember(customers, suppliers, isPurchaseMode, customerSearchQuery) {
                        val baseList = if (isPurchaseMode) {
                            listOf(Customer(name = "Not Register", phone = "", address = "")) + suppliers.map { Customer(id = it.id, name = it.name, phone = it.phone, address = it.address, note = it.note) }
                        } else {
                            listOf(Customer(name = "Not Register", phone = "", address = "")) + customers
                        }
                        if (customerSearchQuery.isEmpty()) {
                            baseList
                        } else {
                            baseList.filter {
                                it.name.contains(customerSearchQuery, ignoreCase = true) ||
                                it.phone.contains(customerSearchQuery)
                            }
                        }
                    }
                    LazyColumn(modifier = Modifier.fillMaxSize().padding(top = 8.dp)) {
                        items(customerList) { cust ->
                            Card(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(horizontal = 16.dp, vertical = 6.dp)
                                    .clickable {
                                        viewModel.activeCustomerName.value = cust.name
                                        showCustomerDialog = false
                                    },
                                colors = CardDefaults.cardColors(containerColor = Color.White),
                                shape = RoundedCornerShape(12.dp),
                                elevation = CardDefaults.cardElevation(1.dp)
                            ) {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(16.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .size(40.dp)
                                            .background(Color(0xFFF2F0F7), shape = CircleShape),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Icon(
                                            imageVector = Icons.Filled.Person,
                                            contentDescription = "Customer",
                                            tint = BrandPurple,
                                            modifier = Modifier.size(20.dp)
                                        )
                                    }
                                    Spacer(modifier = Modifier.width(16.dp))
                                    Column(modifier = Modifier.weight(1f)) {
                                        Text(cust.name, fontWeight = FontWeight.Bold, fontSize = 15.sp, color = AppTextColor)
                                        if (cust.phone.isNotEmpty()) {
                                            Spacer(modifier = Modifier.height(2.dp))
                                             Text(cust.phone, fontSize = 12.sp, color = Color.Gray)
                                        }
                                    }
                                    Icon(
                                        imageVector = Icons.Filled.ArrowForward,
                                        contentDescription = "Select",
                                        tint = Color.Gray
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    // Payment Method Selection Dialog
    if (showPaymentDialog) {
        androidx.compose.ui.window.Dialog(
            onDismissRequest = { showPaymentDialog = false },
            properties = androidx.compose.ui.window.DialogProperties(usePlatformDefaultWidth = false)
        ) {
            var paymentSearchQuery by remember { mutableStateOf("") }
            Scaffold(
                topBar = {
                    TopAppBar(
                        title = {
                            OutlinedTextField(
                                value = paymentSearchQuery,
                                onValueChange = { paymentSearchQuery = it },
                                placeholder = { Text("Enter Payment", color = Color.Gray, fontSize = 15.sp) },
                                leadingIcon = { Icon(imageVector = Icons.Filled.Search, contentDescription = "Search", tint = Color.Gray) },
                                trailingIcon = { Icon(imageVector = Icons.Filled.CreditCard, contentDescription = "Card", tint = Color.Gray) },
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(vertical = 4.dp),
                                shape = RoundedCornerShape(24.dp),
                                colors = OutlinedTextFieldDefaults.colors(
                                    focusedTextColor = Color(0xFF1C1B1F),
                                    unfocusedTextColor = Color(0xFF1C1B1F),
                                    focusedContainerColor = Color(0xFFF2F0F7),
                                    unfocusedContainerColor = Color(0xFFF2F0F7),
                                    focusedBorderColor = Color.Transparent,
                                    unfocusedBorderColor = Color.Transparent
                                ),
                                singleLine = true
                            )
                        },
                        navigationIcon = {
                            IconButton(onClick = { showPaymentDialog = false }) {
                                Icon(imageVector = Icons.Filled.ArrowBack, contentDescription = "Back")
                            }
                        },
                        colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.White)
                    )
                }
            ) { innerPadding ->
                Column(
                    modifier = Modifier
                        .fillMaxSize()
                        .background(LightBg)
                        .padding(innerPadding)
                        .padding(top = 8.dp)
                ) {
                    val dbPayments by viewModel.allPayments.collectAsState()
                    val paymentMethods = if (dbPayments.isNotEmpty()) dbPayments.map { it.method } else listOf("Cash", "Credit")
                    val filteredPayments = paymentMethods.filter { it.contains(paymentSearchQuery, ignoreCase = true) }
                    
                    LazyColumn(modifier = Modifier.fillMaxSize()) {
                        items(filteredPayments) { method ->
                            Card(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(horizontal = 16.dp, vertical = 6.dp)
                                    .clickable {
                                        viewModel.activePaymentMethod.value = method.uppercase(Locale.getDefault())
                                        showPaymentDialog = false
                                    },
                                colors = CardDefaults.cardColors(containerColor = Color.White),
                                shape = RoundedCornerShape(12.dp),
                                elevation = CardDefaults.cardElevation(1.dp)
                            ) {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(16.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .size(40.dp)
                                            .background(Color(0xFFF2F0F7), shape = CircleShape),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Icon(
                                            imageVector = when(method) {
                                                "Credit" -> Icons.Filled.CreditCard
                                                "Cash" -> Icons.Filled.Payments
                                                else -> Icons.Filled.AccountBalanceWallet
                                            },
                                            contentDescription = method,
                                            tint = BrandPurple,
                                            modifier = Modifier.size(20.dp)
                                        )
                                    }
                                    Spacer(modifier = Modifier.width(16.dp))
                                    Text(method, fontWeight = FontWeight.Bold, fontSize = 15.sp, color = AppTextColor, modifier = Modifier.weight(1f))
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    // Custom Dialog for Discount
    if (showDiscountDialog) {
        var localDiscount by remember { mutableStateOf(discountAmount.toInt().toString()) }
        AlertDialog(
            onDismissRequest = { showDiscountDialog = false },
            title = { Text("လျော့စျေးသတ်မှတ်ရန်", fontWeight = FontWeight.Bold) },
            text = {
                OutlinedTextField(
                    value = localDiscount,
                    onValueChange = { localDiscount = it },
                    label = { Text("လျော့စျေးပမာဏ ($selectedCurrency)") },
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                    singleLine = true,
                    modifier = Modifier.fillMaxWidth()
                )
            },
            confirmButton = {
                Button(
                    onClick = {
                        discountAmount = localDiscount.toDoubleOrNull() ?: 0.0
                        showDiscountDialog = false
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = BrandPurple)
                ) {
                    Text("သတ်မှတ်မည်", color = Color.White)
                }
            },
            dismissButton = {
                TextButton(onClick = { showDiscountDialog = false }) {
                    Text("ပယ်ဖျက်မည်")
                }
            }
        )
    }

    // Custom Dialog for Fee
    if (showFeeDialog) {
        var localFee by remember { mutableStateOf(feeAmount.toInt().toString()) }
        AlertDialog(
            onDismissRequest = { showFeeDialog = false },
            title = { Text("ဝန်ဆောင်ခသတ်မှတ်ရန်", fontWeight = FontWeight.Bold) },
            text = {
                OutlinedTextField(
                    value = localFee,
                    onValueChange = { localFee = it },
                    label = { Text("ဝန်ဆောင်ခပမာဏ ($selectedCurrency)") },
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                    singleLine = true,
                    modifier = Modifier.fillMaxWidth()
                )
            },
            confirmButton = {
                Button(
                    onClick = {
                        feeAmount = localFee.toDoubleOrNull() ?: 0.0
                        showFeeDialog = false
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = BrandPurple)
                ) {
                    Text("သတ်မှတ်မည်", color = Color.White)
                }
            },
            dismissButton = {
                TextButton(onClick = { showFeeDialog = false }) {
                    Text("ပယ်ဖျက်မည်")
                }
            }
        )
    }

    // Custom Dialog for Note
    if (showNoteDialog) {
        var localNote by remember { mutableStateOf(noteText) }
        AlertDialog(
            onDismissRequest = { showNoteDialog = false },
            title = { Text("မှတ်ချက်ရေးရန်", fontWeight = FontWeight.Bold) },
            text = {
                OutlinedTextField(
                    value = localNote,
                    onValueChange = { localNote = it },
                    label = { Text("မှတ်ချက်") },
                    singleLine = false,
                    maxLines = 4,
                    modifier = Modifier.fillMaxWidth()
                )
            },
            confirmButton = {
                Button(
                    onClick = {
                        noteText = localNote
                        showNoteDialog = false
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = BrandPurple)
                ) {
                    Text("သိမ်းဆည်းမည်", color = Color.White)
                }
            },
            dismissButton = {
                TextButton(onClick = { showNoteDialog = false }) {
                    Text("ပယ်ဖျက်မည်")
                }
            }
        )
    }

    // Delete item confirmation dialog as requested
    if (showDeleteItemConfirmDialog) {
        AlertDialog(
            onDismissRequest = { showDeleteItemConfirmDialog = false },
            title = { Text("Remove", fontWeight = FontWeight.Bold, fontSize = 18.sp) },
            text = { Text("ဘောက်ချာထဲမှဤကုန်ပစ္စည်းအားဖျက်မည်။", fontSize = 14.sp) },
            confirmButton = {
                Button(
                    onClick = {
                        showDeleteItemConfirmDialog = false
                        viewModel.updateCartItemQuantityByIndex(selectedCartItemIndex, 0)
                        isNewCartItemPending = false
                        selectedCartItemIndex = -1
                        screenState = editCartItemReturnState
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                    shape = RoundedCornerShape(24.dp)
                ) {
                    Text("Remove", color = Color.White, fontWeight = FontWeight.Bold)
                }
            },
            dismissButton = {
                TextButton(
                    onClick = { showDeleteItemConfirmDialog = false }
                ) {
                    Text("Cancel", color = BrandPurple, fontWeight = FontWeight.Bold)
                }
            },
            containerColor = Color.White
        )
    }

    // Bottom Sheet Drawer for Discount, Fee and Note (Now Side Drawer)
    if (showDiscountFeeSheet) {
        var localDiscount by remember(showDiscountFeeSheet) { mutableStateOf(discountAmount.toInt().toString()) }
        var localFee by remember(showDiscountFeeSheet) { mutableStateOf(feeAmount.toInt().toString()) }
        var localNote by remember(showDiscountFeeSheet) { mutableStateOf(noteText) }
        
        androidx.compose.ui.window.Dialog(
            onDismissRequest = { showDiscountFeeSheet = false },
            properties = androidx.compose.ui.window.DialogProperties(usePlatformDefaultWidth = false)
        ) {
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .background(Color.Black.copy(alpha = 0.4f))
                    .clickable { showDiscountFeeSheet = false },
                contentAlignment = Alignment.CenterEnd
            ) {
                Column(
                    modifier = Modifier
                        .widthIn(max = 360.dp)
                        .fillMaxHeight()
                        .background(Color.White, shape = RoundedCornerShape(topStart = 16.dp, bottomStart = 16.dp))
                        .clickable(enabled = false) {}
                        .padding(24.dp)
                ) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = "လျော့ဈေး၊ ဝန်ဆောင်ခနှင့် မှတ်ချက်",
                            fontWeight = FontWeight.Bold,
                            fontSize = 18.sp,
                            color = BrandPurple
                        )
                        IconButton(onClick = { showDiscountFeeSheet = false }) {
                            Icon(
                                imageVector = Icons.Filled.Close,
                                contentDescription = "Close",
                                tint = Color.Gray
                            )
                        }
                    }
                    
                    HorizontalDivider(modifier = Modifier.padding(vertical = 12.dp), color = Color(0xFFF2F2F2))
                    
                    Column(
                        modifier = Modifier
                            .weight(1f)
                            .verticalScroll(rememberScrollState())
                    ) {
                        OutlinedTextField(
                            value = localDiscount,
                            onValueChange = { newValue -> localDiscount = newValue.filter { it.isDigit() } },
                            label = { Text("လျော့ဈေးပမာဏ ($selectedCurrency)") },
                            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                            singleLine = true,
                            modifier = Modifier.fillMaxWidth(),
                            colors = OutlinedTextFieldDefaults.colors(
                                focusedBorderColor = BrandPurple,
                                focusedLabelColor = BrandPurple
                            )
                        )
                        
                        Spacer(modifier = Modifier.height(16.dp))
                        
                        OutlinedTextField(
                            value = localFee,
                            onValueChange = { newValue -> localFee = newValue.filter { it.isDigit() } },
                            label = { Text("ဝန်ဆောင်ခပမာဏ ($selectedCurrency)") },
                            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                            singleLine = true,
                            modifier = Modifier.fillMaxWidth(),
                            colors = OutlinedTextFieldDefaults.colors(
                                focusedBorderColor = BrandPurple,
                                focusedLabelColor = BrandPurple
                            )
                        )
                        
                        Spacer(modifier = Modifier.height(16.dp))
                        
                        OutlinedTextField(
                            value = localNote,
                            onValueChange = { localNote = it },
                            label = { Text("မှတ်ချက်") },
                            singleLine = false,
                            maxLines = 3,
                            modifier = Modifier.fillMaxWidth(),
                            colors = OutlinedTextFieldDefaults.colors(
                                focusedBorderColor = BrandPurple,
                                focusedLabelColor = BrandPurple
                            )
                        )
                        
                        Spacer(modifier = Modifier.height(24.dp))
                    }
                    
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        OutlinedButton(
                            onClick = { showDiscountFeeSheet = false },
                            modifier = Modifier
                                .weight(1f)
                                .height(48.dp),
                            border = BorderStroke(1.dp, Color.LightGray),
                            shape = RoundedCornerShape(10.dp)
                        ) {
                            Text("ပယ်ဖျက်မည်", color = Color.Gray, fontWeight = FontWeight.Bold)
                        }
                        Button(
                            onClick = {
                                discountAmount = localDiscount.toDoubleOrNull() ?: 0.0
                                feeAmount = localFee.toDoubleOrNull() ?: 0.0
                                noteText = localNote
                                showDiscountFeeSheet = false
                            },
                            modifier = Modifier
                                .weight(1f)
                                .height(48.dp),
                            colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                            shape = RoundedCornerShape(10.dp)
                        ) {
                            Text("သတ်မှတ်မည်", color = Color.White, fontWeight = FontWeight.Bold)
                        }
                    }
                }
            }
        }
    }
}

// 11. SALES HISTORY SCREEN
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun FilterDrawerContent(
    viewModel: POSViewModel,
    initialTab: Int,
    isPurchase: Boolean = false,
    onTabChanged: (Int) -> Unit,
    onCustomerSelected: (Customer?) -> Unit,
    onPaymentSelected: (String?) -> Unit,
    onClose: () -> Unit
) {
    val customers by viewModel.allCustomers.collectAsState()
    val suppliers by viewModel.allSuppliers.collectAsState()
    val payments by viewModel.allPayments.collectAsState()

    val targetList = remember(customers, suppliers, isPurchase) {
        if (isPurchase) {
            suppliers.map { Customer(id = it.id, name = it.name, phone = it.phone, address = it.address, note = it.note) }
        } else {
            customers
        }
    }
    
    var customerQuery by remember { mutableStateOf("") }
    var paymentQuery by remember { mutableStateOf("") }
    
    var showAddCustomerDialog by remember { mutableStateOf(false) }
    
    var newCustName by remember { mutableStateOf("") }
    var newCustPhone by remember { mutableStateOf("") }
    var newCustAddress by remember { mutableStateOf("") }
    var newCustNote by remember { mutableStateOf("") }
    
    val context = LocalContext.current
    
    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(Color.White)
            .padding(16.dp)
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(
                text = if (initialTab == 0) (if (isPurchase) "ကုန်သွင်းသူများ" else "ဈေးဝယ်သူများ") else "ငွေပေးချေမှုများ",
                fontWeight = FontWeight.Bold,
                fontSize = 18.sp,
                color = if (initialTab == 0) BrandPurple else Color(0xFF2E7D32)
            )
            IconButton(onClick = onClose) {
                Icon(imageVector = Icons.Filled.Close, contentDescription = "Close")
            }
        }
        
        Spacer(modifier = Modifier.height(16.dp))
        
        Box(modifier = Modifier.weight(1f)) {
            if (initialTab == 0) {
                Column(modifier = Modifier.fillMaxSize()) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = if (isPurchase) "ကုန်သွင်းသူများ" else "ဈေးဝယ်သူများ",
                            fontWeight = FontWeight.SemiBold,
                            fontSize = 14.sp,
                            color = Color.Gray
                        )
                        Text(
                            text = "${targetList.size} items",
                            fontSize = 12.sp,
                            color = Color.LightGray
                        )
                    }
                    
                    Spacer(modifier = Modifier.height(8.dp))
                    
                    OutlinedTextField(
                        value = customerQuery,
                        onValueChange = { customerQuery = it },
                        modifier = Modifier.fillMaxWidth(),
                        placeholder = { Text(if (isPurchase) "ကုန်သွင်းသူ ရှာရန်..." else "ဈေးဝယ်သူ ရှာရန်...") },
                        leadingIcon = { Icon(Icons.Filled.Search, contentDescription = null, tint = Color.Gray) },
                        singleLine = true,
                        shape = RoundedCornerShape(12.dp),
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedBorderColor = BrandPurple,
                            unfocusedBorderColor = Color.LightGray
                        )
                    )
                    
                    Spacer(modifier = Modifier.height(12.dp))
                    
                    val filteredCustomers = remember(targetList, customerQuery) {
                        targetList.filter {
                            it.name.contains(customerQuery, ignoreCase = true) ||
                            it.phone.contains(customerQuery, ignoreCase = true)
                        }
                    }
                    
                    if (filteredCustomers.isEmpty()) {
                        Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                            Text(if (isPurchase) "ကုန်သွင်းသူမရှိပါ" else "ဈေးဝယ်သူမရှိပါ", color = Color.Gray)
                        }
                    } else {
                        LazyColumn(
                            modifier = Modifier.fillMaxWidth(),
                            verticalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            item {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable { onCustomerSelected(null) }
                                        .padding(vertical = 12.dp, horizontal = 4.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .size(40.dp)
                                            .background(BrandPurple.copy(alpha = 0.1f), CircleShape),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Icon(
                                            imageVector = Icons.Filled.People,
                                            contentDescription = null,
                                            tint = BrandPurple,
                                            modifier = Modifier.size(20.dp)
                                        )
                                    }
                                    
                                    Spacer(modifier = Modifier.width(12.dp))
                                    
                                    Text(
                                        text = if (isPurchase) "ကုန်သွင်းသူများ အားလုံး (All Suppliers)" else "ဈေးဝယ်သူများ အားလုံး (All Customers)",
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 14.sp,
                                        color = BrandPurple
                                    )
                                }
                                HorizontalDivider(color = Color(0xFFF3F1F6), thickness = 1.dp)
                            }
                            
                            items(filteredCustomers) { customer ->
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable { onCustomerSelected(customer) }
                                        .padding(vertical = 8.dp, horizontal = 4.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .size(40.dp)
                                            .background(Color(0xFFEDE7F6), CircleShape),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Icon(
                                            imageVector = Icons.Filled.Person,
                                            contentDescription = null,
                                            tint = BrandPurple,
                                            modifier = Modifier.size(20.dp)
                                        )
                                    }
                                    
                                    Spacer(modifier = Modifier.width(12.dp))
                                    
                                    Column(modifier = Modifier.weight(1f)) {
                                        Text(
                                            text = customer.name,
                                            fontWeight = FontWeight.Bold,
                                            fontSize = 14.sp
                                        )
                                        if (customer.phone.isNotEmpty()) {
                                            Text(
                                                text = customer.phone,
                                                fontSize = 12.sp,
                                                color = Color.Gray
                                            )
                                        } else if (customer.note.isNotEmpty()) {
                                            Text(
                                                text = customer.note,
                                                fontSize = 12.sp,
                                                color = Color.Gray
                                            )
                                        }
                                    }
                                    
                                    Icon(
                                        imageVector = Icons.Filled.KeyboardArrowRight,
                                        contentDescription = null,
                                        tint = Color.LightGray
                                    )
                                }
                            }
                        }
                    }
                }
                
                FloatingActionButton(
                    onClick = { showAddCustomerDialog = true },
                    modifier = Modifier
                        .align(Alignment.BottomEnd)
                        .padding(16.dp),
                    containerColor = BrandPurple,
                    contentColor = Color.White
                ) {
                    Icon(imageVector = Icons.Filled.Add, contentDescription = if (isPurchase) "Add Supplier" else "Add Customer")
                }
            } else {
                Column(modifier = Modifier.fillMaxSize()) {
                    Text(
                        text = "ငွေပေးချေမှုများ",
                        fontWeight = FontWeight.SemiBold,
                        fontSize = 14.sp,
                        color = Color.Gray
                    )
                    
                    Spacer(modifier = Modifier.height(8.dp))
                    
                    OutlinedTextField(
                        value = paymentQuery,
                        onValueChange = { paymentQuery = it },
                        modifier = Modifier.fillMaxWidth(),
                        placeholder = { Text("Enter Payment") },
                        leadingIcon = { Icon(Icons.Filled.Search, contentDescription = null, tint = Color.Gray) },
                        singleLine = true,
                        shape = RoundedCornerShape(12.dp),
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedBorderColor = BrandPurple,
                            unfocusedBorderColor = Color.LightGray
                        )
                    )
                    
                    Spacer(modifier = Modifier.height(12.dp))
                    
                    val allPaymentMethods = remember(payments) {
                        payments.map { it.method }.distinct()
                    }
                    
                    val filteredPayments = remember(allPaymentMethods, paymentQuery) {
                        allPaymentMethods.filter {
                            it.contains(paymentQuery, ignoreCase = true)
                        }
                    }
                    
                    LazyColumn(
                        modifier = Modifier.fillMaxWidth(),
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        item {
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable { onPaymentSelected(null) }
                                    .padding(vertical = 12.dp, horizontal = 4.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(40.dp)
                                        .background(Color(0xFFE8F5E9), CircleShape),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        imageVector = Icons.Filled.Payments,
                                        contentDescription = null,
                                        tint = Color(0xFF2E7D32),
                                        modifier = Modifier.size(20.dp)
                                    )
                                }
                                
                                Spacer(modifier = Modifier.width(12.dp))
                                
                                Text(
                                    text = "ငွေပေးချေမှု အားလုံး (All Payments)",
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 14.sp,
                                    color = Color(0xFF2E7D32)
                                )
                            }
                            HorizontalDivider(color = Color(0xFFF3F1F6), thickness = 1.dp)
                        }
                        
                        items(filteredPayments) { method ->
                            val displayMethod = method.replaceFirstChar { if (it.isLowerCase()) it.titlecase(Locale.getDefault()) else it.toString() }
                            val icon = when {
                                method.equals("cash", ignoreCase = true) -> Icons.Filled.Payments
                                method.equals("credit", ignoreCase = true) -> Icons.Filled.CreditCard
                                else -> Icons.Filled.Smartphone
                            }
                            
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable { onPaymentSelected(displayMethod) }
                                    .padding(vertical = 12.dp, horizontal = 4.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(40.dp)
                                        .background(Color(0xFFEDE7F6), CircleShape),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        imageVector = icon,
                                        contentDescription = null,
                                        tint = BrandPurple,
                                        modifier = Modifier.size(20.dp)
                                    )
                                }
                                
                                Spacer(modifier = Modifier.width(12.dp))
                                
                                Text(
                                    text = displayMethod,
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 15.sp,
                                    modifier = Modifier.weight(1f)
                                )
                                
                                Icon(
                                    imageVector = Icons.Filled.Edit,
                                    contentDescription = "Edit",
                                    tint = Color.LightGray.copy(alpha = 0.6f),
                                    modifier = Modifier.size(16.dp)
                                )
                            }
                        }
                    }
                }
            }
        }
    }
    
    if (showAddCustomerDialog) {
        AlertDialog(
            onDismissRequest = { showAddCustomerDialog = false },
            title = { Text(if (isPurchase) "ကုန်သွင်းသူအသစ်ထည့်ရန်" else "ဈေးဝယ်သူအသစ်ထည့်ရန်", fontWeight = FontWeight.Bold, fontSize = 18.sp) },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    OutlinedTextField(
                        value = newCustName,
                        onValueChange = { newCustName = it },
                        label = { Text("အမည်*") },
                        modifier = Modifier.fillMaxWidth()
                    )
                    OutlinedTextField(
                        value = newCustPhone,
                        onValueChange = { newCustPhone = it },
                        label = { Text("ဖုန်းနံပါတ်") },
                        modifier = Modifier.fillMaxWidth()
                    )
                    OutlinedTextField(
                        value = newCustAddress,
                        onValueChange = { newCustAddress = it },
                        label = { Text("လိပ်စာ") },
                        modifier = Modifier.fillMaxWidth()
                    )
                    OutlinedTextField(
                        value = newCustNote,
                        onValueChange = { newCustNote = it },
                        label = { Text("မှတ်ချက်") },
                        modifier = Modifier.fillMaxWidth()
                    )
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        if (newCustName.isNotBlank()) {
                            if (isPurchase) {
                                viewModel.addSupplier(
                                    name = newCustName,
                                    phone = newCustPhone,
                                    address = newCustAddress,
                                    note = newCustNote,
                                    onSuccess = {
                                        android.widget.Toast.makeText(context, "သိမ်းဆည်းပြီးပါပြီ", android.widget.Toast.LENGTH_SHORT).show()
                                    }
                                )
                            } else {
                                viewModel.addCustomer(
                                    name = newCustName,
                                    phone = newCustPhone,
                                    address = newCustAddress,
                                    note = newCustNote,
                                    onSuccess = {
                                        android.widget.Toast.makeText(context, "သိမ်းဆည်းပြီးပါပြီ", android.widget.Toast.LENGTH_SHORT).show()
                                    }
                                )
                            }
                            showAddCustomerDialog = false
                            newCustName = ""
                            newCustPhone = ""
                            newCustAddress = ""
                            newCustNote = ""
                        } else {
                            android.widget.Toast.makeText(context, "အမည်ဖြည့်စွက်ပါ", android.widget.Toast.LENGTH_SHORT).show()
                        }
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = BrandPurple)
                ) {
                    Text("သိမ်းဆည်းမည်", color = Color.White)
                }
            },
            dismissButton = {
                TextButton(onClick = { showAddCustomerDialog = false }) {
                    Text("မလုပ်တော့ပါ", color = Color.Gray)
                }
            }
        )
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun SalesHistoryScreen(navController: NavController, viewModel: POSViewModel) {
    val vouchers by viewModel.allVouchers.collectAsState()
    val isPurchaseHistoryMode by viewModel.isPurchaseHistoryMode.collectAsState()
    val selectedCurrency by viewModel.selectedCurrency.collectAsState()
    val calendar = remember { mutableStateOf(Calendar.getInstance()) }
    val filterMode = remember { mutableStateOf("month") }
    val selectedCustomer = remember { mutableStateOf<Customer?>(null) }
    val selectedPaymentMethod = remember { mutableStateOf<String?>(null) }
    val drawerState = rememberDrawerState(initialValue = DrawerValue.Closed)
    val coroutineScope = rememberCoroutineScope()
    val showMenu = remember { mutableStateOf(false) }
    var drawerTab by remember { mutableStateOf(0) }
    var voucherToDelete by remember { mutableStateOf<Voucher?>(null) }

    val filteredVouchers = remember(vouchers, filterMode.value, calendar.value, selectedCustomer.value, selectedPaymentMethod.value, isPurchaseHistoryMode) {
        vouchers.filter { voucher ->
            val inDateRange = if (filterMode.value == "month") {
                val startCal = (calendar.value.clone() as Calendar).apply {
                    set(Calendar.DAY_OF_MONTH, 1)
                    set(Calendar.HOUR_OF_DAY, 0)
                    set(Calendar.MINUTE, 0)
                    set(Calendar.SECOND, 0)
                    set(Calendar.MILLISECOND, 0)
                }
                val endCal = (calendar.value.clone() as Calendar).apply {
                    set(Calendar.DAY_OF_MONTH, getActualMaximum(Calendar.DAY_OF_MONTH))
                    set(Calendar.HOUR_OF_DAY, 23)
                    set(Calendar.MINUTE, 59)
                    set(Calendar.SECOND, 59)
                    set(Calendar.MILLISECOND, 999)
                }
                voucher.timestamp in startCal.timeInMillis..endCal.timeInMillis
            } else {
                val startCal = (calendar.value.clone() as Calendar).apply {
                    set(Calendar.HOUR_OF_DAY, 0)
                    set(Calendar.MINUTE, 0)
                    set(Calendar.SECOND, 0)
                    set(Calendar.MILLISECOND, 0)
                }
                val endCal = (calendar.value.clone() as Calendar).apply {
                    set(Calendar.HOUR_OF_DAY, 23)
                    set(Calendar.MINUTE, 59)
                    set(Calendar.SECOND, 59)
                    set(Calendar.MILLISECOND, 999)
                }
                voucher.timestamp in startCal.timeInMillis..endCal.timeInMillis
            }
            
            val matchesCustomer = if (selectedCustomer.value != null) {
                voucher.customerName.equals(selectedCustomer.value!!.name, ignoreCase = true)
            } else {
                true
            }
            
            val matchesPayment = if (selectedPaymentMethod.value != null) {
                voucher.paymentMethod.equals(selectedPaymentMethod.value!!, ignoreCase = true)
            } else {
                true
            }
            
            inDateRange && matchesCustomer && matchesPayment && voucher.isPurchase == isPurchaseHistoryMode && voucher.isCompleted
        }
    }

    CompositionLocalProvider(LocalLayoutDirection provides LayoutDirection.Rtl) {
        ModalNavigationDrawer(
            drawerState = drawerState,
            drawerContent = {
                CompositionLocalProvider(LocalLayoutDirection provides LayoutDirection.Ltr) {
                    ModalDrawerSheet(
                        drawerContainerColor = Color.White,
                        modifier = Modifier.width(320.dp)
                    ) {
                        FilterDrawerContent(
                            viewModel = viewModel,
                            initialTab = drawerTab,
                            isPurchase = isPurchaseHistoryMode,
                            onTabChanged = { drawerTab = it },
                            onCustomerSelected = { customer ->
                                selectedCustomer.value = customer
                                coroutineScope.launch { drawerState.close() }
                            },
                            onPaymentSelected = { payment ->
                                selectedPaymentMethod.value = payment
                                coroutineScope.launch { drawerState.close() }
                            },
                            onClose = {
                                coroutineScope.launch { drawerState.close() }
                            }
                        )
                    }
                }
            }
        ) {
            CompositionLocalProvider(LocalLayoutDirection provides LayoutDirection.Ltr) {
                Scaffold(
                    topBar = {
                        TopAppBar(
                            title = {
                                Text(
                                    text = if (isPurchaseHistoryMode) "Purchase Receipt" else "Sale Receipt",
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 18.sp,
                                    color = Color.Black
                                )
                            },
                            navigationIcon = {
                                IconButton(onClick = { navController.popBackStack() }) {
                                    Icon(imageVector = Icons.Filled.ArrowBack, contentDescription = "Back", tint = BrandPurple)
                                }
                            },
                            actions = {
                                // Customer Icon
                                IconButton(
                                    onClick = {
                                        drawerTab = 0
                                        coroutineScope.launch { drawerState.open() }
                                    }
                                ) {
                                    Icon(
                                        imageVector = Icons.Filled.Person,
                                        contentDescription = "Customers Filter",
                                        tint = Color(0xFF1E88E5)
                                    )
                                }
                                
                                // Payment Icon
                                IconButton(
                                    onClick = {
                                        drawerTab = 1
                                        coroutineScope.launch { drawerState.open() }
                                    }
                                ) {
                                    Icon(
                                        imageVector = Icons.Filled.Payments,
                                        contentDescription = "Payments Filter",
                                        tint = Color(0xFF00897B)
                                    )
                                }
                                
                                // Calendar/Date Icon
                                Box {
                                    IconButton(onClick = { showMenu.value = true }) {
                                        Icon(imageVector = Icons.Filled.CalendarMonth, contentDescription = "Date/Month Filter", tint = Color(0xFF5E35B1))
                                    }
                                    DropdownMenu(
                                        expanded = showMenu.value,
                                        onDismissRequest = { showMenu.value = false }
                                    ) {
                                        DropdownMenuItem(
                                            text = { Text("ရက်အလိုက်") },
                                            leadingIcon = { Icon(imageVector = Icons.Filled.Today, contentDescription = null) },
                                            onClick = {
                                                filterMode.value = "date"
                                                showMenu.value = false
                                            }
                                        )
                                        DropdownMenuItem(
                                            text = { Text("လအလိုက်") },
                                            leadingIcon = { Icon(imageVector = Icons.Filled.CalendarMonth, contentDescription = null) },
                                            onClick = {
                                                filterMode.value = "month"
                                                showMenu.value = false
                                            }
                                        )
                                    }
                                }
                            },
                            colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.White)
                        )
                    },
                    modifier = Modifier.fillMaxSize()
                ) { innerPadding ->
                    Column(
                        modifier = Modifier
                            .fillMaxSize()
                            .background(LightBg)
                            .padding(innerPadding)
                    ) {
                        // Date/Month Switcher Row (inline card right below topbar)
                        Card(
                            colors = CardDefaults.cardColors(containerColor = Color.White),
                            shape = RoundedCornerShape(12.dp),
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(horizontal = 16.dp, vertical = 8.dp),
                            elevation = CardDefaults.cardElevation(1.dp)
                        ) {
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(vertical = 4.dp, horizontal = 8.dp),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                IconButton(
                                    onClick = {
                                        val newCal = calendar.value.clone() as Calendar
                                        if (filterMode.value == "month") {
                                            newCal.add(Calendar.MONTH, -1)
                                        } else {
                                            newCal.add(Calendar.DATE, -1)
                                        }
                                        calendar.value = newCal
                                    }
                                ) {
                                    Icon(
                                        imageVector = Icons.Filled.KeyboardArrowLeft,
                                        contentDescription = "Previous",
                                        tint = Color.DarkGray
                                    )
                                }
                                
                                val displayText = remember(calendar.value, filterMode.value) {
                                    if (filterMode.value == "month") {
                                        SimpleDateFormat("MMMM yyyy", Locale.US).format(calendar.value.time)
                                    } else {
                                        SimpleDateFormat("dd/MM/yyyy EEE", Locale.US).format(calendar.value.time)
                                    }
                                }
                                
                                Text(
                                    text = displayText,
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 15.sp,
                                    color = Color.DarkGray
                                )
                                
                                IconButton(
                                    onClick = {
                                        val newCal = calendar.value.clone() as Calendar
                                        if (filterMode.value == "month") {
                                            newCal.add(Calendar.MONTH, 1)
                                        } else {
                                            newCal.add(Calendar.DATE, 1)
                                        }
                                        calendar.value = newCal
                                    }
                                ) {
                                    Icon(
                                        imageVector = Icons.Filled.KeyboardArrowRight,
                                        contentDescription = "Next",
                                        tint = Color.DarkGray
                                    )
                                }
                            }
                        }
                        
                        // Selected Customer / Selected Payment Filter Display Banner (Always positioned here consistently)
                        if (selectedCustomer.value != null || selectedPaymentMethod.value != null) {
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(horizontal = 16.dp, vertical = 4.dp),
                                horizontalArrangement = Arrangement.spacedBy(8.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                selectedCustomer.value?.let { customer ->
                                    Card(
                                        colors = CardDefaults.cardColors(containerColor = Color(0xFFF3EFFF)),
                                        shape = RoundedCornerShape(8.dp),
                                        border = BorderStroke(1.dp, BrandPurple.copy(alpha = 0.3f)),
                                        modifier = Modifier.weight(1f)
                                    ) {
                                        Row(
                                            modifier = Modifier.fillMaxWidth().padding(horizontal = 12.dp, vertical = 8.dp),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Row(verticalAlignment = Alignment.CenterVertically) {
                                                Icon(
                                                    imageVector = Icons.Filled.Person,
                                                    contentDescription = null,
                                                    tint = BrandPurple,
                                                    modifier = Modifier.size(16.dp)
                                                )
                                                Spacer(modifier = Modifier.width(6.dp))
                                                Text(
                                                    text = customer.name,
                                                    fontSize = 13.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = BrandPurple,
                                                    maxLines = 1,
                                                    overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis
                                                )
                                            }
                                            IconButton(
                                                onClick = { selectedCustomer.value = null },
                                                modifier = Modifier.size(18.dp)
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Filled.Close,
                                                    contentDescription = "Clear",
                                                    tint = Color.Gray,
                                                    modifier = Modifier.size(12.dp)
                                                )
                                            }
                                        }
                                    }
                                }
                                
                                selectedPaymentMethod.value?.let { payment ->
                                    Card(
                                        colors = CardDefaults.cardColors(containerColor = Color(0xFFE8F5E9)),
                                        shape = RoundedCornerShape(8.dp),
                                        border = BorderStroke(1.dp, Color(0xFF2E7D32).copy(alpha = 0.3f)),
                                        modifier = Modifier.weight(1f)
                                    ) {
                                        Row(
                                            modifier = Modifier.fillMaxWidth().padding(horizontal = 12.dp, vertical = 8.dp),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Row(verticalAlignment = Alignment.CenterVertically) {
                                                Icon(
                                                    imageVector = Icons.Filled.Payments,
                                                    contentDescription = null,
                                                    tint = Color(0xFF2E7D32),
                                                    modifier = Modifier.size(16.dp)
                                                )
                                                Spacer(modifier = Modifier.width(6.dp))
                                                Text(
                                                    text = payment,
                                                    fontSize = 13.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = Color(0xFF2E7D32),
                                                    maxLines = 1,
                                                    overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis
                                                )
                                            }
                                            IconButton(
                                                onClick = { selectedPaymentMethod.value = null },
                                                modifier = Modifier.size(18.dp)
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Filled.Close,
                                                    contentDescription = "Clear",
                                                    tint = Color.Gray,
                                                    modifier = Modifier.size(12.dp)
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }
                        
                        // Main history list block
                        Box(
                            modifier = Modifier
                                .weight(1f)
                                .fillMaxWidth()
                        ) {
                            if (filteredVouchers.isEmpty()) {
                                Column(
                                    modifier = Modifier.fillMaxSize(),
                                    horizontalAlignment = Alignment.CenterHorizontally,
                                    verticalArrangement = Arrangement.Center
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .size(100.dp)
                                            .background(Color(0xFFEDE7F6), CircleShape),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Icon(
                                            imageVector = Icons.Filled.ReceiptLong,
                                            contentDescription = "Empty",
                                            modifier = Modifier.size(48.dp),
                                            tint = BrandPurple
                                        )
                                    }
                                    Spacer(modifier = Modifier.height(16.dp))
                                    Text(
                                        text = "No Receipts Found",
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 16.sp,
                                        color = Color.Gray
                                    )
                                }
                            } else {
                                LazyColumn(
                                    modifier = Modifier
                                        .fillMaxSize()
                                        .padding(horizontal = 12.dp, vertical = 6.dp)
                                ) {
                                    items(filteredVouchers) { voucher: Voucher ->
                                        val dateString = remember(voucher.timestamp) {
                                            val sdf = SimpleDateFormat("dd/MM/yyyy hh:mm a", Locale.getDefault())
                                            sdf.format(Date(voucher.timestamp))
                                        }
                                        
                                        var showDetails by remember { mutableStateOf(false) }
                                        var itemsList by remember { mutableStateOf<List<VoucherItem>>(emptyList()) }
                                        
                                        LaunchedEffect(showDetails) {
                                            if (showDetails) {
                                                val db = AppDatabase.getDatabase(navController.context)
                                                itemsList = db.voucherDao().getVoucherItemsDirect(voucher.receiptNo)
                                            }
                                        }
                                        
                                        val isRegisteredCustomer = voucher.customerName != "Not Register" && voucher.customerName.isNotBlank()
                                        val titleText = if (isRegisteredCustomer) voucher.customerName else "Receipt ${voucher.receiptNo}"
                                        val numberFormat = remember { NumberFormat.getNumberInstance(Locale.US) }
                                        
                                        Card(
                                            colors = CardDefaults.cardColors(containerColor = Color.White),
                                            shape = RoundedCornerShape(12.dp),
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .padding(vertical = 4.dp)
                                                .clickable { navController.navigate("receipt_detail/${voucher.receiptNo}") },
                                            elevation = CardDefaults.cardElevation(2.dp)
                                        ) {
                                            Column(modifier = Modifier.padding(16.dp)) {
                                                Row(
                                                    modifier = Modifier.fillMaxWidth(),
                                                    verticalAlignment = Alignment.CenterVertically
                                                ) {
                                                    Box(
                                                        modifier = Modifier
                                                            .size(44.dp)
                                                            .background(Color(0xFFEDE7F6), RoundedCornerShape(10.dp)),
                                                        contentAlignment = Alignment.Center
                                                    ) {
                                                        Icon(
                                                            imageVector = Icons.Filled.ReceiptLong,
                                                            contentDescription = "Receipt Icon",
                                                            tint = BrandPurple,
                                                            modifier = Modifier.size(24.dp)
                                                        )
                                                    }
                                                    
                                                    Spacer(modifier = Modifier.width(12.dp))
                                                    
                                                    Column(modifier = Modifier.weight(1f)) {
                                                        Text(
                                                            text = titleText,
                                                            fontWeight = FontWeight.Bold,
                                                            fontSize = 14.sp,
                                                            color = Color.Black
                                                        )
                                                        Spacer(modifier = Modifier.height(2.dp))
                                                        Text(
                                                            text = dateString,
                                                            fontSize = 11.sp,
                                                            color = Color.Gray
                                                        )
                                                        if (isRegisteredCustomer) {
                                                            Spacer(modifier = Modifier.height(2.dp))
                                                            Text(
                                                                text = "#${voucher.receiptNo}",
                                                                fontSize = 11.sp,
                                                                color = Color.Gray
                                                            )
                                                        }
                                                    }
                                                    
                                                    Column(horizontalAlignment = Alignment.End) {
                                                        Text(
                                                            text = "${numberFormat.format(voucher.totalAmount.toInt())} $selectedCurrency",
                                                            fontWeight = FontWeight.Bold,
                                                            fontSize = 14.sp,
                                                            color = Color.Black
                                                        )
                                                        
                                                        Spacer(modifier = Modifier.height(6.dp))
                                                        
                                                        val (bg, txt, iconEmoji) = when {
                                                            voucher.paymentMethod.equals("cash", ignoreCase = true) -> Triple(Color(0xFFE8F5E9), Color(0xFF2E7D32), "💵 CASH")
                                                            voucher.paymentMethod.equals("credit", ignoreCase = true) -> Triple(Color(0xFFFFF3E0), Color(0xFFE65100), "💳 Credit")
                                                            else -> Triple(Color(0xFFE3F2FD), Color(0xFF1565C0), "📱 ${voucher.paymentMethod}")
                                                        }
                                                        
                                                        Box(
                                                            modifier = Modifier
                                                                .background(bg, RoundedCornerShape(6.dp))
                                                                .clickable {
                                                                    drawerTab = 1
                                                                    coroutineScope.launch { drawerState.open() }
                                                                }
                                                                .padding(horizontal = 8.dp, vertical = 4.dp)
                                                        ) {
                                                            Text(
                                                                text = iconEmoji,
                                                                fontSize = 10.sp,
                                                                fontWeight = FontWeight.Bold,
                                                                color = txt
                                                            )
                                                        }
                                                    }
                                                }
                                                
                                                AnimatedVisibility(visible = showDetails) {
                                                    Column(modifier = Modifier.padding(top = 12.dp)) {
                                                        HorizontalDivider(color = Color.LightGray)
                                                        Spacer(modifier = Modifier.height(8.dp))
                                                        Text("Items sold:", fontWeight = FontWeight.Bold, fontSize = 12.sp, color = BrandPurple)
                                                        
                                                        itemsList.forEach { item ->
                                                            Row(
                                                                modifier = Modifier
                                                                    .fillMaxWidth()
                                                                    .padding(vertical = 4.dp),
                                                                horizontalArrangement = Arrangement.SpaceBetween
                                                            ) {
                                                                Text(
                                                                    text = "${item.productName} (x${item.quantity})",
                                                                    fontSize = 12.sp,
                                                                    fontWeight = FontWeight.Medium
                                                                )
                                                                Text(
                                                                    text = "${numberFormat.format((item.sellingPrice * item.quantity).toInt())} $selectedCurrency",
                                                                    fontSize = 12.sp,
                                                                    fontWeight = FontWeight.Bold
                                                                )
                                                            }
                                                        }

                                                        Spacer(modifier = Modifier.height(12.dp))
                                                        Row(
                                                            modifier = Modifier.fillMaxWidth(),
                                                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                                                        ) {
                                                            Button(
                                                                onClick = {
                                                                    viewModel.loadDraftVoucher(voucher)
                                                                    navController.navigate("new_voucher") {
                                                                        popUpTo("new_voucher") { inclusive = true }
                                                                    }
                                                                },
                                                                colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                                                                shape = RoundedCornerShape(8.dp),
                                                                modifier = Modifier.weight(1.2f),
                                                                contentPadding = PaddingValues(horizontal = 8.dp, vertical = 4.dp)
                                                            ) {
                                                                Icon(
                                                                    imageVector = Icons.Filled.Edit,
                                                                    contentDescription = "Edit",
                                                                    modifier = Modifier.size(16.dp),
                                                                    tint = Color.White
                                                                )
                                                                Spacer(modifier = Modifier.width(6.dp))
                                                                Text("ပြင်မည်", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = Color.White)
                                                            }

                                                            Button(
                                                                onClick = {
                                                                    voucherToDelete = voucher
                                                                },
                                                                colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFD32F2F)),
                                                                shape = RoundedCornerShape(8.dp),
                                                                modifier = Modifier.weight(1f),
                                                                contentPadding = PaddingValues(horizontal = 8.dp, vertical = 4.dp)
                                                            ) {
                                                                Icon(
                                                                    imageVector = Icons.Filled.Delete,
                                                                    contentDescription = "Delete",
                                                                    modifier = Modifier.size(16.dp),
                                                                    tint = Color.White
                                                                )
                                                                Spacer(modifier = Modifier.width(6.dp))
                                                                Text("ဖျက်မည်", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = Color.White)
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                        
                        // Total Sum Footer (Always Pinned Symmetrically at the Very Bottom of the Screen!)
                        val totalSum = filteredVouchers.sumOf { it.totalAmount }
                        val numberFormat = remember { NumberFormat.getNumberInstance(Locale.US) }
                        Card(
                            colors = CardDefaults.cardColors(containerColor = Color.White),
                            shape = RoundedCornerShape(topStart = 16.dp, topEnd = 16.dp),
                            elevation = CardDefaults.cardElevation(12.dp),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(horizontal = 24.dp, vertical = 16.dp),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = "စုစုပေါင်း",
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 16.sp,
                                    color = Color.Black
                                )
                                Text(
                                    text = "${numberFormat.format(totalSum.toInt())} $selectedCurrency",
                                    fontWeight = FontWeight.ExtraBold,
                                    fontSize = 20.sp,
                                    color = BrandPurple
                                )
                            }
                        }
                    }
                }
            }
        }
    }

    if (voucherToDelete != null) {
        AlertDialog(
            onDismissRequest = { voucherToDelete = null },
            title = {
                Text(
                    text = "ဘောက်ချာဖျက်ရန် အတည်ပြုပါ",
                    fontWeight = FontWeight.Bold,
                    fontSize = 18.sp,
                    color = Color.Black
                )
            },
            text = {
                Text(
                    text = "ဘောက်ချာအမှတ် #${voucherToDelete?.receiptNo} ကို ဖျက်ရန် သေချာပါသလား?",
                    fontSize = 14.sp,
                    color = Color.DarkGray
                )
            },
            confirmButton = {
                Button(
                    onClick = {
                        val currentVoucher = voucherToDelete
                        if (currentVoucher != null) {
                            viewModel.deleteVoucher(currentVoucher.receiptNo)
                        }
                        voucherToDelete = null
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFD32F2F)),
                    shape = RoundedCornerShape(8.dp)
                ) {
                    Text("ဖျက်မည်", fontWeight = FontWeight.Bold, color = Color.White)
                }
            },
            dismissButton = {
                OutlinedButton(
                    onClick = { voucherToDelete = null },
                    shape = RoundedCornerShape(8.dp)
                ) {
