// Helper to scan/fetch Bluetooth devices with simulation fallback
fun getBluetoothDevices(context: Context): List<Pair<String, String>> {
    val deviceList = mutableListOf<Pair<String, String>>()
    val hasPermission = if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.S) {
        ContextCompat.checkSelfPermission(context, android.Manifest.permission.BLUETOOTH_CONNECT) == PackageManager.PERMISSION_GRANTED
    } else {
        ContextCompat.checkSelfPermission(context, android.Manifest.permission.BLUETOOTH) == PackageManager.PERMISSION_GRANTED
    }
    
    if (hasPermission) {
        try {
            val bluetoothAdapter: BluetoothAdapter? = BluetoothAdapter.getDefaultAdapter()
            if (bluetoothAdapter != null && bluetoothAdapter.isEnabled) {
                val pairedDevices: Set<BluetoothDevice>? = bluetoothAdapter.bondedDevices
                pairedDevices?.forEach { device ->
                    val name = device.name ?: "Unknown Device"
                    val address = device.address ?: "00:00:00:00:00:00"
                    deviceList.add(Pair(name, address))
                }
            }
        } catch (e: Exception) {
            e.printStackTrace()
        }
    }
    return deviceList
}

@Composable
