// 12. SETTINGS SCREEN
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun SettingsScreen(navController: NavController, viewModel: POSViewModel) {
    var currentSubScreen by remember { mutableStateOf("main") }
    val context = LocalContext.current
    val sharedPrefs = remember { context.getSharedPreferences("pos_prefs", android.content.Context.MODE_PRIVATE) }
    val logoUri by viewModel.headerLogoUri.collectAsState()

    var showRestoreConfirmDialog by remember { mutableStateOf(false) }

    val backupLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.CreateDocument("*/*")
    ) { uri ->
        if (uri != null) {
            try {
                val db = com.example.data.AppDatabase.getDatabase(context)
                try {
                    db.openHelper.writableDatabase.execSQL("PRAGMA wal_checkpoint(FULL);")
                } catch (_: Exception) {}

                val dbFile = context.getDatabasePath("unpatch_pos_db")
                if (dbFile.exists()) {
                    context.contentResolver.openOutputStream(uri)?.use { output ->
                        dbFile.inputStream().use { input ->
                            input.copyTo(output)
                        }
                    }
                    Toast.makeText(context, "Database backup successful!", Toast.LENGTH_LONG).show()
                } else {
                    Toast.makeText(context, "Database file not found", Toast.LENGTH_SHORT).show()
                }
            } catch (e: Exception) {
                Toast.makeText(context, "Backup failed: ${e.message}", Toast.LENGTH_LONG).show()
            }
        }
    }

    val restoreLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.OpenDocument()
    ) { uri ->
        if (uri != null) {
            try {
                com.example.data.AppDatabase.closeDatabase()

                val dbFile = context.getDatabasePath("unpatch_pos_db")
                val walFile = File(dbFile.path + "-wal")
                val shmFile = File(dbFile.path + "-shm")
                if (walFile.exists()) walFile.delete()
                if (shmFile.exists()) shmFile.delete()

                context.contentResolver.openInputStream(uri)?.use { input ->
                    FileOutputStream(dbFile).use { output ->
                        input.copyTo(output)
                    }
                }

                // Inspect restored DB file to auto-recover user account phone into sharedPrefs
                try {
                    val sqliteDb = android.database.sqlite.SQLiteDatabase.openDatabase(
                        dbFile.path,
                        null,
                        android.database.sqlite.SQLiteDatabase.OPEN_READWRITE
                    )
                    val cursor = sqliteDb.rawQuery("SELECT phoneNo FROM user_accounts ORDER BY id DESC LIMIT 1", null)
                    if (cursor.moveToFirst()) {
                        val restoredPhone = cursor.getString(0)
                        if (!restoredPhone.isNullOrEmpty()) {
                            sharedPrefs.edit()
                                .putString("logged_in_phone", restoredPhone)
                                .putString("last_registered_phone", restoredPhone)
                                .apply()
                        }
                    }
                    cursor.close()
                    sqliteDb.close()
                } catch (_: Exception) {}

                Toast.makeText(context, "Database restore successful! Restarting app...", Toast.LENGTH_LONG).show()
                val intent = context.packageManager.getLaunchIntentForPackage(context.packageName)
                if (intent != null) {
                    intent.addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK or android.content.Intent.FLAG_ACTIVITY_CLEAR_TASK)
                    context.startActivity(intent)
                    if (context is android.app.Activity) {
                        context.finish()
                    }
                    Runtime.getRuntime().exit(0)
                }
            } catch (e: Exception) {
                Toast.makeText(context, "Restore failed: ${e.message}", Toast.LENGTH_LONG).show()
            }
        }
    }

    val importProductsLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.OpenDocument()
    ) { uri ->
        if (uri != null) {
            val count = com.example.util.BackupAndExcelUtils.importProductsFromCSV(context, uri, viewModel)
