                "add_receipt_printer" -> {
                    Column(
                        modifier = Modifier
                            .fillMaxSize()
                            .padding(16.dp),
                        verticalArrangement = Arrangement.spacedBy(16.dp)
                    ) {
                        val printerName by viewModel.selectedPrinterName.collectAsState()
                        val printerMac by viewModel.selectedPrinterMac.collectAsState()
                        val paperWidth by viewModel.selectedPaperWidth.collectAsState()

                        // Card for Printer Connection
                        Card(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clickable { currentSubScreen = "select_printer_device" },
                            colors = CardDefaults.cardColors(containerColor = AppSurfaceColor),
                            shape = RoundedCornerShape(12.dp)
                        ) {
                            Column(modifier = Modifier.padding(16.dp)) {
                                Text(
                                    text = "Printer",
                                    fontSize = 12.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = BrandPurple
                                )
                                Spacer(modifier = Modifier.height(4.dp))
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text(
                                        text = if (printerName.isNotEmpty()) "$printerName ($printerMac)" else "Connect Printer",
                                        fontSize = 16.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = AppTextColor
                                    )
                                    Icon(
                                        imageVector = Icons.Default.KeyboardArrowRight,
                                        contentDescription = "Select Printer",
                                        tint = Color.Gray
                                    )
                                }
                            }
                        }

                        // Card for Paper Width Dropdown
                        var showWidthDropdown by remember { mutableStateOf(false) }
                        Card(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clickable { showWidthDropdown = true },
                            colors = CardDefaults.cardColors(containerColor = AppSurfaceColor),
                            shape = RoundedCornerShape(12.dp)
                        ) {
                            Column(modifier = Modifier.padding(16.dp)) {
                                Text(
                                    text = "Paper Width",
                                    fontSize = 12.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = BrandPurple
                                )
                                Spacer(modifier = Modifier.height(4.dp))
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text(
                                        text = paperWidth,
                                        fontSize = 16.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = AppTextColor
                                    )
                                    Icon(
                                        imageVector = Icons.Default.ArrowDropDown,
                                        contentDescription = "Dropdown",
                                        tint = Color.Gray
                                    )
                                }

                                DropdownMenu(
                                    expanded = showWidthDropdown,
                                    onDismissRequest = { showWidthDropdown = false },
                                    modifier = Modifier.background(AppSurfaceColor)
                                ) {
                                    DropdownMenuItem(
                                        text = { Text("58mm", color = AppTextColor) },
                                        onClick = {
                                            viewModel.selectedPaperWidth.value = "58mm"
                                            showWidthDropdown = false
                                        }
                                    )
                                    DropdownMenuItem(
                                        text = { Text("80mm", color = AppTextColor) },
                                        onClick = {
                                            viewModel.selectedPaperWidth.value = "80mm"
                                            showWidthDropdown = false
                                        }
                                    )
                                }
                            }
                        }

                        Spacer(modifier = Modifier.height(24.dp))

                        // Test Printer Button
                        Button(
                            onClick = {
                                if (printerMac.isEmpty()) {
                                    android.widget.Toast.makeText(context, "Please connect a printer first!", android.widget.Toast.LENGTH_SHORT).show()
                                } else {
                                    android.widget.Toast.makeText(context, "Testing connection & printing test receipt to $printerName ($paperWidth)...", android.widget.Toast.LENGTH_SHORT).show()
                                }
                            },
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(52.dp),
                            colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                            shape = RoundedCornerShape(12.dp)
                        ) {
                            Text(
                                text = "Test Printer",
                                fontSize = 16.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color.White
                            )
                        }

                        // Save Printer Button
                        Button(
                            onClick = {
                                android.widget.Toast.makeText(context, "Printer saved successfully!", android.widget.Toast.LENGTH_SHORT).show()
                                currentSubScreen = "print_settings"
                            },
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(52.dp),
                            colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                            shape = RoundedCornerShape(12.dp)
                        ) {
                            Text(
                                text = "Save Printer",
                                fontSize = 16.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color.White
                            )
                        }
                    }
                }
                "add_kitchen_printer" -> {
                            Column(
                                modifier = Modifier
