                        "select_printer_device" -> {
                            var bluetoothPermissionGranted by remember {
                                mutableStateOf(
                                    if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.S) {
                                        ContextCompat.checkSelfPermission(context, android.Manifest.permission.BLUETOOTH_CONNECT) == PackageManager.PERMISSION_GRANTED
                                    } else {
                                        ContextCompat.checkSelfPermission(context, android.Manifest.permission.BLUETOOTH) == PackageManager.PERMISSION_GRANTED
                                    }
                                )
                            }

                            val bluetoothAdapter: BluetoothAdapter? = remember { BluetoothAdapter.getDefaultAdapter() }
                            var bluetoothEnabled by remember {
                                mutableStateOf(bluetoothAdapter?.isEnabled == true)
                            }

                            var pairedDevices by remember {
                                mutableStateOf<List<Pair<String, String>>>(emptyList())
                            }

                            // Function to reload paired devices list
                            fun loadDevices() {
                                if (bluetoothPermissionGranted && bluetoothEnabled) {
                                    pairedDevices = getBluetoothDevices(context)
                                }
                            }

                            // Launchers
                            val permissionLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
                                contract = androidx.activity.result.contract.ActivityResultContracts.RequestMultiplePermissions()
                            ) { results ->
                                val granted = if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.S) {
                                    results[android.Manifest.permission.BLUETOOTH_CONNECT] == true
                                } else {
                                    results[android.Manifest.permission.BLUETOOTH] == true
                                }
                                bluetoothPermissionGranted = granted
                                if (granted) {
                                    bluetoothEnabled = bluetoothAdapter?.isEnabled == true
                                    loadDevices()
                                }
                            }

                            val bluetoothLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
                                contract = androidx.activity.result.contract.ActivityResultContracts.StartActivityForResult()
                            ) { result ->
                                bluetoothEnabled = bluetoothAdapter?.isEnabled == true
                                loadDevices()
                            }

                            LaunchedEffect(bluetoothPermissionGranted, bluetoothEnabled) {
                                loadDevices()
                            }

                            // Trigger permission request or bluetooth enable automatically on screen entry
                            LaunchedEffect(Unit) {
                                if (!bluetoothPermissionGranted) {
                                    val permissions = if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.S) {
                                        arrayOf(
                                            android.Manifest.permission.BLUETOOTH_CONNECT,
                                            android.Manifest.permission.BLUETOOTH_SCAN
                                        )
                                    } else {
                                        arrayOf(
                                            android.Manifest.permission.BLUETOOTH,
                                            android.Manifest.permission.BLUETOOTH_ADMIN,
                                            android.Manifest.permission.ACCESS_FINE_LOCATION
                                        )
                                    }
                                    permissionLauncher.launch(permissions)
                                } else if (bluetoothAdapter != null && !bluetoothAdapter.isEnabled) {
                                    try {
                                        val intent = Intent(BluetoothAdapter.ACTION_REQUEST_ENABLE)
                                        bluetoothLauncher.launch(intent)
                                    } catch (e: Exception) {
                                        // fallback enable
                                    }
                                }
                            }

                            Column(
                                modifier = Modifier
                                    .fillMaxSize()
                                    .padding(16.dp),
                                verticalArrangement = Arrangement.spacedBy(12.dp)
                            ) {
                                if (!bluetoothPermissionGranted) {
                                    // Permission request UI card
                                    Card(
                                        modifier = Modifier.fillMaxWidth(),
                                        colors = CardDefaults.cardColors(containerColor = AppSurfaceColor),
                                        shape = RoundedCornerShape(16.dp),
                                        border = BorderStroke(1.dp, Color(0xFFE2E0E6))
                                    ) {
                                        Column(
                                            modifier = Modifier.padding(24.dp),
                                            horizontalAlignment = Alignment.CenterHorizontally,
                                            verticalArrangement = Arrangement.Center
                                        ) {
                                            Icon(
                                                imageVector = Icons.Default.BluetoothDisabled,
                                                contentDescription = "Bluetooth Permission",
                                                tint = BrandPurple,
                                                modifier = Modifier.size(64.dp)
                                            )
                                            Spacer(modifier = Modifier.height(16.dp))
                                            Text(
                                                text = "Bluetooth Permission Required",
                                                fontSize = 18.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = AppTextColor,
                                                textAlign = TextAlign.Center
                                            )
                                            Spacer(modifier = Modifier.height(8.dp))
                                            Text(
                                                text = "Please allow bluetooth permissions to scan and connect to nearby printers.",
                                                fontSize = 14.sp,
                                                color = AppSubTextColor,
                                                textAlign = TextAlign.Center
                                            )
                                            Spacer(modifier = Modifier.height(24.dp))
                                            Button(
                                                onClick = {
                                                    val permissions = if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.S) {
                                                        arrayOf(
                                                            android.Manifest.permission.BLUETOOTH_CONNECT,
                                                            android.Manifest.permission.BLUETOOTH_SCAN
                                                        )
                                                    } else {
                                                        arrayOf(
                                                            android.Manifest.permission.BLUETOOTH,
                                                            android.Manifest.permission.BLUETOOTH_ADMIN,
                                                            android.Manifest.permission.ACCESS_FINE_LOCATION
                                                        )
                                                    }
                                                    permissionLauncher.launch(permissions)
                                                },
                                                colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                                                shape = RoundedCornerShape(12.dp),
                                                modifier = Modifier.fillMaxWidth().height(48.dp)
                                            ) {
                                                Text("Grant Permission", color = Color.White, fontWeight = FontWeight.Bold)
                                            }
                                        }
                                    }
                                } else if (bluetoothAdapter == null) {
                                    // Bluetooth not supported
                                    Card(
                                        modifier = Modifier.fillMaxWidth(),
                                        colors = CardDefaults.cardColors(containerColor = AppSurfaceColor),
                                        shape = RoundedCornerShape(16.dp)
                                    ) {
                                        Column(
                                            modifier = Modifier.padding(24.dp),
                                            horizontalAlignment = Alignment.CenterHorizontally
                                        ) {
                                            Icon(
                                                imageVector = Icons.Default.Warning,
                                                contentDescription = "Not Supported",
                                                tint = Color.Red,
                                                modifier = Modifier.size(48.dp)
                                            )
                                            Spacer(modifier = Modifier.height(16.dp))
                                            Text(
                                                text = "Bluetooth Not Supported",
                                                fontSize = 16.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = AppTextColor
                                            )
                                        }
                                    }
                                } else if (!bluetoothEnabled) {
                                    // Bluetooth is turned off
                                    Card(
                                        modifier = Modifier.fillMaxWidth(),
                                        colors = CardDefaults.cardColors(containerColor = AppSurfaceColor),
                                        shape = RoundedCornerShape(16.dp),
                                        border = BorderStroke(1.dp, Color(0xFFE2E0E6))
                                    ) {
                                        Column(
                                            modifier = Modifier.padding(24.dp),
                                            horizontalAlignment = Alignment.CenterHorizontally,
                                            verticalArrangement = Arrangement.Center
                                        ) {
                                            Icon(
                                                imageVector = Icons.Default.Bluetooth,
                                                contentDescription = "Bluetooth Disabled",
                                                tint = BrandPurple,
                                                modifier = Modifier.size(64.dp)
                                            )
                                            Spacer(modifier = Modifier.height(16.dp))
                                            Text(
                                                text = "Bluetooth is Turned Off",
                                                fontSize = 18.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = AppTextColor,
                                                textAlign = TextAlign.Center
                                            )
                                            Spacer(modifier = Modifier.height(8.dp))
                                            Text(
                                                text = "Please turn on bluetooth to see the connected printers list and connect.",
                                                fontSize = 14.sp,
                                                color = AppSubTextColor,
                                                textAlign = TextAlign.Center
                                            )
                                            Spacer(modifier = Modifier.height(24.dp))
                                            Button(
                                                onClick = {
                                                    try {
                                                        val intent = Intent(BluetoothAdapter.ACTION_REQUEST_ENABLE)
                                                        bluetoothLauncher.launch(intent)
                                                    } catch (e: Exception) {
                                                        // fallback enable
                                                    }
                                                },
                                                colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                                                shape = RoundedCornerShape(12.dp),
                                                modifier = Modifier.fillMaxWidth().height(48.dp)
                                            ) {
                                                Text("Turn On Bluetooth", color = Color.White, fontWeight = FontWeight.Bold)
                                            }
                                        }
                                    }
                                } else {
                                    // Bluetooth is on and permissions are granted
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Text(
                                            text = "Connected Devices (${pairedDevices.size})",
                                            fontSize = 14.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = AppSubTextColor
                                        )
                                        IconButton(onClick = { loadDevices() }) {
                                            Icon(imageVector = Icons.Default.Refresh, contentDescription = "Refresh Devices List", tint = BrandPurple)
                                        }
                                    }

                                    if (pairedDevices.isEmpty()) {
                                        // Empty state for paired devices
                                        Card(
                                            modifier = Modifier.fillMaxWidth(),
                                            colors = CardDefaults.cardColors(containerColor = AppSurfaceColor),
                                            shape = RoundedCornerShape(16.dp),
                                            border = BorderStroke(1.dp, Color(0xFFE2E0E6))
                                        ) {
                                            Column(
                                                modifier = Modifier.padding(24.dp),
                                                horizontalAlignment = Alignment.CenterHorizontally
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Default.Search,
                                                    contentDescription = "No Paired Devices",
                                                    tint = Color.Gray,
                                                    modifier = Modifier.size(48.dp)
                                                )
                                                Spacer(modifier = Modifier.height(16.dp))
                                                Text(
                                                    text = "No Connected Devices Found",
                                                    fontSize = 16.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = AppTextColor,
                                                    textAlign = TextAlign.Center
                                                )
                                                Spacer(modifier = Modifier.height(8.dp))
                                                Text(
                                                    text = "Please pair your receipt printer in Android Bluetooth settings first, then click Refresh above.",
                                                    fontSize = 14.sp,
                                                    color = AppSubTextColor,
                                                    textAlign = TextAlign.Center
                                                )
                                            }
                                        }
                                    } else {
                                        // Scrollable devices list
                                        Column(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .verticalScroll(rememberScrollState()),
                                            verticalArrangement = Arrangement.spacedBy(10.dp)
                                        ) {
                                            pairedDevices.forEach { device ->
                                                Card(
                                                    modifier = Modifier
                                                        .fillMaxWidth()
                                                        .clickable {
                                                            viewModel.selectedPrinterName.value = device.first
                                                            viewModel.selectedPrinterMac.value = device.second
                                                            currentSubScreen = "add_receipt_printer"
                                                        },
                                                    colors = CardDefaults.cardColors(containerColor = AppSurfaceColor),
                                                    shape = RoundedCornerShape(12.dp),
                                                    border = BorderStroke(1.dp, Color(0xFFE2E0E6))
                                                ) {
                                                    Row(
                                                        modifier = Modifier
                                                            .fillMaxWidth()
                                                            .padding(horizontal = 16.dp, vertical = 14.dp),
                                                        verticalAlignment = Alignment.CenterVertically
                                                    ) {
                                                        Box(
                                                            modifier = Modifier
                                                                .size(40.dp)
                                                                .background(Color(0xFFF2EFFF), shape = CircleShape),
                                                            contentAlignment = Alignment.Center
                                                        ) {
                                                            Icon(
                                                                imageVector = Icons.Default.Print,
                                                                contentDescription = "Printer",
                                                                tint = BrandPurple,
                                                                modifier = Modifier.size(20.dp)
                                                            )
                                                        }
                                                        Spacer(modifier = Modifier.width(16.dp))
                                                        Column(modifier = Modifier.weight(1f)) {
                                                            Text(
                                                                text = device.first,
                                                                fontSize = 16.sp,
                                                                fontWeight = FontWeight.Bold,
                                                                color = AppTextColor
                                                            )
                                                            Spacer(modifier = Modifier.height(4.dp))
                                                            Text(
                                                                text = device.second,
                                                                fontSize = 13.sp,
                                                                color = AppSubTextColor
                                                            )
                                                        }
                                                        Icon(
                                                            imageVector = Icons.Default.KeyboardArrowRight,
                                                            contentDescription = "Select",
                                                            tint = Color.Gray
                                                        )
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                        "theme" -> {
