                        "header_design" -> {
                            val headers by viewModel.headerLines.collectAsState()

                            // 1. Blinking Transition for Empty State
                            val infiniteTransition = rememberInfiniteTransition(label = "blink")
                            val blinkAlpha by infiniteTransition.animateFloat(
                                initialValue = 1.0f,
                                targetValue = 0.2f,
                                animationSpec = infiniteRepeatable(
                                    animation = tween(durationMillis = 800, easing = LinearEasing),
                                    repeatMode = RepeatMode.Reverse
                                ),
                                label = "alpha"
                            )

                            // Add/Edit Text Dialog
                            if (isAddingHeader || editingHeaderIndexForText != null) {
                                val isEditing = editingHeaderIndexForText != null
                                var textState by remember(isAddingHeader, editingHeaderIndexForText) {
                                    mutableStateOf(if (isEditing) headers[editingHeaderIndexForText!!] else "")
                                }
                                AlertDialog(
                                    onDismissRequest = {
                                        isAddingHeader = false
                                        editingHeaderIndexForText = null
                                    },
                                    title = {
                                        Text(
                                            text = if (isEditing) "Edit Header Text" else "Add Header Text",
                                            fontWeight = FontWeight.Bold,
                                            color = AppTextColor
                                        )
                                    },
                                    text = {
                                        OutlinedTextField(
                                            value = textState,
                                            onValueChange = { textState = it },
                                            placeholder = { Text("Enter header text...") },
                                            singleLine = true,
                                            modifier = Modifier.fillMaxWidth(),
                                            colors = OutlinedTextFieldDefaults.colors(
                                                focusedBorderColor = BrandPurple,
                                                unfocusedBorderColor = Color.LightGray
                                            )
                                        )
                                    },
                                    confirmButton = {
                                        Button(
                                            onClick = {
                                                val newList = headers.toMutableList()
                                                if (isEditing) {
                                                    if (textState.isNotBlank()) {
                                                        newList[editingHeaderIndexForText!!] = textState
                                                    }
                                                    editingHeaderIndexForText = null
                                                } else {
                                                    if (textState.isNotBlank()) {
                                                        val isFirst = newList.isEmpty()
                                                        val i = newList.size
                                                        sharedPrefs.edit()
                                                            .putString("header_font_family_$i", "Default")
                                                            .putFloat("header_font_size_$i", if (isFirst) 63f else 40f)
                                                            .putBoolean("header_is_bold_$i", true)
                                                            .putString("header_alignment_$i", "Center")
                                                            .putFloat("header_top_spacing_$i", 0f)
                                                            .apply()
                                                        newList.add(textState)
                                                        selectedHeaderIndex = i // select the newly added line immediately for styling
                                                    }
                                                    isAddingHeader = false
                                                }
                                                viewModel.headerLines.value = newList
                                                stylingUpdateCounter++
                                            },
                                            colors = ButtonDefaults.buttonColors(containerColor = BrandPurple)
                                        ) {
                                            Text("Save", color = Color.White)
                                        }
                                    },
                                    dismissButton = {
                                        TextButton(
                                            onClick = {
                                                isAddingHeader = false
                                                editingHeaderIndexForText = null
                                            }
                                        ) {
                                            Text("Cancel", color = Color.Gray)
                                        }
                                    }
                                )
                            }

                            if (showLogoSheet) {
                                val galleryLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
                                    contract = androidx.activity.result.contract.ActivityResultContracts.GetContent()
                                ) { uri: android.net.Uri? ->
                                    if (uri != null) {
                                        try {
                                            context.contentResolver.takePersistableUriPermission(
                                                uri,
                                                android.content.Intent.FLAG_GRANT_READ_URI_PERMISSION
                                            )
                                        } catch (e: Exception) {
                                            // Ignore
                                        }
                                        viewModel.headerLogoUri.value = uri.toString()
                                    }
                                    showLogoSheet = false
                                }

                                AlertDialog(
                                    onDismissRequest = { showLogoSheet = false },
                                    title = { Text("Select Header Logo", fontWeight = FontWeight.Bold, color = AppTextColor) },
                                    text = {
                                        Column(
                                            verticalArrangement = Arrangement.spacedBy(12.dp),
                                            modifier = Modifier.fillMaxWidth()
                                        ) {
                                            Text("Select a predefined style or pick an image from your gallery:", fontSize = 14.sp, color = AppSubTextColor)
                                            
                                            // Option 1: Gallery
                                            Card(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .clickable {
                                                        galleryLauncher.launch("image/*")
                                                    },
                                                colors = CardDefaults.cardColors(containerColor = Color(0xFFEFEAFA)),
                                                shape = RoundedCornerShape(12.dp)
                                            ) {
                                                Row(
                                                    modifier = Modifier
                                                        .fillMaxWidth()
                                                        .padding(16.dp),
                                                    horizontalArrangement = Arrangement.spacedBy(12.dp),
                                                    verticalAlignment = Alignment.CenterVertically
                                                ) {
                                                    Icon(imageVector = Icons.Default.PhotoLibrary, contentDescription = "Gallery", tint = BrandPurple)
                                                    Text("Choose from Gallery", fontWeight = FontWeight.Bold, color = BrandPurple)
                                                }
                                            }

                                            Text("Presets:", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = Color.Gray)

                                            // Option 2: Presets
                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                                            ) {
                                                listOf(
                                                    Triple("logo_store", Icons.Default.ShoppingCart, "Store"),
                                                    Triple("logo_food", Icons.Default.Star, "Food"),
                                                    Triple("logo_coffee", Icons.Default.Favorite, "Coffee")
                                                ).forEach { (key, icon, label) ->
                                                    Card(
                                                        modifier = Modifier
                                                            .weight(1f)
                                                            .clickable {
                                                                viewModel.headerLogoUri.value = key
                                                                showLogoSheet = false
                                                            },
                                                        colors = CardDefaults.cardColors(containerColor = if (logoUri == key) Color(0xFFFFF0F5) else Color(0xFFF2F0F7)),
                                                        shape = RoundedCornerShape(8.dp),
                                                        border = BorderStroke(1.dp, if (logoUri == key) BrandPurple else Color.Transparent)
                                                    ) {
                                                        Column(
                                                            modifier = Modifier
                                                                .fillMaxWidth()
                                                                .padding(8.dp),
                                                            horizontalAlignment = Alignment.CenterHorizontally,
                                                            verticalArrangement = Arrangement.spacedBy(4.dp)
                                                        ) {
                                                            Icon(imageVector = icon, contentDescription = label, tint = BrandPurple, modifier = Modifier.size(24.dp))
                                                            Text(label, fontSize = 11.sp, fontWeight = FontWeight.Bold, color = AppTextColor)
                                                        }
                                                    }
                                                }
                                            }

                                            if (logoUri.isNotEmpty()) {
                                                Spacer(modifier = Modifier.height(4.dp))
                                                TextButton(
                                                    onClick = {
                                                        viewModel.headerLogoUri.value = ""
                                                        showLogoSheet = false
                                                    },
                                                    modifier = Modifier.align(Alignment.CenterHorizontally)
                                                ) {
                                                    Text("Remove Logo", color = Color.Red, fontWeight = FontWeight.Bold)
                                                }
                                            }
                                        }
                                    },
                                    confirmButton = {},
                                    dismissButton = {
                                        TextButton(onClick = { showLogoSheet = false }) {
                                            Text("Cancel", color = BrandPurple)
                                        }
                                    }
                                )
                            }

                            Box(modifier = Modifier.fillMaxSize()) {
                                if (selectedHeaderIndex != null) {
                                // 1. STYLING/PREVIEW SCREEN (First Image)
                                Column(
                                    modifier = Modifier
                                        .fillMaxSize()
                                        .background(LightBg)
                                ) {
                                    // Top 40% Pink Live Receipt Preview Paper
                                    Box(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .weight(0.4f)
                                            .background(Color(0xFFFFF0F5)) // light pink receipt background
                                            .padding(16.dp),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Box(
                                            modifier = Modifier
                                                .fillMaxSize()
                                                .border(
                                                    width = 1.dp,
                                                    color = Color(0xFFECD1E2),
                                                    shape = RoundedCornerShape(8.dp)
                                                )
                                                .background(Color.White)
                                                .padding(16.dp),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Column(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .verticalScroll(rememberScrollState()),
                                                horizontalAlignment = Alignment.CenterHorizontally,
                                                verticalArrangement = Arrangement.Center
                                            ) {
                                                // Business Logo placeholder or selected image
                                                if (logoUri.isNotEmpty()) {
                                                    Box(
                                                        modifier = Modifier
                                                            .padding(bottom = 8.dp)
                                                            .size(logoSizeValState.dp)
                                                            .background(Color.Transparent)
                                                            .clickable {
                                                                showLogoSizeSheet = true
                                                            },
                                                        contentAlignment = Alignment.Center
                                                    ) {
                                                        if (logoUri.startsWith("content://") || logoUri.startsWith("file://") || logoUri.startsWith("http")) {
                                                            Image(
                                                                painter = rememberAsyncImagePainter(model = logoUri),
                                                                contentDescription = "Logo Image Preview",
                                                                modifier = Modifier.fillMaxSize()
                                                            )
                                                        } else {
                                                            val logoIcon = when (logoUri) {
                                                                "logo_store" -> Icons.Default.ShoppingCart
                                                                "logo_food" -> Icons.Default.Star
                                                                "logo_coffee" -> Icons.Default.Favorite
                                                                else -> Icons.Default.ShoppingCart
                                                            }
                                                            Icon(
                                                                imageVector = logoIcon,
                                                                contentDescription = "Logo Icon Preview",
                                                                tint = BrandPurple,
                                                                modifier = Modifier
                                                                    .fillMaxSize()
                                                                    .padding(8.dp)
                                                            )
                                                        }
                                                    }
                                                }

                                                // Header lines preview list
                                                if (headers.isEmpty()) {
                                                    Text(
                                                        text = "No Header Found",
                                                        fontSize = 16.sp,
                                                        fontWeight = FontWeight.Medium,
                                                        color = Color.LightGray,
                                                        modifier = Modifier.alpha(blinkAlpha)
                                                    )
                                                } else {
                                                    headers.forEachIndexed { index, header ->
                                                        val isSelected = selectedHeaderIndex == index
                                                        
                                                        // Load styles
                                                        val fontFamily = if (isSelected) lineFontFamily else (sharedPrefs.getString("header_font_family_$index", "Default") ?: "Default")
                                                        val fontSize = if (isSelected) lineFontSize else sharedPrefs.getFloat("header_font_size_$index", if (index == 0) 40f else 20f)
                                                        val isBold = if (isSelected) lineIsBold else sharedPrefs.getBoolean("header_is_bold_$index", index == 0)
                                                        val alignment = if (isSelected) lineAlignment else (sharedPrefs.getString("header_alignment_$index", "Center") ?: "Center")
                                                        val topSpacing = if (isSelected) lineTopSpacing else sharedPrefs.getFloat("header_top_spacing_$index", 0f)
                                                        
                                                        val styleConfig = POSFontStyles.getStyle(fontFamily)

                                                        Column(
                                                            modifier = Modifier
                                                                .fillMaxWidth()
                                                                .background(
                                                                    color = if (isSelected) Color(0xFFF0E6FF) else Color.Transparent,
                                                                    shape = RoundedCornerShape(8.dp)
                                                                )
                                                                .clickable {
                                                                    selectedHeaderIndex = index
                                                                }
                                                                .padding(vertical = 4.dp, horizontal = 12.dp),
                                                            horizontalAlignment = when (alignment) {
                                                                "Left" -> Alignment.Start
                                                                "Right" -> Alignment.End
                                                                else -> Alignment.CenterHorizontally
                                                            }
                                                        ) {
                                                            Spacer(modifier = Modifier.height(topSpacing.dp))
                                                            Text(
                                                                text = header,
                                                                fontSize = fontSize.sp,
                                                                fontWeight = if (isBold) FontWeight.Bold else styleConfig.fontWeight,
                                                                fontStyle = styleConfig.fontStyle,
                                                                fontFamily = styleConfig.fontFamily,
                                                                letterSpacing = styleConfig.letterSpacing,
                                                                color = Color.Black,
                                                                textAlign = when (alignment) {
                                                                    "Left" -> TextAlign.Left
                                                                    "Right" -> TextAlign.Right
                                                                    else -> TextAlign.Center
                                                                }
                                                            )
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }

                                    // Bottom 60% Area: Scrollable Styling Settings Card List
                                    Box(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .weight(0.6f)
                                            .clip(RoundedCornerShape(topStart = 24.dp, topEnd = 24.dp))
                                            .background(Color(0xFFF9F7FC)) // clean lavender background
                                            .padding(20.dp)
                                    ) {
                                        Column(
                                            modifier = Modifier
                                                .fillMaxSize()
                                                .verticalScroll(rememberScrollState()),
                                            verticalArrangement = Arrangement.spacedBy(12.dp)
                                        ) {
                                            // CARD 1: Font Selection
                                            Card(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .clickable { currentSubScreen = "font_list" },
                                                colors = CardDefaults.cardColors(containerColor = Color.White),
                                                elevation = CardDefaults.cardElevation(defaultElevation = 1.dp),
                                                shape = RoundedCornerShape(12.dp)
                                            ) {
                                                Row(
                                                    modifier = Modifier
                                                        .fillMaxWidth()
                                                        .padding(16.dp),
                                                    horizontalArrangement = Arrangement.SpaceBetween,
                                                    verticalAlignment = Alignment.CenterVertically
                                                ) {
                                                    Column {
                                                        Text("Font", fontSize = 12.sp, color = Color.Gray)
                                                        Spacer(modifier = Modifier.height(4.dp))
                                                        Text(
                                                            text = lineFontFamily,
                                                            fontSize = 18.sp,
                                                            fontWeight = FontWeight.Bold,
                                                            color = BrandPurple
                                                        )
                                                    }
                                                    if (lineFontFamily != "Default") {
                                                        IconButton(onClick = {
                                                            lineFontFamily = "Default"
                                                            saveLineStyles()
                                                        }) {
                                                            Icon(
                                                                imageVector = Icons.Default.Clear,
                                                                contentDescription = "Reset Font",
                                                                tint = Color.Gray
                                                            )
                                                        }
                                                    }
                                                }
                                            }

                                            // CARD 2: Font Size Slider
                                            Card(
                                                modifier = Modifier.fillMaxWidth(),
                                                colors = CardDefaults.cardColors(containerColor = Color.White),
                                                elevation = CardDefaults.cardElevation(defaultElevation = 1.dp),
                                                shape = RoundedCornerShape(12.dp)
                                            ) {
                                                Column(
                                                    modifier = Modifier
                                                        .fillMaxWidth()
                                                        .padding(16.dp)
                                                ) {
                                                    Text("Font Size (${lineFontSize.toInt()})", fontSize = 13.sp, color = Color.Gray, fontWeight = FontWeight.Medium)
                                                    Spacer(modifier = Modifier.height(8.dp))
                                                    Slider(
                                                        value = lineFontSize,
                                                        onValueChange = {
                                                            lineFontSize = it
                                                            saveLineStyles()
                                                        },
                                                        valueRange = 12f..100f,
                                                        colors = SliderDefaults.colors(
                                                            thumbColor = BrandPurple,
                                                            activeTrackColor = BrandPurple,
                                                            inactiveTrackColor = Color(0xFFEFEAFA)
                                                        )
                                                    )
                                                }
                                            }

                                            // CARD 3: Bold Control Checkbox
                                            Card(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .clickable {
                                                        lineIsBold = !lineIsBold
                                                        saveLineStyles()
                                                    },
                                                colors = CardDefaults.cardColors(containerColor = Color.White),
                                                elevation = CardDefaults.cardElevation(defaultElevation = 1.dp),
                                                shape = RoundedCornerShape(12.dp)
                                            ) {
                                                Row(
                                                    modifier = Modifier
                                                        .fillMaxWidth()
                                                        .padding(16.dp),
                                                    horizontalArrangement = Arrangement.SpaceBetween,
                                                    verticalAlignment = Alignment.CenterVertically
                                                ) {
                                                    Text("Bold", fontSize = 16.sp, fontWeight = FontWeight.Bold, color = Color.Black)
                                                    Checkbox(
                                                        checked = lineIsBold,
                                                        onCheckedChange = {
                                                            lineIsBold = it
                                                            saveLineStyles()
                                                        },
                                                        colors = CheckboxDefaults.colors(
                                                            checkedColor = BrandPurple,
                                                            checkmarkColor = Color.White
                                                        )
                                                    )
                                                }
                                            }

                                            // CARD 4: Alignment segment buttons
                                            Card(
                                                modifier = Modifier.fillMaxWidth(),
                                                colors = CardDefaults.cardColors(containerColor = Color.White),
                                                elevation = CardDefaults.cardElevation(defaultElevation = 1.dp),
                                                shape = RoundedCornerShape(12.dp)
                                            ) {
                                                Column(
                                                    modifier = Modifier
                                                        .fillMaxWidth()
                                                        .padding(16.dp)
                                                ) {
                                                    Text("Align", fontSize = 13.sp, color = Color.Gray, fontWeight = FontWeight.Medium)
                                                    Spacer(modifier = Modifier.height(12.dp))
                                                    Row(
                                                        modifier = Modifier.fillMaxWidth(),
                                                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                                                    ) {
                                                        listOf("Left", "Center", "Right").forEach { align ->
