                                                        IconButton(onClick = {
                                                            footerFontFamily = "Default"
                                                            saveFooterLineStyles()
                                                        }) {
                                                            Icon(
                                                                imageVector = Icons.Default.Clear,
                                                                contentDescription = "Reset Font",
                                                                tint = Color.Gray
                                                            )
                                                        }
                                                    }
                                                }
                                            }

                                            // CARD 2: Font Size Slider
                                            Card(
                                                modifier = Modifier.fillMaxWidth(),
                                                colors = CardDefaults.cardColors(containerColor = Color.White),
                                                elevation = CardDefaults.cardElevation(defaultElevation = 1.dp),
                                                shape = RoundedCornerShape(12.dp)
                                            ) {
                                                Column(
                                                    modifier = Modifier
                                                        .fillMaxWidth()
                                                        .padding(16.dp)
                                                ) {
                                                    Text("Font Size (${footerFontSize.toInt()})", fontSize = 13.sp, color = Color.Gray, fontWeight = FontWeight.Medium)
                                                    Spacer(modifier = Modifier.height(8.dp))
                                                    Slider(
                                                        value = footerFontSize,
                                                        onValueChange = {
                                                            footerFontSize = it
                                                            saveFooterLineStyles()
                                                        },
                                                        valueRange = 12f..100f,
                                                        colors = SliderDefaults.colors(
                                                            thumbColor = BrandPurple,
                                                            activeTrackColor = BrandPurple,
                                                            inactiveTrackColor = Color(0xFFEFEAFA)
                                                        )
                                                    )
                                                }
                                            }

                                            // CARD 3: Bold Control Checkbox
                                            Card(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .clickable {
                                                        footerIsBold = !footerIsBold
                                                        saveFooterLineStyles()
                                                    },
                                                colors = CardDefaults.cardColors(containerColor = Color.White),
                                                elevation = CardDefaults.cardElevation(defaultElevation = 1.dp),
                                                shape = RoundedCornerShape(12.dp)
                                            ) {
                                                Row(
                                                    modifier = Modifier
                                                        .fillMaxWidth()
                                                        .padding(16.dp),
                                                    horizontalArrangement = Arrangement.SpaceBetween,
                                                    verticalAlignment = Alignment.CenterVertically
                                                ) {
                                                    Text("Bold", fontSize = 16.sp, fontWeight = FontWeight.Bold, color = Color.Black)
                                                    Checkbox(
                                                        checked = footerIsBold,
                                                        onCheckedChange = {
                                                            footerIsBold = it
                                                            saveFooterLineStyles()
                                                        },
                                                        colors = CheckboxDefaults.colors(
                                                            checkedColor = BrandPurple,
                                                            checkmarkColor = Color.White
                                                        )
                                                    )
                                                }
                                            }

                                            // CARD 4: Alignment segment buttons
                                            Card(
                                                modifier = Modifier.fillMaxWidth(),
                                                colors = CardDefaults.cardColors(containerColor = Color.White),
                                                elevation = CardDefaults.cardElevation(defaultElevation = 1.dp),
                                                shape = RoundedCornerShape(12.dp)
                                            ) {
                                                Column(
                                                    modifier = Modifier
                                                        .fillMaxWidth()
                                                        .padding(16.dp)
                                                ) {
                                                    Text("Align", fontSize = 13.sp, color = Color.Gray, fontWeight = FontWeight.Medium)
                                                    Spacer(modifier = Modifier.height(12.dp))
                                                    Row(
                                                        modifier = Modifier.fillMaxWidth(),
                                                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                                                    ) {
                                                        listOf("Left", "Center", "Right").forEach { align ->
                                                            val isAlignSelected = footerAlignment == align
                                                            Box(
                                                                modifier = Modifier
                                                                    .weight(1f)
                                                                    .height(44.dp)
                                                                    .background(
                                                                        color = if (isAlignSelected) Color(0xFFF0E6FF) else Color(0xFFF9F7FC),
                                                                        shape = RoundedCornerShape(24.dp)
                                                                    )
                                                                    .border(
                                                                        width = 1.dp,
                                                                        color = if (isAlignSelected) BrandPurple else Color(0xFFE2D6FF),
                                                                        shape = RoundedCornerShape(24.dp)
                                                                    )
                                                                    .clickable {
                                                                        footerAlignment = align
                                                                        saveFooterLineStyles()
                                                                    },
                                                                contentAlignment = Alignment.Center
                                                            ) {
                                                                Text(
                                                                    text = align,
                                                                    color = BrandPurple,
                                                                    fontWeight = if (isAlignSelected) FontWeight.Bold else FontWeight.Normal,
                                                                    fontSize = 14.sp
                                                                )
                                                            }
                                                        }
                                                    }
                                                }
                                            }

                                            // CARD 5: Top Spacing Adjustment Slider
                                            Card(
                                                modifier = Modifier.fillMaxWidth(),
                                                colors = CardDefaults.cardColors(containerColor = Color.White),
                                                elevation = CardDefaults.cardElevation(defaultElevation = 1.dp),
                                                shape = RoundedCornerShape(12.dp)
                                            ) {
                                                Column(
                                                    modifier = Modifier
                                                        .fillMaxWidth()
                                                        .padding(16.dp)
                                                ) {
                                                    Text("Top Spacing (${footerTopSpacing.toInt()})", fontSize = 13.sp, color = Color.Gray, fontWeight = FontWeight.Medium)
                                                    Spacer(modifier = Modifier.height(8.dp))
                                                    Slider(
                                                        value = footerTopSpacing,
                                                        onValueChange = {
                                                            footerTopSpacing = it
                                                            saveFooterLineStyles()
                                                        },
                                                        valueRange = 0f..100f,
                                                        colors = SliderDefaults.colors(
                                                            thumbColor = BrandPurple,
                                                            activeTrackColor = BrandPurple,
                                                            inactiveTrackColor = Color(0xFFEFEAFA)
                                                        )
                                                    )
                                                }
                                            }
                                        }
                                    }
                                }
                            } else {
                                // 2. ROW LIST VIEW (Second Image / List Screen)
                                Column(
                                    modifier = Modifier
                                        .fillMaxSize()
                                        .padding(16.dp),
                                    verticalArrangement = Arrangement.spacedBy(16.dp)
                                ) {
                                    // Soft pink live receipt preview paper (top portion of list screen)
                                    Card(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .height(160.dp),
                                        colors = CardDefaults.cardColors(containerColor = Color(0xFFFFF0F5)),
                                        shape = RoundedCornerShape(12.dp),
                                        border = BorderStroke(1.dp, Color(0xFFECD1E2)),
                                        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
                                    ) {
