                        "font_list" -> {
                            val headers by viewModel.headerLines.collectAsState()
                            val footers by viewModel.footerLines.collectAsState()
                            val previewText = if (fontListSource == "footer") {
                                if (selectedFooterIndex != null && footers.size > selectedFooterIndex!!) footers[selectedFooterIndex!!] else ""
                            } else {
                                if (selectedHeaderIndex != null && headers.size > selectedHeaderIndex!!) headers[selectedHeaderIndex!!] else ""
                            }
                            val fontFamilyVal by viewModel.headerFontFamily.collectAsState()

                            LazyColumn(
                                modifier = Modifier
                                    .fillMaxSize()
                                    .background(LightBg)
                                    .padding(16.dp),
                                verticalArrangement = Arrangement.spacedBy(10.dp)
                            ) {
                                items(50) { index ->
                                    val fontNum = index + 1
                                    val fontKey = if (fontNum == 1) "Default" else "Font$fontNum"
                                    val styleConfig = POSFontStyles.list[index]
                                    val isSelected = if (fontListSource == "footer") {
                                        if (selectedFooterIndex != null) footerFontFamily == fontKey else false
                                    } else {
                                        (if (selectedHeaderIndex != null) lineFontFamily else fontFamilyVal) == fontKey
                                    }

                                    Card(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .clickable {
                                                if (fontListSource == "footer") {
                                                    if (selectedFooterIndex != null) {
                                                        footerFontFamily = fontKey
                                                        sharedPrefs.edit().putString("footer_font_family_$selectedFooterIndex", fontKey).apply()
                                                        stylingUpdateCounter++
                                                    }
                                                    currentSubScreen = "footer_design"
                                                } else {
                                                    if (selectedHeaderIndex != null) {
                                                        lineFontFamily = fontKey
                                                        sharedPrefs.edit().putString("header_font_family_$selectedHeaderIndex", fontKey).apply()
                                                        stylingUpdateCounter++
                                                    } else {
                                                        viewModel.headerFontFamily.value = fontKey
                                                    }
                                                    currentSubScreen = "header_design"
                                                }
                                            },
                                        colors = CardDefaults.cardColors(containerColor = Color.White),
                                        shape = RoundedCornerShape(12.dp),
                                        border = BorderStroke(
                                            width = if (isSelected) 2.dp else 1.dp,
                                            color = if (isSelected) BrandPurple else Color(0xFFE2E0E6)
                                        ),
                                        elevation = CardDefaults.cardElevation(defaultElevation = if (isSelected) 4.dp else 1.dp)
                                    ) {
                                        Row(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .padding(16.dp),
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.spacedBy(16.dp)
                                        ) {
                                            // Number badge with light purple background and BrandPurple text
                                            Box(
                                                modifier = Modifier
                                                    .size(36.dp)
                                                    .background(
                                                        color = if (isSelected) BrandPurple else Color(0xFFEFEAFA),
                                                        shape = CircleShape
                                                    ),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                Text(
                                                    text = fontNum.toString(),
                                                    color = if (isSelected) Color.White else BrandPurple,
                                                    fontWeight = FontWeight.Bold,
                                                    fontSize = 14.sp
                                                )
                                            }

                                            // Styled Preview Text
                                            Text(
                                                text = previewText,
                                                color = Color.Black,
                                                fontSize = 24.sp,
                                                fontWeight = styleConfig.fontWeight,
                                                fontStyle = styleConfig.fontStyle,
                                                fontFamily = styleConfig.fontFamily,
                                                letterSpacing = styleConfig.letterSpacing,
                                                modifier = Modifier.weight(1f)
                                            )
                                        }
                                    }
                                }
                            }
                        }
