                                    ) {
                                        Column(
                                            modifier = Modifier.fillMaxSize(),
                                            horizontalAlignment = Alignment.CenterHorizontally,
                                            verticalArrangement = Arrangement.Bottom
                                        ) {
                                            if (footers.isNotEmpty()) {
                                                Text(
                                                    footers.first(),
                                                    color = Color.Black,
                                                    fontWeight = FontWeight.Bold,
                                                    fontSize = 16.sp,
                                                    modifier = Modifier.padding(bottom = 8.dp)
                                                )
                                            }
                                            Text(
                                                "--- End of Receipt ---",
                                                color = Color.Gray,
                                                fontSize = 11.sp,
                                                modifier = Modifier.padding(bottom = 8.dp)
                                            )
                                            Box(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .height(4.dp)
                                                    .background(Color.Red, shape = RoundedCornerShape(2.dp))
                                            )
                                            Spacer(modifier = Modifier.height(bottomFeed.dp))
                                        }
                                    }
                                }

                                Box(
                                    modifier = Modifier
                                        .fillMaxWidth() .weight(0.6f)
                                         .clip(RoundedCornerShape(topStart = 24.dp, topEnd = 24.dp))
                                         .background(AppSurfaceColor)
                                         .padding(24.dp)
                                 ) {
                                     Column(
                                         modifier = Modifier.fillMaxSize(),
                                         verticalArrangement = Arrangement.spacedBy(16.dp)
                                     ) {
                                         Text("Bottom Feed Space", fontWeight = FontWeight.Bold, color = AppTextColor, fontSize = 18.sp)
                                         Text("Adjust the extra paper feeding amount at the end of each receipt printout to ensure clean cutting.", color = AppSubTextColor, fontSize = 13.sp)

                                         Spacer(modifier = Modifier.height(12.dp))

                                         Row(
                                             modifier = Modifier.fillMaxWidth(),
                                             horizontalArrangement = Arrangement.SpaceBetween
                                         ) {
                                             Text("Feed Amount", color = AppSubTextColor)
                                             Text("${bottomFeed.toInt()} dp", color = BrandPurple, fontWeight = FontWeight.Bold)
                                         }

                                         Slider(
                                             value = bottomFeed,
                                             onValueChange = { viewModel.bottomFeed.value = it },
                                             valueRange = 10f..150f,
                                             colors = SliderDefaults.colors(
                                                thumbColor = BrandPurple,
                                                activeTrackColor = BrandPurple
                                            )
                                        )

                                        Spacer(modifier = Modifier.weight(1f))

                                        Button(
                                            onClick = { currentSubScreen = "print_settings" },
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .height(52.dp),
                                            colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                                            shape = RoundedCornerShape(12.dp)
                                        ) {
                                            Text("Save Feed", color = Color.White, fontWeight = FontWeight.Bold)
                                        }
                                    }
                                }
                            }
                        }
                        "print_receipt" -> {
                            SettingsPrintReceiptScreen(
                                viewModel = viewModel,
                                onBack = { currentSubScreen = "print_settings" }
                            )
                        }
                        "line_spacing" -> {
                            SettingsLineSpacingScreen(
                                viewModel = viewModel,
                                onBack = { currentSubScreen = "print_settings" }
                            )
                        }
                        "print_brightness" -> {
                            val brightness by viewModel.printBrightness.collectAsState()
                            Column(
                                modifier = Modifier
                                    .fillMaxSize()
                                    .background(LightBg)
                            ) {
                                Box(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .weight(0.4f)
                                        .background(Color(0xFFFDEAF4))
                                        .padding(24.dp),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .width(220.dp)
                                            .fillMaxHeight()
                                            .background(Color.White, shape = RoundedCornerShape(8.dp))
                                            .border(1.dp, Color(0xFFECD1E2), shape = RoundedCornerShape(8.dp))
                                            .padding(16.dp),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Column(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalAlignment = Alignment.CenterHorizontally,
                                            verticalArrangement = Arrangement.Center
                                        ) {
                                            val simulatedAlpha = (brightness / 100f).coerceIn(0.3f, 1.0f)
                                            Text(
                                                "PRINT PREVIEW",
                                                color = Color.Black.copy(alpha = simulatedAlpha),
                                                fontWeight = FontWeight.ExtraBold,
                                                fontSize = 20.sp
                                            )
                                            Spacer(modifier = Modifier.height(10.dp))
                                            Text(
                                                "Testing Print density levels\nThis text simulates printing brightness.",
                                                color = Color.Black.copy(alpha = simulatedAlpha),
                                                fontSize = 11.sp,
                                                textAlign = TextAlign.Center
                                            )
                                        }
                                    }
                                }

                                Box(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .weight(0.6f)
                                        .clip(RoundedCornerShape(topStart = 24.dp, topEnd = 24.dp))
                                        .background(AppSurfaceColor)
                                        .padding(24.dp)
                                ) {
                                    Column(
                                        modifier = Modifier.fillMaxSize(),
                                        verticalArrangement = Arrangement.spacedBy(16.dp)
                                    ) {
                                        Text("Print Brightness / Density", fontWeight = FontWeight.Bold, color = AppTextColor, fontSize = 18.sp)
                                        Text("Increase or decrease printhead ink density levels for deeper black prints on various thermal paper types.", color = AppSubTextColor, fontSize = 13.sp)

                                        Spacer(modifier = Modifier.height(12.dp))

                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween
                                        ) {
                                            Text("Density Level", color = AppSubTextColor)
                                            Text("${brightness.toInt()}%", color = BrandPurple, fontWeight = FontWeight.Bold)
                                        }

                                        Slider(
                                            value = brightness,
                                            onValueChange = { viewModel.printBrightness.value = it },
                                            valueRange = 50f..150f,
                                            colors = SliderDefaults.colors(
                                                thumbColor = BrandPurple,
                                                activeTrackColor = BrandPurple
                                            )
                                        )

                                        Spacer(modifier = Modifier.weight(1f))

                                        Button(
                                            onClick = { currentSubScreen = "print_settings" },
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .height(52.dp),
                                            colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                                            shape = RoundedCornerShape(12.dp)
                                        ) {
                                            Text("Save Density", color = Color.White, fontWeight = FontWeight.Bold)
                                        }
                                    }
                                }
                            }
                        }
                    }
            }
        }

        if (showRestoreConfirmDialog) {
            AlertDialog(
                onDismissRequest = { showRestoreConfirmDialog = false },
                title = { Text("Database Restore", fontWeight = FontWeight.Bold, color = AppTextColor) },
                text = { Text("Database restore ပြုလုပ်ပါက လက်ရှိ data များကို အစားထိုးသွားမည်ဖြစ်ပါသည်။ ဆက်လက်လုပ်ဆောင်ပါမလား?", color = AppTextColor) },
                confirmButton = {
                    Button(
                        onClick = {
                            showRestoreConfirmDialog = false
                            restoreLauncher.launch(arrayOf("*/*"))
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = BrandPurple)
                    ) {
                        Text("Restore", color = Color.White)
                    }
                },
                dismissButton = {
                    TextButton(onClick = { showRestoreConfirmDialog = false }) {
                        Text("မလုပ်ဆောင်ပါ", color = Color.Gray)
                    }
                },
                containerColor = AppSurfaceColor,
                shape = RoundedCornerShape(16.dp)
            )
        }
    }

