// 14. CUSTOMERS LIST SCREEN
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun CustomersListScreen(navController: NavController, viewModel: POSViewModel) {
    val customers by viewModel.allCustomers.collectAsState()
    var searchQuery by remember { mutableStateOf("") }
    var isSearching by remember { mutableStateOf(false) }
    var showSortDialog by remember { mutableStateOf(false) }
    var selectedSort by remember { mutableStateOf("A-Z") } // "A-Z", "Z-A", "0-9", "9-0"

    // Sort customer list based on selection
    val filteredCustomers = customers.filter {
        it.name.contains(searchQuery, ignoreCase = true) || it.phone.contains(searchQuery)
    }.sortedWith { c1, c2 ->
        when (selectedSort) {
            "A-Z" -> c1.name.compareTo(c2.name)
            "Z-A" -> c2.name.compareTo(c1.name)
            "0-9" -> c1.id.compareTo(c2.id) // oldest first
            "9-0" -> c2.id.compareTo(c1.id) // newest first
            else -> c1.name.compareTo(c2.name)
        }
    }

    Scaffold(
        topBar = {
            if (isSearching) {
                TopAppBar(
                    title = {
                        OutlinedTextField(
                            value = searchQuery,
                            onValueChange = { searchQuery = it },
                            placeholder = { Text("ဈေးဝယ်သူ ရှာရန်...", color = Color.LightGray) },
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(vertical = 4.dp),
                            singleLine = true,
                            colors = OutlinedTextFieldDefaults.colors(
                                focusedTextColor = AppTextColor,
                                unfocusedTextColor = AppTextColor,
                                focusedContainerColor = Color.Transparent,
                                unfocusedContainerColor = Color.Transparent,
                                disabledContainerColor = Color.Transparent,
                                focusedBorderColor = Color.Transparent,
                                unfocusedBorderColor = Color.Transparent,
                            ),
                            trailingIcon = {
                                if (searchQuery.isNotEmpty()) {
                                    IconButton(onClick = { searchQuery = "" }) {
                                        Icon(imageVector = Icons.Filled.Close, contentDescription = "Clear", tint = Color.Gray)
                                    }
                                }
                            }
                        )
                    },
                    navigationIcon = {
                        IconButton(onClick = { 
                            isSearching = false
                            searchQuery = ""
                        }) {
                            Icon(imageVector = Icons.Filled.Close, contentDescription = "Close Search", tint = AppTextColor)
                        }
                    },
                    colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.White)
                )
            } else {
                TopAppBar(
                    title = { Text("ဈေးဝယ်သူများ", fontWeight = FontWeight.Bold, color = AppTextColor) },
                    navigationIcon = {
                        IconButton(onClick = { navController.popBackStack() }) {
                            Icon(imageVector = Icons.Filled.ArrowBack, contentDescription = "Back", tint = AppTextColor)
                        }
                    },
                    actions = {
                        Text(
                            text = "${customers.size} item${if (customers.size != 1) "s" else ""}",
                            color = Color.Gray,
                            fontSize = 14.sp,
                            modifier = Modifier.padding(end = 8.dp)
                        )
                        IconButton(onClick = { isSearching = true }) {
                            Icon(imageVector = Icons.Filled.Search, contentDescription = "Search", tint = Color.Gray)
                        }
                        IconButton(onClick = {
                            viewModel.editingCustomer.value = null
                            navController.navigate("add_customer")
                        }) {
                            Icon(imageVector = Icons.Filled.Add, contentDescription = "Add Customer", tint = BrandPurple)
                        }
                        IconButton(onClick = { showSortDialog = true }) {
                            Icon(imageVector = Icons.Filled.Sort, contentDescription = "Sort", tint = Color.Gray)
                        }
                    },
                    colors = TopAppBarDefaults.topAppBarColors(
                        containerColor = Color.White,
                        navigationIconContentColor = AppTextColor,
                        titleContentColor = AppTextColor
                    )
                )
            }
        }
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .background(Color.White)
                .padding(innerPadding)
        ) {
            if (filteredCustomers.isEmpty()) {
                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                        Icon(
                            imageVector = Icons.Filled.People,
                            contentDescription = "No Customers",
                            modifier = Modifier.size(72.dp),
                            tint = Color.LightGray
                        )
                        Spacer(modifier = Modifier.height(16.dp))
                        Text("ဈေးဝယ်သူ ရှာမတွေ့ပါ", color = Color.Gray, fontWeight = FontWeight.Bold)
                    }
                }
            } else {
                LazyColumn(modifier = Modifier.fillMaxWidth()) {
                    items(filteredCustomers) { customer ->
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clickable {
                                    viewModel.editingCustomer.value = customer
                                    navController.navigate("add_customer")
                                }
                        ) {
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(horizontal = 16.dp, vertical = 12.dp),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.SpaceBetween
                            ) {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    val firstLetter = if (customer.name.isNotEmpty()) customer.name.take(1).lowercase() else "c"
                                    Box(
                                        modifier = Modifier
                                            .size(40.dp)
                                            .background(Color(0xFFECE9F6), shape = CircleShape),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Text(
                                            text = firstLetter,
                                            fontWeight = FontWeight.Bold,
                                            fontSize = 18.sp,
                                            color = BrandPurple
                                        )
                                    }
                                    Spacer(modifier = Modifier.width(16.dp))
                                    Column {
                                        Text(customer.name, fontWeight = FontWeight.Bold, fontSize = 16.sp, color = AppTextColor)
                                        val subtitleText = if (customer.phone.isNotEmpty()) customer.phone else if (customer.address.isNotEmpty()) customer.address else ""
                                        if (subtitleText.isNotEmpty()) {
                                            Text(subtitleText, color = Color.Gray, fontSize = 13.sp)
                                        }
                                    }
                                }
                                Icon(imageVector = Icons.Filled.KeyboardArrowRight, contentDescription = "Edit", tint = Color.Gray)
                            }
                            HorizontalDivider(
                                color = Color(0xFFF1F0F5),
                                thickness = 1.dp,
                                modifier = Modifier.padding(horizontal = 16.dp)
                            )
                        }
                    }
                }
            }
        }
    }

    // Sort Dialog matching the video (A-Z, Z-A, 0-9, 9-0)
    if (showSortDialog) {
        var tempSelectedSort by remember { mutableStateOf(selectedSort) }
        AlertDialog(
            onDismissRequest = { showSortDialog = false },
            title = { Text("Sort By", fontWeight = FontWeight.Bold) },
            text = {
                Column {
                    listOf(
                        "A-Z" to "A-Z အမည်",
                        "Z-A" to "Z-A အမည်",
                        "0-9" to "0-9 အချိန်",
                        "9-0" to "9-0 အချိန်"
                    ).forEach { (code, label) ->
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clickable { tempSelectedSort = code }
                                .padding(vertical = 12.dp, horizontal = 8.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            RadioButton(
                                selected = tempSelectedSort == code,
                                onClick = { tempSelectedSort = code },
                                colors = RadioButtonDefaults.colors(selectedColor = BrandPurple)
                            )
                            Spacer(modifier = Modifier.width(8.dp))
                            Text(label, fontSize = 15.sp)
                        }
                    }
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        selectedSort = tempSelectedSort
                        showSortDialog = false
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = BrandPurple)
                ) {
                    Text("Ok")
                }
            },
            dismissButton = {
                TextButton(onClick = { showSortDialog = false }) {
                    Text("Cancel", color = BrandPurple)
                }
            }
        )
    }
}

// 15. ADD / EDIT CUSTOMER SCREEN
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AddCustomerScreen(navController: NavController, viewModel: POSViewModel) {
    val editingCustomer by viewModel.editingCustomer.collectAsState()
    val context = LocalContext.current

    var name by remember { mutableStateOf("") }
    var phone by remember { mutableStateOf("") }
    var address by remember { mutableStateOf("") }
    var note by remember { mutableStateOf("") }

    var showDeleteConfirm by remember { mutableStateOf(false) }

    LaunchedEffect(editingCustomer) {
        editingCustomer?.let {
            name = it.name
            phone = it.phone
            address = it.address
            note = it.note
        }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text(if (editingCustomer == null) "ဈေးဝယ်သူအသစ်" else "ပြင်ရန်", fontWeight = FontWeight.Bold) },
                navigationIcon = {
                    IconButton(onClick = { navController.popBackStack() }) {
                        Icon(imageVector = Icons.Filled.ArrowBack, contentDescription = "Back")
                    }
                },
                actions = {
                    if (editingCustomer != null) {
                        IconButton(onClick = { showDeleteConfirm = true }) {
                            Icon(imageVector = Icons.Filled.Delete, contentDescription = "Delete", tint = Color.Red)
                        }
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.White)
            )
        }
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .background(LightBg)
                .padding(innerPadding)
                .verticalScroll(rememberScrollState())
                .padding(16.dp)
        ) {
            Column(modifier = Modifier.fillMaxWidth().padding(bottom = 24.dp)) {
                // Name field
                CustomProductField(label = "အမည်*") {
                    OutlinedTextField(
                        value = name,
                        onValueChange = { name = it },
                        modifier = Modifier.fillMaxWidth().testTag("cust_name"),
                        singleLine = true,
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedTextColor = Color(0xFF1C1B1F),
                            unfocusedTextColor = Color(0xFF1C1B1F),
                            focusedContainerColor = Color.White,
                            unfocusedContainerColor = Color.White,
                            focusedBorderColor = BrandPurple,
                            unfocusedBorderColor = Color(0xFFE0E0E0)
                        ),
                        shape = RoundedCornerShape(12.dp)
                    )
                }
                Spacer(modifier = Modifier.height(16.dp))

                // Address field
                CustomProductField(label = "လိပ်စာ") {
                    OutlinedTextField(
                        value = address,
                        onValueChange = { address = it },
                        modifier = Modifier.fillMaxWidth().testTag("cust_address"),
                        singleLine = true,
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedTextColor = Color(0xFF1C1B1F),
                            unfocusedTextColor = Color(0xFF1C1B1F),
                            focusedContainerColor = Color.White,
                            unfocusedContainerColor = Color.White,
                            focusedBorderColor = BrandPurple,
                            unfocusedBorderColor = Color(0xFFE0E0E0)
                        ),
                        shape = RoundedCornerShape(12.dp)
                    )
                }
                Spacer(modifier = Modifier.height(16.dp))

                // Phone field
                CustomProductField(label = "ဖုန်းနံပါတ်") {
                    OutlinedTextField(
                        value = phone,
                        onValueChange = { phone = it },
                        modifier = Modifier.fillMaxWidth().testTag("cust_phone"),
                        singleLine = true,
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Phone),
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedTextColor = Color(0xFF1C1B1F),
                            unfocusedTextColor = Color(0xFF1C1B1F),
                            focusedContainerColor = Color.White,
                            unfocusedContainerColor = Color.White,
                            focusedBorderColor = BrandPurple,
                            unfocusedBorderColor = Color(0xFFE0E0E0)
                        ),
                        shape = RoundedCornerShape(12.dp)
                    )
                }
                Spacer(modifier = Modifier.height(16.dp))

                // Note/Remark field
                CustomProductField(label = "မှတ်ချက်") {
                    OutlinedTextField(
                        value = note,
                        onValueChange = { note = it },
                        modifier = Modifier.fillMaxWidth().testTag("cust_note"),
                        singleLine = true,
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedTextColor = Color(0xFF1C1B1F),
                            unfocusedTextColor = Color(0xFF1C1B1F),
                            focusedContainerColor = Color.White,
                            unfocusedContainerColor = Color.White,
                            focusedBorderColor = BrandPurple,
                            unfocusedBorderColor = Color(0xFFE0E0E0)
                        ),
                        shape = RoundedCornerShape(12.dp)
                    )
                }
            }

            Spacer(modifier = Modifier.height(24.dp))

            // Save / Update Button
            Button(
                onClick = {
                    if (name.isNotEmpty()) {
                        val cust = editingCustomer
                        if (cust == null) {
                            viewModel.addCustomer(name, phone, address, note) {
                                android.widget.Toast.makeText(context, "သိမ်းပြီးပါပြီ။", android.widget.Toast.LENGTH_SHORT).show()
                                navController.popBackStack()
                            }
                        } else {
                            viewModel.updateCustomer(cust.copy(name = name, phone = phone, address = address, note = note)) {
                                android.widget.Toast.makeText(context, "ပြင်ပြီးပါပြီ။", android.widget.Toast.LENGTH_SHORT).show()
                                navController.popBackStack()
                            }
                        }
                    } else {
                        android.widget.Toast.makeText(context, "အမည်ဖြည့်စွက်ပါ", android.widget.Toast.LENGTH_SHORT).show()
                    }
                },
                modifier = Modifier
                    .fillMaxWidth()
                    .height(54.dp)
                    .testTag("save_cust_button"),
                shape = RoundedCornerShape(12.dp),
                colors = ButtonDefaults.buttonColors(containerColor = BrandPurple)
            ) {
                Text(
                    text = if (editingCustomer == null) "SAVE" else "ပြင်မည်",
                    fontWeight = FontWeight.Bold,
                    fontSize = 16.sp,
                    color = Color.White
                )
            }
        }
    }

    // Delete Confirmation Dialog matching the video exactly
    if (showDeleteConfirm) {
        AlertDialog(
            onDismissRequest = { showDeleteConfirm = false },
            title = { Text("ဖျက်ရန်", fontWeight = FontWeight.Bold) },
            text = { Text("$name ဖျက်ရန်အတည်ပြုပါ။", fontSize = 15.sp) },
            confirmButton = {
                Button(
                    onClick = {
                        editingCustomer?.let {
                            viewModel.deleteCustomer(it) {
                                showDeleteConfirm = false
                                android.widget.Toast.makeText(context, "ဖျက်ပြီးပါပြီ။", android.widget.Toast.LENGTH_SHORT).show()
                                navController.popBackStack()
                            }
                        }
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color.Red)
                ) {
                    Text("Delete")
                }
            },
            dismissButton = {
                TextButton(onClick = { showDeleteConfirm = false }) {
                    Text("Cancel", color = BrandPurple)
                }
            }
        )
    }
}

// 16. SUPPLIERS LIST SCREEN
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun SuppliersListScreen(navController: NavController, viewModel: POSViewModel) {
    val suppliers by viewModel.allSuppliers.collectAsState()
    var searchQuery by remember { mutableStateOf("") }
    var showSortDialog by remember { mutableStateOf(false) }
    var selectedSort by remember { mutableStateOf("A-Z") } // "A-Z", "Z-A", "0-9", "9-0"

    var isSearching by remember { mutableStateOf(false) }

    // Sort supplier list based on selection
    val filteredSuppliers = suppliers.filter {
        it.name.contains(searchQuery, ignoreCase = true) || it.phone.contains(searchQuery)
    }.sortedWith { s1, s2 ->
        when (selectedSort) {
            "A-Z" -> s1.name.compareTo(s2.name)
            "Z-A" -> s2.name.compareTo(s1.name)
            "0-9" -> s1.id.compareTo(s2.id) // oldest first
            "9-0" -> s2.id.compareTo(s1.id) // newest first
            else -> s1.name.compareTo(s2.name)
        }
    }

    Scaffold(
        topBar = {
            if (isSearching) {
                TopAppBar(
                    title = {
                        OutlinedTextField(
                            value = searchQuery,
                            onValueChange = { searchQuery = it },
                            placeholder = { Text("ကုန်သွင်းသူ ရှာရန်...", color = Color.LightGray) },
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(vertical = 4.dp),
                            singleLine = true,
                            colors = OutlinedTextFieldDefaults.colors(
                                focusedContainerColor = Color.Transparent,
                                unfocusedContainerColor = Color.Transparent,
                                disabledContainerColor = Color.Transparent,
                                focusedBorderColor = Color.Transparent,
                                unfocusedBorderColor = Color.Transparent,
                            ),
                            trailingIcon = {
                                if (searchQuery.isNotEmpty()) {
                                    IconButton(onClick = { searchQuery = "" }) {
                                        Icon(imageVector = Icons.Filled.Close, contentDescription = "Clear", tint = Color.Gray)
                                    }
                                }
                            }
                        )
                    },
                    navigationIcon = {
                        IconButton(onClick = { 
                            isSearching = false
                            searchQuery = ""
                        }) {
                            Icon(imageVector = Icons.Filled.ArrowBack, contentDescription = "Close Search", tint = AppTextColor)
                        }
                    },
                    colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.White)
                )
            } else {
                TopAppBar(
                    title = { Text("ကုန်သွင်းသူများ", fontWeight = FontWeight.Bold, color = AppTextColor) },
                    navigationIcon = {
                        IconButton(onClick = { navController.popBackStack() }) {
                            Icon(imageVector = Icons.Filled.ArrowBack, contentDescription = "Back", tint = AppTextColor)
                        }
                    },
                    actions = {
                        Text(
                            text = "${suppliers.size} item${if (suppliers.size != 1) "s" else ""}",
                            color = Color.Gray,
                            fontSize = 14.sp,
                            modifier = Modifier.padding(end = 8.dp)
                        )
                        IconButton(onClick = { isSearching = true }) {
                            Icon(imageVector = Icons.Filled.Search, contentDescription = "Search", tint = Color.Gray)
                        }
                        IconButton(onClick = {
                            viewModel.editingSupplier.value = null
                            navController.navigate("add_supplier")
                        }) {
                            Icon(imageVector = Icons.Filled.Add, contentDescription = "Add Supplier", tint = BrandPurple)
                        }
                        IconButton(onClick = { showSortDialog = true }) {
                            Icon(imageVector = Icons.Filled.Sort, contentDescription = "Sort", tint = Color.Gray)
                        }
                    },
                    colors = TopAppBarDefaults.topAppBarColors(
                        containerColor = Color.White,
                        navigationIconContentColor = AppTextColor,
                        titleContentColor = AppTextColor
                    )
                )
            }
        }
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .background(Color.White)
                .padding(innerPadding)
        ) {
            if (filteredSuppliers.isEmpty()) {
                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                        Icon(
                            imageVector = Icons.Filled.Groups,
                            contentDescription = "No Suppliers",
                            modifier = Modifier.size(72.dp),
                            tint = Color.LightGray
                        )
                        Spacer(modifier = Modifier.height(16.dp))
                        Text("ကုန်သွင်းသူ ရှာမတွေ့ပါ", color = Color.Gray, fontWeight = FontWeight.Bold)
                    }
                }
            } else {
                LazyColumn(modifier = Modifier.fillMaxWidth()) {
                    items(filteredSuppliers) { supplier ->
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clickable {
                                    viewModel.editingSupplier.value = supplier
                                    navController.navigate("add_supplier")
                                }
                        ) {
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(horizontal = 16.dp, vertical = 12.dp),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.SpaceBetween
                            ) {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    val firstLetter = if (supplier.name.isNotEmpty()) supplier.name.take(1).lowercase() else "s"
                                    Box(
                                        modifier = Modifier
                                            .size(40.dp)
                                            .background(Color(0xFFECE9F6), shape = CircleShape),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Text(
                                            text = firstLetter,
                                            fontWeight = FontWeight.Bold,
                                            fontSize = 18.sp,
                                            color = BrandPurple
                                        )
                                    }
                                    Spacer(modifier = Modifier.width(16.dp))
                                    Column {
                                        Text(supplier.name, fontWeight = FontWeight.Bold, fontSize = 16.sp, color = AppTextColor)
                                        val subtitleText = if (supplier.phone.isNotEmpty()) supplier.phone else if (supplier.address.isNotEmpty()) supplier.address else ""
                                        if (subtitleText.isNotEmpty()) {
                                            Text(subtitleText, color = Color.Gray, fontSize = 13.sp)
                                        }
                                    }
                                }
                                Icon(imageVector = Icons.Filled.KeyboardArrowRight, contentDescription = "Edit", tint = Color.Gray)
                            }
                            HorizontalDivider(
                                color = Color(0xFFF1F0F5),
                                thickness = 1.dp,
                                modifier = Modifier.padding(horizontal = 16.dp)
                            )
                        }
                    }
                }
            }
        }
    }

    // Sort Dialog
    if (showSortDialog) {
        var tempSelectedSort by remember { mutableStateOf(selectedSort) }
        AlertDialog(
            onDismissRequest = { showSortDialog = false },
            title = { Text("Sort By", fontWeight = FontWeight.Bold) },
            text = {
                Column {
                    listOf(
                        "A-Z" to "A-Z အမည်",
                        "Z-A" to "Z-A အမည်",
                        "0-9" to "0-9 အချိန်",
                        "9-0" to "9-0 အချိန်"
                    ).forEach { (code, label) ->
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clickable { tempSelectedSort = code }
                                .padding(vertical = 12.dp, horizontal = 8.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            RadioButton(
                                selected = tempSelectedSort == code,
                                onClick = { tempSelectedSort = code },
                                colors = RadioButtonDefaults.colors(selectedColor = BrandPurple)
                            )
                            Spacer(modifier = Modifier.width(8.dp))
                            Text(label, fontSize = 15.sp)
                        }
                    }
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        selectedSort = tempSelectedSort
                        showSortDialog = false
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = BrandPurple)
                ) {
                    Text("Ok")
                }
            },
            dismissButton = {
                TextButton(onClick = { showSortDialog = false }) {
                    Text("Cancel", color = BrandPurple)
                }
            }
        )
    }
}

