            )
        }
    ) { innerPadding ->
        if (voucher == null) {
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(innerPadding),
                contentAlignment = Alignment.Center
            ) {
                CircularProgressIndicator(color = BrandPurple)
            }
        } else {
            val numberFormat = remember { NumberFormat.getNumberInstance(Locale.US) }
            val formattedDate = remember(voucher.timestamp) {
                val sdf = SimpleDateFormat("dd/MM/yyyy hh:mma", Locale.getDefault())
                sdf.format(Date(voucher.timestamp))
            }

            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .background(Color.White)
                    .padding(innerPadding)
                    .padding(24.dp)
                    .verticalScroll(rememberScrollState()),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                Spacer(modifier = Modifier.height(16.dp))
                
                Text(
                    text = "စုစုပေါင်း",
                    fontSize = 15.sp,
                    color = Color.Gray,
                    fontWeight = FontWeight.Medium
                )
                
                Spacer(modifier = Modifier.height(8.dp))
                
                Text(
                    text = "${numberFormat.format(voucher.totalAmount.toInt())} $selectedCurrency",
                    fontSize = 36.sp,
                    fontWeight = FontWeight.Bold,
                    color = Color.Black
                )
                
                Spacer(modifier = Modifier.height(24.dp))
                
                HorizontalDivider(color = Color(0xFFE5E5E5), thickness = 1.dp)
                
                Spacer(modifier = Modifier.height(16.dp))
                
                // Metadata details: ရက်စွဲ, ဈေးဝယ်သူ, ငွေပေးချေမှု
                Column(
                    modifier = Modifier.fillMaxWidth(),
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    Row(modifier = Modifier.fillMaxWidth()) {
                        Text(
                            text = "ရက်စွဲ: ",
