                    }
                    
                    Row(modifier = Modifier.fillMaxWidth()) {
                        Text(
                            text = if (voucher.isPurchase) "ကုန်သွင်းသူများ: " else "ဈေးဝယ်သူ: ",
                            fontSize = 15.sp,
                            color = Color(0xFF5F6368),
                            fontWeight = FontWeight.Medium
                        )
                        Text(
                            text = voucher.customerName,
                            fontSize = 15.sp,
                            color = Color.Black,
                            fontWeight = FontWeight.Medium
                        )
                    }
                    
                    Row(modifier = Modifier.fillMaxWidth()) {
                        Text(
                            text = "ငွေပေးချေမှု: ",
                            fontSize = 15.sp,
                            color = Color(0xFF5F6368),
                            fontWeight = FontWeight.Medium
                        )
                        Text(
                            text = voucher.paymentMethod,
                            fontSize = 15.sp,
                            color = Color.Black,
                            fontWeight = FontWeight.Medium
                        )
                    }
                }
                
                Spacer(modifier = Modifier.height(16.dp))
                
                HorizontalDivider(color = Color(0xFFE5E5E5), thickness = 1.dp)
                
                Spacer(modifier = Modifier.height(16.dp))
                
                // Sold Items
                Column(
                    modifier = Modifier.fillMaxWidth(),
                    verticalArrangement = Arrangement.spacedBy(14.dp)
                ) {
                    items.forEach { item ->
                        val isHighlighted = item.productName.equals(highlightProduct, ignoreCase = true)
                        val rowModifier = if (isHighlighted) {
                            Modifier
                                .fillMaxWidth()
                                .background(Color(0xFFECE9F5), shape = RoundedCornerShape(8.dp))
                                .padding(8.dp)
                        } else {
                            Modifier.fillMaxWidth()
                        }
                        Row(
                            modifier = rowModifier,
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Column(modifier = Modifier.weight(1f)) {
                                Text(
                                    text = item.productName,
                                    fontSize = 15.sp,
                                    fontWeight = FontWeight.Medium,
                                    color = Color.Black
                                )
                                Spacer(modifier = Modifier.height(2.dp))
                                Text(
                                    text = "${numberFormat.format(item.sellingPrice.toInt())} $selectedCurrency x${item.quantity}",
                                    fontSize = 13.sp,
                                    color = Color.Gray
                                )
                            }
                            Text(
                                text = "${numberFormat.format((item.sellingPrice * item.quantity).toInt())} $selectedCurrency",
                                fontSize = 15.sp,
                                fontWeight = FontWeight.Medium,
                                color = Color.Black
                            )
