                    }
                }
                
                Spacer(modifier = Modifier.height(16.dp))
                
                HorizontalDivider(color = Color(0xFFE5E5E5), thickness = 1.dp)
                
                Spacer(modifier = Modifier.height(16.dp))
                
                // Total
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = "စုစုပေါင်းကျသင့်ငွေ",
                        fontSize = 15.sp,
                        fontWeight = FontWeight.Bold,
                        color = Color.Black
                    )
                    Text(
                        text = "${numberFormat.format(voucher.totalAmount.toInt())} $selectedCurrency",
                        fontSize = 15.sp,
                        fontWeight = FontWeight.Bold,
                        color = Color.Black
                    )
                }
                
                Spacer(modifier = Modifier.height(16.dp))
                
                HorizontalDivider(color = Color(0xFFE5E5E5), thickness = 1.dp)
                
                Spacer(modifier = Modifier.height(16.dp))
                
                // Footer
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = "Cashier: ${voucher.cashierName}",
                        fontSize = 13.sp,
                        color = Color.Gray
                    )
                    Text(
                        text = "#${voucher.receiptNo}",
                        fontSize = 13.sp,
                        color = Color.Gray
                    )
                }
            }
        }
    }

    if (showDeleteDialog) {
        AlertDialog(
            onDismissRequest = { showDeleteDialog = false },
            title = {
                Text(
                    text = "ဘောက်ချာဖျက်ရန် အတည်ပြုပါ",
                    fontWeight = FontWeight.Bold,
                    fontSize = 18.sp,
                    color = Color.Black
                )
            },
            text = {
                Text(
                    text = "ဘောက်ချာအမှတ် #$receiptNo ကို ဖျက်ရန် သေချာပါသလား?",
                    fontSize = 14.sp,
                    color = Color.DarkGray
                )
            },
            confirmButton = {
                Button(
                    onClick = {
                        viewModel.deleteVoucher(receiptNo)
                        showDeleteDialog = false
