                                    Icon(
                                        imageVector = if (isExpanded) Icons.Filled.KeyboardArrowUp else Icons.Filled.KeyboardArrowDown,
                                        contentDescription = "Show More",
                                        tint = BrandPurple,
                                        modifier = Modifier.size(18.dp)
                                    )
                                }

                                if (isExpanded && voucher.balanceAmount > 0) {
                                    Button(
                                        onClick = {
