@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun MyDateRangePickerDialog(
    onDismissRequest: () -> Unit,
    onDateRangeSelected: (Long?, Long?) -> Unit
) {
    val state = rememberDateRangePickerState()
    androidx.compose.ui.window.Dialog(
        onDismissRequest = onDismissRequest,
        properties = androidx.compose.ui.window.DialogProperties(usePlatformDefaultWidth = false)
    ) {
        Surface(
            modifier = Modifier.fillMaxSize(),
            color = Color.White
        ) {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .systemBarsPadding()
            ) {
                // Top Custom Header Row with X and Save
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 12.dp, vertical = 8.dp),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    IconButton(onClick = onDismissRequest) {
                        Icon(
                            imageVector = Icons.Filled.Close,
                            contentDescription = "Close",
                            tint = Color.DarkGray
                        )
                    }
                    
                    val hasSelection = state.selectedStartDateMillis != null && state.selectedEndDateMillis != null
                    TextButton(
                        onClick = {
                            if (hasSelection) {
                                onDateRangeSelected(state.selectedStartDateMillis, state.selectedEndDateMillis)
                                onDismissRequest()
                            }
                        },
                        enabled = hasSelection
                    ) {
                        Text(
                            text = "Save",
                            color = if (hasSelection) BrandPurple else Color.LightGray,
                            fontWeight = FontWeight.Bold,
                            fontSize = 16.sp
                        )
                    }
                }
                
                DateRangePicker(
                    state = state,
                    modifier = Modifier.weight(1f),
                    title = {
                        Text(
                            text = "Select range",
                            fontSize = 18.sp,
                            color = Color.DarkGray,
                            modifier = Modifier.padding(start = 24.dp, top = 8.dp, bottom = 4.dp)
                        )
                    },
                    colors = DatePickerDefaults.colors(
                        containerColor = Color.White,
                        selectedDayContainerColor = BrandPurple,
                        selectedDayContentColor = Color.White,
                        dayInSelectionRangeContainerColor = Color(0xFFECE9F5),
                        dayInSelectionRangeContentColor = BrandPurple,
                        todayContentColor = BrandPurple,
                        todayDateBorderColor = BrandPurple
                    )
                )
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun SalesProductTotalScreen(
    navController: NavController,
    viewModel: POSViewModel,
    isQuantityMode: Boolean
) {
    val vouchers by viewModel.allVouchers.collectAsState()
    val voucherItems by viewModel.allVoucherItems.collectAsState()
    val expenses by viewModel.allExpenses.collectAsState()
    val selectedCurrency by viewModel.selectedCurrency.collectAsState()
    val numberFormat = remember { NumberFormat.getNumberInstance(Locale.US) }

    // Default: current month (1st day of month to last day of month)
    val calendar = remember { Calendar.getInstance() }
    val firstDayOfMonthMillis = remember {
        val cal = Calendar.getInstance()
        cal.set(Calendar.DAY_OF_MONTH, 1)
        cal.set(Calendar.HOUR_OF_DAY, 0)
        cal.set(Calendar.MINUTE, 0)
        cal.set(Calendar.SECOND, 0)
        cal.set(Calendar.MILLISECOND, 0)
        cal.timeInMillis
    }
    val lastDayOfMonthMillis = remember {
        val cal = Calendar.getInstance()
        cal.set(Calendar.DAY_OF_MONTH, cal.getActualMaximum(Calendar.DAY_OF_MONTH))
        cal.set(Calendar.HOUR_OF_DAY, 23)
        cal.set(Calendar.MINUTE, 59)
        cal.set(Calendar.SECOND, 59)
        cal.set(Calendar.MILLISECOND, 999)
        cal.timeInMillis
    }

    var startDate by remember { mutableStateOf(firstDayOfMonthMillis) }
    var endDate by remember { mutableStateOf(lastDayOfMonthMillis) }
    var showDatePicker by remember { mutableStateOf(false) }

    val dateFormatter = remember { SimpleDateFormat("dd/MM/yyyy", Locale.US) }

    // Filter and aggregate data
    val completedSalesVouchers = remember(vouchers, startDate, endDate) {
        vouchers.filter { voucher ->
            !voucher.isPurchase && voucher.isCompleted && voucher.timestamp in startDate..endDate
        }
    }

    val completedVoucherIds = remember(completedSalesVouchers) {
        completedSalesVouchers.map { it.receiptNo }.toSet()
    }

    val filteredItems = remember(voucherItems, completedVoucherIds) {
        voucherItems.filter { it.voucherId in completedVoucherIds }
    }

    val filteredExpenses = remember(expenses, startDate, endDate) {
        expenses.filter { it.timestamp in startDate..endDate }
    }

    // Key Summary Metrics
    val totalSales = remember(completedSalesVouchers) {
        completedSalesVouchers.sumOf { it.totalAmount }
    }

    val totalDiscount = remember(completedSalesVouchers, filteredItems) {
        completedSalesVouchers.sumOf { v ->
            val itemsForV = filteredItems.filter { it.voucherId == v.receiptNo }
            val itemsTotal = itemsForV.sumOf { it.quantity * it.sellingPrice }
            (itemsTotal - v.totalAmount).coerceAtLeast(0.0)
        }
    }

    val totalExpenses = remember(filteredExpenses) {
        filteredExpenses.sumOf { it.amount }
    }

    val totalGrossProfit = remember(filteredItems) {
        filteredItems.sumOf { (it.sellingPrice - it.purchasePrice) * it.quantity }
    }

    val totalNetProfit = remember(totalGrossProfit, totalDiscount, totalExpenses) {
        totalGrossProfit - totalDiscount - totalExpenses
    }

    val productSalesList = remember(filteredItems, isQuantityMode) {
        filteredItems.groupBy { it.productName }
            .map { (productName, items) ->
                val totalQty = items.sumOf { it.quantity }
                val totalAmount = items.sumOf { it.quantity * it.sellingPrice }
                val firstItem = items.first()
                ProductSalesData(
                    productId = firstItem.productId,
                    productName = productName,
                    quantity = totalQty,
                    totalAmount = totalAmount,
                    sellingPrice = firstItem.sellingPrice
                )
            }
            .sortedByDescending { if (isQuantityMode) it.quantity.toDouble() else it.totalAmount }
    }

    // Generate daily chart data points
    val chartPoints = remember(completedSalesVouchers, filteredItems, filteredExpenses, startDate, endDate) {
        val points = mutableListOf<SalesChartPoint>()
        val cal = Calendar.getInstance().apply {
            timeInMillis = startDate
            set(Calendar.HOUR_OF_DAY, 0)
            set(Calendar.MINUTE, 0)
            set(Calendar.SECOND, 0)
            set(Calendar.MILLISECOND, 0)
        }
        val endCal = Calendar.getInstance().apply {
            timeInMillis = endDate
            set(Calendar.HOUR_OF_DAY, 23)
            set(Calendar.MINUTE, 59)
            set(Calendar.SECOND, 59)
            set(Calendar.MILLISECOND, 999)
        }

        val dayFormatter = SimpleDateFormat("dd/MM", Locale.US)

        while (!cal.after(endCal)) {
            val pStart = cal.timeInMillis
            val pEnd = Calendar.getInstance().apply {
                timeInMillis = pStart
                set(Calendar.HOUR_OF_DAY, 23)
                set(Calendar.MINUTE, 59)
                set(Calendar.SECOND, 59)
                set(Calendar.MILLISECOND, 999)
            }.timeInMillis

            val pVouchers = completedSalesVouchers.filter { it.timestamp in pStart..pEnd }
            val pVIds = pVouchers.map { it.receiptNo }.toSet()
            val pItems = filteredItems.filter { it.voucherId in pVIds }
            val pExpenses = filteredExpenses.filter { it.timestamp in pStart..pEnd }

            val pSales = pVouchers.sumOf { it.totalAmount }
            val pDiscount = pVouchers.sumOf { v ->
                val itemsForV = pItems.filter { it.voucherId == v.receiptNo }
                val itemsTotal = itemsForV.sumOf { it.quantity * it.sellingPrice }
                (itemsTotal - v.totalAmount).coerceAtLeast(0.0)
            }
            val pExp = pExpenses.sumOf { it.amount }
            val pGrossProfit = pItems.sumOf { (it.sellingPrice - it.purchasePrice) * it.quantity }
            val pNetProfit = (pGrossProfit - pDiscount - pExp).coerceAtLeast(0.0)

            val label = dayFormatter.format(cal.time)
            points.add(
                SalesChartPoint(
                    dateLabel = label,
                    sales = pSales,
                    discount = pDiscount,
                    expenses = pExp,
                    profit = pNetProfit
                )
            )

            cal.add(Calendar.DAY_OF_YEAR, 1)
        }

        if (points.isEmpty()) {
            listOf(SalesChartPoint("01/01", 0.0, 0.0, 0.0, 0.0))
        } else {
            points
        }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = {
                    Text(
                        text = if (isQuantityMode) "ကုန်ပစ္စည်းအလိုက်အရောင်း (အရေအတွက်)" else "အရောင်းအနှစ်ချုပ်",
                        fontWeight = FontWeight.Bold,
                        fontSize = 18.sp,
                        color = AppTextColor
                    )
                },
                navigationIcon = {
                    IconButton(onClick = { navController.popBackStack() }) {
                        Icon(imageVector = Icons.Filled.ArrowBack, contentDescription = "Back", tint = AppTextColor)
                    }
                },
                actions = {
                    IconButton(onClick = { showDatePicker = true }) {
                        Icon(
                            imageVector = Icons.Filled.CalendarMonth,
                            contentDescription = "Select Date Range",
                            tint = BrandPurple
                        )
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.White)
            )
        },
        bottomBar = {
            if (isQuantityMode && productSalesList.isNotEmpty()) {
                Surface(
                    tonalElevation = 8.dp,
                    shadowElevation = 8.dp,
                    color = Color.White,
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Column(
                        modifier = Modifier
                            .navigationBarsPadding()
                            .fillMaxWidth()
                            .padding(horizontal = 16.dp, vertical = 14.dp)
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Text(
                                text = "စုစုပေါင်း",
                                fontWeight = FontWeight.Bold,
                                fontSize = 15.sp,
                                color = AppTextColor,
                                modifier = Modifier.weight(2f)
                            )
                            Text(
                                text = "${productSalesList.sumOf { it.quantity }}",
                                fontWeight = FontWeight.Bold,
                                fontSize = 15.sp,
                                color = AppTextColor,
                                textAlign = TextAlign.Center,
                                modifier = Modifier.weight(1f)
                            )
                            Text(
                                text = "${numberFormat.format(productSalesList.sumOf { it.totalAmount }.toInt())} $selectedCurrency",
                                fontWeight = FontWeight.Bold,
                                fontSize = 15.sp,
                                color = BrandPurple,
                                textAlign = TextAlign.End,
                                modifier = Modifier.weight(1.5f)
                            )
                        }
                    }
                }
            }
        },
        modifier = Modifier.fillMaxSize()
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .background(Color(0xFFFAF9FD))
                .padding(innerPadding)
                .verticalScroll(rememberScrollState())
        ) {
            // Date Range Bar under TopBar
            Card(
                colors = CardDefaults.cardColors(containerColor = Color.White),
                shape = RoundedCornerShape(0.dp),
                modifier = Modifier
                    .fillMaxWidth()
                    .clickable { showDatePicker = true }
            ) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 16.dp, vertical = 12.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.SpaceBetween
                ) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Icon(
                            imageVector = Icons.Filled.DateRange,
                            contentDescription = null,
                            tint = Color.Gray,
                            modifier = Modifier.size(20.dp)
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(
                            text = "${dateFormatter.format(Date(startDate))} မှ ${dateFormatter.format(Date(endDate))} အထိ",
                            fontSize = 14.sp,
                            fontWeight = FontWeight.Medium,
                            color = Color.DarkGray
                        )
                    }
                    Icon(
                        imageVector = Icons.Filled.ChevronRight,
                        contentDescription = "Edit Date Range",
                        tint = Color.Gray,
                        modifier = Modifier.size(18.dp)
                    )
                }
            }

            if (!isQuantityMode) {
                Spacer(modifier = Modifier.height(12.dp))

                // Top 3 Metric Cards: စုစုပေါင်းအရောင်း | Discount | အသုံးစရိတ်
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 12.dp),
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    // Card 1: စုစုပေါင်းအရောင်း
                    Card(
                        modifier = Modifier.weight(1f),
                        colors = CardDefaults.cardColors(containerColor = Color(0xFFF3EFFF)),
                        shape = RoundedCornerShape(16.dp)
                    ) {
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(12.dp),
                            horizontalAlignment = Alignment.Start
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(36.dp)
                                    .background(Color(0xFFE2D6F8), CircleShape),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Filled.ShoppingCart,
                                    contentDescription = null,
                                    tint = Color(0xFF5E35B1),
                                    modifier = Modifier.size(18.dp)
                                )
                            }
                            Spacer(modifier = Modifier.height(10.dp))
                            Text(
                                text = "စုစုပေါင်းအရောင်း",
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color.DarkGray
                            )
                            Spacer(modifier = Modifier.height(4.dp))
                            Text(
                                text = "${numberFormat.format(totalSales.toInt())} $selectedCurrency",
                                fontSize = 13.sp,
                                fontWeight = FontWeight.Bold,
                                color = AppTextColor
                            )
                        }
                    }

                    // Card 2: Discount
                    Card(
                        modifier = Modifier.weight(1f),
                        colors = CardDefaults.cardColors(containerColor = Color(0xFFFFF3E8)),
                        shape = RoundedCornerShape(16.dp)
                    ) {
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(12.dp),
                            horizontalAlignment = Alignment.Start
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(36.dp)
                                    .background(Color(0xFFFFE1C4), CircleShape),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Filled.LocalOffer,
                                    contentDescription = null,
                                    tint = Color(0xFFFB8C00),
                                    modifier = Modifier.size(18.dp)
                                )
                            }
                            Spacer(modifier = Modifier.height(10.dp))
                            Text(
                                text = "Discount",
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color.DarkGray
                            )
                            Spacer(modifier = Modifier.height(4.dp))
                            Text(
                                text = "${numberFormat.format(totalDiscount.toInt())} $selectedCurrency",
                                fontSize = 13.sp,
                                fontWeight = FontWeight.Bold,
                                color = AppTextColor
                            )
                        }
                    }

                    // Card 3: အသုံးစရိတ်
                    Card(
                        modifier = Modifier.weight(1f),
                        colors = CardDefaults.cardColors(containerColor = Color(0xFFEDF4FE)),
                        shape = RoundedCornerShape(16.dp)
                    ) {
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(12.dp),
                            horizontalAlignment = Alignment.Start
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(36.dp)
                                    .background(Color(0xFFD3E5FD), CircleShape),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Filled.AccountBalanceWallet,
                                    contentDescription = null,
                                    tint = Color(0xFF1E88E5),
                                    modifier = Modifier.size(18.dp)
                                )
                            }
                            Spacer(modifier = Modifier.height(10.dp))
                            Text(
                                text = "အသုံးစရိတ်",
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color.DarkGray
                            )
                            Spacer(modifier = Modifier.height(4.dp))
                            Text(
                                text = "${numberFormat.format(totalExpenses.toInt())} $selectedCurrency",
                                fontSize = 13.sp,
                                fontWeight = FontWeight.Bold,
                                color = AppTextColor
                            )
                        }
                    }
                }

                Spacer(modifier = Modifier.height(12.dp))

                // Middle 2 Metric Cards: စုစုပေါင်းအမြတ် | အသားတင်အမြတ်
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 12.dp),
                    horizontalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    // Card 4: စုစုပေါင်းအမြတ်
                    Card(
                        modifier = Modifier.weight(1f),
                        colors = CardDefaults.cardColors(containerColor = Color(0xFFF1F8E9)),
                        shape = RoundedCornerShape(16.dp)
                    ) {
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(14.dp),
                            horizontalAlignment = Alignment.Start
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(40.dp)
                                    .background(Color(0xFFC8E6C9), CircleShape),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Filled.TrendingUp,
                                    contentDescription = null,
                                    tint = Color(0xFF2E7D32),
                                    modifier = Modifier.size(22.dp)
                                )
                            }
                            Spacer(modifier = Modifier.height(12.dp))
                            Text(
                                text = "စုစုပေါင်းအမြတ်",
                                fontSize = 13.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color.DarkGray
                            )
                            Spacer(modifier = Modifier.height(4.dp))
                            Text(
                                text = "${numberFormat.format(totalGrossProfit.toInt())} $selectedCurrency",
                                fontSize = 16.sp,
                                fontWeight = FontWeight.Bold,
                                color = AppTextColor
                            )
                        }
                    }

                    // Card 5: အသားတင်အမြတ်
                    Card(
                        modifier = Modifier.weight(1f),
                        colors = CardDefaults.cardColors(containerColor = Color(0xFFE8F8EE)),
                        shape = RoundedCornerShape(16.dp)
                    ) {
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(14.dp),
                            horizontalAlignment = Alignment.Start
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(40.dp)
                                    .background(Color(0xFFA5D6A7), CircleShape),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Filled.CheckCircle,
                                    contentDescription = null,
                                    tint = Color(0xFF388E3C),
                                    modifier = Modifier.size(22.dp)
                                )
                            }
                            Spacer(modifier = Modifier.height(12.dp))
                            Text(
                                text = "အသားတင်အမြတ်",
                                fontSize = 13.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color.DarkGray
                            )
                            Spacer(modifier = Modifier.height(4.dp))
                            Text(
                                text = "${numberFormat.format(totalNetProfit.toInt())} $selectedCurrency",
                                fontSize = 16.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color(0xFF2E7D32)
                            )
                        }
                    }
                }

                Spacer(modifier = Modifier.height(16.dp))

                // Chart Section
                Card(
                    colors = CardDefaults.cardColors(containerColor = Color.White),
                    shape = RoundedCornerShape(16.dp),
                    elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 12.dp)
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(16.dp)
                    ) {
                        Text(
                            text = "အရောင်းအချက်အလက် (နေ့စဉ်)",
                            fontSize = 15.sp,
                            fontWeight = FontWeight.Bold,
                            color = AppTextColor
                        )

                        Spacer(modifier = Modifier.height(12.dp))

                        // Chart Legends Row
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            LegendItem(color = Color(0xFF673AB7), label = "အရောင်း")
                            LegendItem(color = Color(0xFFFB8C00), label = "Discount")
                            LegendItem(color = Color(0xFF1E88E5), label = "အသုံးစရိတ်")
                            LegendItem(color = Color(0xFF4CAF50), label = "အမြတ်")
                        }

                        Spacer(modifier = Modifier.height(20.dp))

                        // Daily Bar Chart Component
                        SalesDailyGroupedBarChart(chartPoints = chartPoints)
                    }
                }

                Spacer(modifier = Modifier.height(16.dp))
            }

            if (isQuantityMode) {
                // Product Sales Breakdown Header & List (Full width like CustomerSalesReportScreen)
                Column(modifier = Modifier.fillMaxWidth()) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(Color(0xFFEFEBF9))
                            .padding(horizontal = 16.dp, vertical = 12.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = "ကုန်စည်အမည်",
                            fontWeight = FontWeight.Bold,
                            fontSize = 14.sp,
                            color = AppTextColor,
                            modifier = Modifier.weight(2f)
                        )
                        Text(
                            text = "အရေအတွက်",
                            fontWeight = FontWeight.Bold,
                            fontSize = 14.sp,
                            color = AppTextColor,
                            textAlign = TextAlign.Center,
                            modifier = Modifier.weight(1f)
                        )
                        Text(
                            text = "စုစုပေါင်း",
                            fontWeight = FontWeight.Bold,
                            fontSize = 14.sp,
                            color = AppTextColor,
                            textAlign = TextAlign.End,
                            modifier = Modifier.weight(1.5f)
                        )
                    }

                    if (productSalesList.isEmpty()) {
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(160.dp),
                            contentAlignment = Alignment.Center
                        ) {
                            Text("ရောင်းအားမှတ်တမ်း မရှိသေးပါ", color = Color.Gray, fontSize = 15.sp)
                        }
                    } else {
                        productSalesList.forEach { item ->
                            Column(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .background(Color.White)
                                    .clickable {
                                        navController.navigate("sales_product_detail/${Uri.encode(item.productName)}/$startDate/$endDate")
                                    }
                                    .padding(horizontal = 16.dp, vertical = 14.dp)
                            ) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text(
                                        text = item.productName,
                                        fontSize = 15.sp,
                                        fontWeight = FontWeight.Medium,
                                        color = AppTextColor,
                                        modifier = Modifier.weight(2f)
                                    )
                                    Text(
                                        text = "${item.quantity}",
                                        fontSize = 15.sp,
                                        color = AppTextColor,
                                        textAlign = TextAlign.Center,
                                        modifier = Modifier.weight(1f)
                                    )
                                    Text(
                                        text = "${numberFormat.format(item.totalAmount.toInt())} $selectedCurrency",
                                        fontSize = 15.sp,
                                        fontWeight = FontWeight.SemiBold,
                                        color = AppTextColor,
                                        textAlign = TextAlign.End,
                                        modifier = Modifier.weight(1.5f)
                                    )
                                }
                                HorizontalDivider(
                                    modifier = Modifier.padding(top = 12.dp),
                                    color = Color(0xFFF0EDF7)
                                )
                            }
                        }
                    }
                }
            }

            Spacer(modifier = Modifier.height(24.dp))
        }
    }

    if (showDatePicker) {
        MyDateRangePickerDialog(
            onDismissRequest = { showDatePicker = false },
            onDateRangeSelected = { start, end ->
                if (start != null && end != null) {
                    val utcStartCal = java.util.Calendar.getInstance(java.util.TimeZone.getTimeZone("UTC")).apply {
                        timeInMillis = start
                    }
                    val localStartCal = java.util.Calendar.getInstance().apply {
                        set(java.util.Calendar.YEAR, utcStartCal.get(java.util.Calendar.YEAR))
                        set(java.util.Calendar.MONTH, utcStartCal.get(java.util.Calendar.MONTH))
                        set(java.util.Calendar.DAY_OF_MONTH, utcStartCal.get(java.util.Calendar.DAY_OF_MONTH))
                        set(java.util.Calendar.HOUR_OF_DAY, 0)
                        set(java.util.Calendar.MINUTE, 0)
                        set(java.util.Calendar.SECOND, 0)
                        set(java.util.Calendar.MILLISECOND, 0)
                    }

                    val utcEndCal = java.util.Calendar.getInstance(java.util.TimeZone.getTimeZone("UTC")).apply {
                        timeInMillis = end
                    }
                    val localEndCal = java.util.Calendar.getInstance().apply {
                        set(java.util.Calendar.YEAR, utcEndCal.get(java.util.Calendar.YEAR))
                        set(java.util.Calendar.MONTH, utcEndCal.get(java.util.Calendar.MONTH))
                        set(java.util.Calendar.DAY_OF_MONTH, utcEndCal.get(java.util.Calendar.DAY_OF_MONTH))
                        set(java.util.Calendar.HOUR_OF_DAY, 23)
                        set(java.util.Calendar.MINUTE, 59)
                        set(java.util.Calendar.SECOND, 59)
                        set(java.util.Calendar.MILLISECOND, 999)
                    }

                    startDate = localStartCal.timeInMillis
                    endDate = localEndCal.timeInMillis
                }
                showDatePicker = false
            }
        )
    }
}

private data class SalesChartPoint(
    val dateLabel: String,
    val sales: Double,
    val discount: Double,
    val expenses: Double,
    val profit: Double
)

@Composable
private fun LegendItem(color: Color, label: String) {
    Row(verticalAlignment = Alignment.CenterVertically) {
        Box(
            modifier = Modifier
                .size(10.dp)
                .background(color, CircleShape)
        )
        Spacer(modifier = Modifier.width(4.dp))
        Text(
            text = label,
            fontSize = 12.sp,
            fontWeight = FontWeight.Medium,
            color = Color.DarkGray
        )
    }
}

@Composable
private fun SalesDailyGroupedBarChart(chartPoints: List<SalesChartPoint>) {
    val maxVal = remember(chartPoints) {
        chartPoints.flatMap { listOf(it.sales, it.discount, it.expenses, it.profit) }
            .maxOrNull()?.coerceAtLeast(100.0) ?: 100.0
    }

    val yLabels = remember(maxVal) {
        val step = maxVal / 4.0
        listOf(
            maxVal,
            step * 3,
            step * 2,
            step * 1,
            0.0
        )
    }

    fun formatShort(v: Double): String {
        return when {
            v >= 1_000_000 -> "${(v / 1_000_000).toInt()}M"
            v >= 1_000 -> "${(v / 1_000).toInt()}K"
            else -> "${v.toInt()}"
        }
    }

    val scrollState = rememberScrollState()
    LaunchedEffect(chartPoints) {
        if (chartPoints.isNotEmpty()) {
            scrollState.scrollTo(scrollState.maxValue)
        }
    }

    Column(modifier = Modifier.fillMaxWidth()) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .height(180.dp)
        ) {
            // Y-Axis Labels Column
            Column(
                modifier = Modifier
                    .fillMaxHeight()
                    .width(40.dp)
                    .padding(bottom = 20.dp),
                verticalArrangement = Arrangement.SpaceBetween,
                horizontalAlignment = Alignment.End
            ) {
                yLabels.forEach { labelVal ->
                    Text(
                        text = formatShort(labelVal),
                        fontSize = 10.sp,
                        color = Color.Gray
                    )
                }
            }

            Spacer(modifier = Modifier.width(8.dp))

            // Bars Grid Area
            Box(
                modifier = Modifier
                    .weight(1f)
                    .fillMaxHeight()
            ) {
                // Horizontal grid lines
                Column(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(bottom = 20.dp),
                    verticalArrangement = Arrangement.SpaceBetween
                ) {
                    repeat(5) {
                        HorizontalDivider(
                            color = Color(0xFFEEEEEE),
                            thickness = 1.dp
                        )
                    }
                }

                // Grouped Bars for each date point
                Row(
                    modifier = Modifier
                        .fillMaxSize()
                        .horizontalScroll(scrollState),
                    horizontalArrangement = Arrangement.spacedBy(10.dp),
                    verticalAlignment = Alignment.Bottom
                ) {
                    chartPoints.forEach { point ->
                        Column(
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.Bottom,
                            modifier = Modifier.fillMaxHeight()
                        ) {
                            Row(
                                verticalAlignment = Alignment.Bottom,
                                horizontalArrangement = Arrangement.spacedBy(2.dp),
                                modifier = Modifier
                                    .weight(1f)
                                    .padding(bottom = 4.dp)
                            ) {
                                // Sales Bar (Purple)
                                val sHeight = ((point.sales / maxVal).toFloat() * 120).coerceIn(0f, 120f)
                                Box(
                                    modifier = Modifier
                                        .width(5.dp)
                                        .height(sHeight.dp.coerceAtLeast(2.dp))
                                        .background(Color(0xFF673AB7), RoundedCornerShape(topStart = 3.dp, topEnd = 3.dp))
                                )

                                // Discount Bar (Orange)
                                val dHeight = ((point.discount / maxVal).toFloat() * 120).coerceIn(0f, 120f)
                                Box(
                                    modifier = Modifier
                                        .width(5.dp)
                                        .height(dHeight.dp.coerceAtLeast(2.dp))
                                        .background(Color(0xFFFB8C00), RoundedCornerShape(topStart = 3.dp, topEnd = 3.dp))
                                )

                                // Expenses Bar (Blue)
                                val eHeight = ((point.expenses / maxVal).toFloat() * 120).coerceIn(0f, 120f)
                                Box(
                                    modifier = Modifier
                                        .width(5.dp)
                                        .height(eHeight.dp.coerceAtLeast(2.dp))
                                        .background(Color(0xFF1E88E5), RoundedCornerShape(topStart = 3.dp, topEnd = 3.dp))
                                )

                                // Profit Bar (Green)
                                val pHeight = ((point.profit / maxVal).toFloat() * 120).coerceIn(0f, 120f)
                                Box(
                                    modifier = Modifier
                                        .width(5.dp)
                                        .height(pHeight.dp.coerceAtLeast(2.dp))
                                        .background(Color(0xFF4CAF50), RoundedCornerShape(topStart = 3.dp, topEnd = 3.dp))
                                )
                            }

                            Text(
                                text = point.dateLabel,
                                fontSize = 9.sp,
                                color = Color.DarkGray,
                                fontWeight = FontWeight.Medium
                            )
                        }
                    }
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun SalesProductDetailScreen(
    navController: NavController,
    viewModel: POSViewModel,
    productName: String,
    startDate: Long,
    endDate: Long
) {
    val vouchers by viewModel.allVouchers.collectAsState()
    val voucherItems by viewModel.allVoucherItems.collectAsState()
    val selectedCurrency by viewModel.selectedCurrency.collectAsState()

    val productVouchers = remember(vouchers, voucherItems, productName, startDate, endDate) {
        vouchers.filter { voucher ->
            !voucher.isPurchase && voucher.isCompleted && voucher.timestamp in startDate..endDate
        }.mapNotNull { voucher ->
            val items = voucherItems.filter { it.voucherId == voucher.receiptNo && it.productName == productName }
            if (items.isNotEmpty()) {
                Pair(voucher, items)
            } else {
                null
            }
        }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = {
                    Text(
                        text = productName,
                        fontWeight = FontWeight.Bold,
                        fontSize = 18.sp,
                        color = AppTextColor
                    )
                },
                navigationIcon = {
                    IconButton(onClick = { navController.popBackStack() }) {
                        Icon(imageVector = Icons.Filled.ArrowBack, contentDescription = "Back", tint = AppTextColor)
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.White)
            )
        },
        modifier = Modifier.fillMaxSize()
    ) { innerPadding ->
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(LightBg)
                .padding(innerPadding)
        ) {
            if (productVouchers.isEmpty()) {
                Box(
                    modifier = Modifier.fillMaxSize(),
                    contentAlignment = Alignment.Center
                ) {
                    Text("မှတ်တမ်း မရှိသေးပါ", color = Color.Gray, fontSize = 15.sp)
                }
            } else {
                LazyColumn(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(horizontal = 16.dp, vertical = 8.dp),
                    verticalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    items(productVouchers) { (voucher, items) ->
                        val totalQty = items.sumOf { it.quantity }
                        val unitPrice = items.firstOrNull()?.sellingPrice ?: 0.0
                        val totalAmount = totalQty * unitPrice
                        val dateString = remember(voucher.timestamp) {
                            SimpleDateFormat("dd/MM/yyyy", Locale.US).format(Date(voucher.timestamp))
                        }

                        Card(
                            colors = CardDefaults.cardColors(containerColor = Color.White),
                            shape = RoundedCornerShape(12.dp),
                            elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
                            modifier = Modifier
                                .fillMaxWidth()
                                .clickable {
                                    navController.navigate("receipt_detail/${voucher.receiptNo}/${Uri.encode(productName)}")
                                }
                        ) {
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(16.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(44.dp)
                                        .clip(RoundedCornerShape(8.dp))
                                        .background(Color(0xFFECE9F5)),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        imageVector = Icons.Filled.ShoppingBag,
                                        contentDescription = null,
                                        tint = BrandPurple,
                                        modifier = Modifier.size(24.dp)
                                    )
                                }

                                Spacer(modifier = Modifier.width(12.dp))

                                Column(
                                    modifier = Modifier.weight(1f)
                                ) {
                                    Text(
                                        text = productName,
                                        fontSize = 15.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = AppTextColor
                                    )
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Text(
                                        text = dateString,
                                        fontSize = 12.sp,
                                        color = Color.Gray
                                    )
                                }

                                Column(
                                    horizontalAlignment = Alignment.End
                                ) {
                                    Text(
                                        text = "${String.format("%,.0f", totalAmount)} $selectedCurrency",
                                        fontSize = 15.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = AppTextColor
                                    )
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Text(
                                        text = "${totalQty}x${String.format("%,.0f", unitPrice)} $selectedCurrency",
                                        fontSize = 12.sp,
                                        color = Color.Gray
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

// Data class for Customer Sales Reports
data class CustomerSalesData(
    val customerName: String,
    val quantity: Int,
    val totalAmount: Double
)

// Data class for Profit/Loss Reports
data class ProductProfitData(
    val productName: String,
    val quantity: Int,
    val totalSales: Double,
    val totalProfit: Double
)

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun CustomerSalesTotalScreen(
    navController: NavController,
    viewModel: POSViewModel
) {
    val vouchers by viewModel.allVouchers.collectAsState()
    val voucherItems by viewModel.allVoucherItems.collectAsState()
    val selectedCurrency by viewModel.selectedCurrency.collectAsState()

    // Default: first day of current month to today
    val calendar = remember { java.util.Calendar.getInstance() }
    val todayMillis = calendar.timeInMillis
    val firstDayOfMonthMillis = remember {
        val cal = java.util.Calendar.getInstance()
        cal.set(java.util.Calendar.DAY_OF_MONTH, 1)
        cal.set(java.util.Calendar.HOUR_OF_DAY, 0)
        cal.set(java.util.Calendar.MINUTE, 0)
        cal.set(java.util.Calendar.SECOND, 0)
        cal.set(java.util.Calendar.MILLISECOND, 0)
        cal.timeInMillis
    }

    var startDate by remember { mutableStateOf(firstDayOfMonthMillis) }
    var endDate by remember { mutableStateOf(todayMillis) }
    var showDatePicker by remember { mutableStateOf(false) }

    val dateFormatter = remember { SimpleDateFormat("dd/MM/yyyy", Locale.US) }

    // Filter and aggregate data
    val completedSalesVouchers = remember(vouchers, startDate, endDate) {
        vouchers.filter { voucher ->
            !voucher.isPurchase && voucher.isCompleted && voucher.timestamp in startDate..endDate
        }
    }

    val customerSalesList = remember(completedSalesVouchers, voucherItems) {
        val voucherIdsByCustomer = completedSalesVouchers.groupBy { it.customerName.trim() }
        voucherIdsByCustomer.map { (customerName, customerVouchers) ->
            val vIds = customerVouchers.map { it.receiptNo }.toSet()
            val items = voucherItems.filter { it.voucherId in vIds }
            val totalQty = items.sumOf { it.quantity }
            val totalAmount = customerVouchers.sumOf { it.totalAmount }
            CustomerSalesData(
                customerName = if (customerName.isBlank() || customerName.equals("Not Register", ignoreCase = true)) "Not Register" else customerName,
                quantity = totalQty,
                totalAmount = totalAmount
            )
        }.sortedByDescending { it.totalAmount }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = {
                    Text(
                        text = "Customer အလိုက်စုစုပေါင်းဝယ်ယူမှု",
                        fontWeight = FontWeight.Bold,
                        fontSize = 18.sp,
                        color = AppTextColor
                    )
                },
                navigationIcon = {
                    IconButton(onClick = { navController.popBackStack() }) {
                        Icon(imageVector = Icons.Filled.ArrowBack, contentDescription = "Back", tint = AppTextColor)
                    }
                },
                actions = {
                    IconButton(onClick = { showDatePicker = true }) {
                        Icon(
                            imageVector = Icons.Filled.DateRange,
                            contentDescription = "Select Date Range",
                            tint = BrandPurple
                        )
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.White)
            )
        },
        bottomBar = {
            if (customerSalesList.isNotEmpty()) {
                Surface(
                    tonalElevation = 8.dp,
                    shadowElevation = 8.dp,
                    color = Color.White,
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Column(
                        modifier = Modifier
                            .navigationBarsPadding()
                            .fillMaxWidth()
                            .padding(horizontal = 16.dp, vertical = 14.dp)
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Text(
                                text = "စုစုပေါင်း",
                                fontWeight = FontWeight.Bold,
                                fontSize = 15.sp,
                                color = AppTextColor,
                                modifier = Modifier.weight(2f)
                            )
                            Text(
                                text = "${customerSalesList.sumOf { it.quantity }}",
                                fontWeight = FontWeight.Bold,
                                fontSize = 15.sp,
                                color = AppTextColor,
                                textAlign = TextAlign.Center,
                                modifier = Modifier.weight(1f)
                            )
                            Text(
                                text = "${String.format("%,.0f", customerSalesList.sumOf { it.totalAmount })} $selectedCurrency",
                                fontWeight = FontWeight.Bold,
                                fontSize = 15.sp,
                                color = BrandPurple,
                                textAlign = TextAlign.End,
                                modifier = Modifier.weight(1.5f)
                            )
                        }
                    }
                }
            }
        },
        modifier = Modifier.fillMaxSize()
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .background(Color(0xFFFAF9FD))
                .padding(innerPadding)
        ) {
            // Date Range under ActionBar
            Card(
                colors = CardDefaults.cardColors(containerColor = Color.White),
                shape = RoundedCornerShape(0.dp),
                modifier = Modifier
                    .fillMaxWidth()
                    .clickable { showDatePicker = true }
            ) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 16.dp, vertical = 12.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.SpaceBetween
                ) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Icon(
                            imageVector = Icons.Filled.DateRange,
                            contentDescription = null,
                            tint = Color.Gray,
                            modifier = Modifier.size(18.dp)
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(
                            text = "${dateFormatter.format(Date(startDate))} မှ ${dateFormatter.format(Date(endDate))} အထိ",
                            fontSize = 14.sp,
                            fontWeight = FontWeight.Medium,
                            color = Color.DarkGray
                        )
                    }
                    Icon(
                        imageVector = Icons.Filled.ChevronRight,
                        contentDescription = "Edit Date Range",
                        tint = Color.Gray,
                        modifier = Modifier.size(16.dp)
                    )
                }
            }

            // Header row: စျေးဝယ်သူ | အရေအတွက် | စုစုပေါင်း
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(Color(0xFFEFEBF9))
                    .padding(horizontal = 16.dp, vertical = 12.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = "စျေးဝယ်သူ",
                    fontWeight = FontWeight.Bold,
                    fontSize = 14.sp,
                    color = AppTextColor,
                    modifier = Modifier.weight(2f)
                )
                Text(
                    text = "အရေအတွက်",
                    fontWeight = FontWeight.Bold,
                    fontSize = 14.sp,
                    color = AppTextColor,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.weight(1f)
                )
                Text(
                    text = "စုစုပေါင်း",
                    fontWeight = FontWeight.Bold,
                    fontSize = 14.sp,
                    color = AppTextColor,
                    textAlign = TextAlign.End,
                    modifier = Modifier.weight(1.5f)
                )
            }

            if (customerSalesList.isEmpty()) {
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .weight(1f),
                    contentAlignment = Alignment.Center
                ) {
                    Text("ဝယ်ယူမှုမှတ်တမ်း မရှိသေးပါ", color = Color.Gray, fontSize = 15.sp)
                }
            } else {
                LazyColumn(
                    modifier = Modifier
                        .fillMaxSize()
                        .weight(1f)
                ) {
                    items(customerSalesList) { item ->
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clickable {
                                    navController.navigate("customer_sales_detail/${Uri.encode(item.customerName)}/$startDate/$endDate")
                                }
                                .padding(horizontal = 16.dp, vertical = 14.dp)
                        ) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = item.customerName,
                                    fontSize = 15.sp,
                                    fontWeight = FontWeight.Medium,
                                    color = AppTextColor,
                                    modifier = Modifier.weight(2f)
                                )
                                Text(
                                    text = "${item.quantity}",
                                    fontSize = 15.sp,
                                    color = AppTextColor,
                                    textAlign = TextAlign.Center,
                                    modifier = Modifier.weight(1f)
                                )
                                Text(
                                    text = "${String.format("%,.0f", item.totalAmount)} $selectedCurrency",
                                    fontSize = 15.sp,
                                    fontWeight = FontWeight.SemiBold,
                                    color = AppTextColor,
                                    textAlign = TextAlign.End,
                                    modifier = Modifier.weight(1.5f)
                                )
                            }
                            HorizontalDivider(
                                modifier = Modifier.padding(top = 12.dp),
                                color = Color(0xFFF0EDF7)
                            )
                        }
                    }
                }
            }
        }
    }

    if (showDatePicker) {
        MyDateRangePickerDialog(
            onDismissRequest = { showDatePicker = false },
            onDateRangeSelected = { start, end ->
                if (start != null && end != null) {
                    val utcStartCal = java.util.Calendar.getInstance(java.util.TimeZone.getTimeZone("UTC")).apply {
                        timeInMillis = start
                    }
                    val localStartCal = java.util.Calendar.getInstance().apply {
                        set(java.util.Calendar.YEAR, utcStartCal.get(java.util.Calendar.YEAR))
                        set(java.util.Calendar.MONTH, utcStartCal.get(java.util.Calendar.MONTH))
                        set(java.util.Calendar.DAY_OF_MONTH, utcStartCal.get(java.util.Calendar.DAY_OF_MONTH))
                        set(java.util.Calendar.HOUR_OF_DAY, 0)
                        set(java.util.Calendar.MINUTE, 0)
                        set(java.util.Calendar.SECOND, 0)
                        set(java.util.Calendar.MILLISECOND, 0)
                    }
                    startDate = localStartCal.timeInMillis

                    val utcEndCal = java.util.Calendar.getInstance(java.util.TimeZone.getTimeZone("UTC")).apply {
                        timeInMillis = end
                    }
                    val localEndCal = java.util.Calendar.getInstance().apply {
                        set(java.util.Calendar.YEAR, utcEndCal.get(java.util.Calendar.YEAR))
                        set(java.util.Calendar.MONTH, utcEndCal.get(java.util.Calendar.MONTH))
                        set(java.util.Calendar.DAY_OF_MONTH, utcEndCal.get(java.util.Calendar.DAY_OF_MONTH))
                        set(java.util.Calendar.HOUR_OF_DAY, 23)
                        set(java.util.Calendar.MINUTE, 59)
                        set(java.util.Calendar.SECOND, 59)
                        set(java.util.Calendar.MILLISECOND, 999)
                    }
                    endDate = localEndCal.timeInMillis
                }
            }
        )
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun CustomerSalesDetailScreen(
    navController: NavController,
    viewModel: POSViewModel,
    customerName: String,
    startDate: Long,
    endDate: Long
) {
    val vouchers by viewModel.allVouchers.collectAsState()
    val voucherItems by viewModel.allVoucherItems.collectAsState()
    val selectedCurrency by viewModel.selectedCurrency.collectAsState()

    val customerPurchases = remember(vouchers, voucherItems, customerName, startDate, endDate) {
        val filteredVouchers = vouchers.filter { voucher ->
            !voucher.isPurchase && 
            voucher.isCompleted && 
            voucher.timestamp in startDate..endDate && 
            (if (customerName == "Not Register") {
                voucher.customerName.isBlank() || voucher.customerName.equals("Not Register", ignoreCase = true)
            } else {
                voucher.customerName.trim().equals(customerName.trim(), ignoreCase = true)
            })
        }
        val vIds = filteredVouchers.map { it.receiptNo }.toSet()
        val items = voucherItems.filter { it.voucherId in vIds }
        
        items.mapNotNull { item ->
            val v = filteredVouchers.find { it.receiptNo == item.voucherId }
            if (v != null) Pair(item, v) else null
        }.sortedByDescending { it.second.timestamp }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = {
                    Text(
                        text = customerName,
                        fontWeight = FontWeight.Bold,
                        fontSize = 18.sp,
                        color = AppTextColor
                    )
                },
                navigationIcon = {
                    IconButton(onClick = { navController.popBackStack() }) {
                        Icon(imageVector = Icons.Filled.ArrowBack, contentDescription = "Back", tint = AppTextColor)
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.White)
            )
        },
        modifier = Modifier.fillMaxSize()
    ) { innerPadding ->
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(LightBg)
                .padding(innerPadding)
        ) {
            if (customerPurchases.isEmpty()) {
                Box(
                    modifier = Modifier.fillMaxSize(),
                    contentAlignment = Alignment.Center
                ) {
                    Text("မှတ်တမ်း မရှိသေးပါ", color = Color.Gray, fontSize = 15.sp)
                }
            } else {
                LazyColumn(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(horizontal = 16.dp, vertical = 8.dp),
                    verticalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    items(customerPurchases) { (item, voucher) ->
                        val dateString = remember(voucher.timestamp) {
                            SimpleDateFormat("dd/MM/yyyy", Locale.US).format(Date(voucher.timestamp))
                        }

                        Card(
                            colors = CardDefaults.cardColors(containerColor = Color.White),
                            shape = RoundedCornerShape(12.dp),
                            elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
                            modifier = Modifier
                                .fillMaxWidth()
                                .clickable {
                                    navController.navigate("receipt_detail/${voucher.receiptNo}/${Uri.encode(item.productName)}")
                                }
                        ) {
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(16.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(44.dp)
                                        .clip(RoundedCornerShape(8.dp))
                                        .background(Color(0xFFECE9F5)),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        imageVector = Icons.Filled.ShoppingBag,
                                        contentDescription = null,
                                        tint = BrandPurple,
                                        modifier = Modifier.size(24.dp)
                                    )
                                }

                                Spacer(modifier = Modifier.width(12.dp))

                                Column(
                                    modifier = Modifier.weight(1f)
                                ) {
                                    Text(
                                        text = item.productName,
                                        fontSize = 15.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = AppTextColor
                                    )
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Text(
                                        text = dateString,
                                        fontSize = 12.sp,
                                        color = Color.Gray
                                    )
                                }

                                Column(
                                    horizontalAlignment = Alignment.End
                                ) {
                                    val totalAmount = item.quantity * item.sellingPrice
                                    Text(
                                        text = "${String.format("%,.0f", totalAmount)} $selectedCurrency",
                                        fontSize = 15.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = AppTextColor
                                    )
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Text(
                                        text = "${item.quantity}x${String.format("%,.0f", item.sellingPrice)} $selectedCurrency",
                                        fontSize = 12.sp,
                                        color = Color.Gray
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun ProfitLossReportScreen(
    navController: NavController,
    viewModel: POSViewModel
) {
    val vouchers by viewModel.allVouchers.collectAsState()
    val voucherItems by viewModel.allVoucherItems.collectAsState()
    val selectedCurrency by viewModel.selectedCurrency.collectAsState()

    // Default: current month (1st day of month to last day of month)
    val calendar = remember { java.util.Calendar.getInstance() }
    val firstDayOfMonthMillis = remember {
        val cal = java.util.Calendar.getInstance()
        cal.set(java.util.Calendar.DAY_OF_MONTH, 1)
        cal.set(java.util.Calendar.HOUR_OF_DAY, 0)
        cal.set(java.util.Calendar.MINUTE, 0)
        cal.set(java.util.Calendar.SECOND, 0)
        cal.set(java.util.Calendar.MILLISECOND, 0)
        cal.timeInMillis
    }
    val lastDayOfMonthMillis = remember {
        val cal = java.util.Calendar.getInstance()
        cal.set(java.util.Calendar.DAY_OF_MONTH, cal.getActualMaximum(java.util.Calendar.DAY_OF_MONTH))
        cal.set(java.util.Calendar.HOUR_OF_DAY, 23)
        cal.set(java.util.Calendar.MINUTE, 59)
        cal.set(java.util.Calendar.SECOND, 59)
        cal.set(java.util.Calendar.MILLISECOND, 999)
        cal.timeInMillis
    }

    var startDate by remember { mutableStateOf(firstDayOfMonthMillis) }
    var endDate by remember { mutableStateOf(lastDayOfMonthMillis) }
    var showDatePicker by remember { mutableStateOf(false) }

    val dateFormatter = remember { SimpleDateFormat("dd/MM/yyyy", Locale.US) }

    // Filter and aggregate data
    val completedSalesVouchers = remember(vouchers, startDate, endDate) {
        vouchers.filter { voucher ->
            !voucher.isPurchase && voucher.isCompleted && voucher.timestamp in startDate..endDate
        }
    }

    val completedVoucherIds = remember(completedSalesVouchers) {
        completedSalesVouchers.map { it.receiptNo }.toSet()
    }

    val filteredItems = remember(voucherItems, completedVoucherIds) {
        voucherItems.filter { it.voucherId in completedVoucherIds }
    }

    val productProfitList = remember(filteredItems) {
        filteredItems.groupBy { it.productName }
            .map { (productName, items) ->
                val totalQty = items.sumOf { it.quantity }
                val totalSales = items.sumOf { it.quantity * it.sellingPrice }
                val totalProfit = items.sumOf { (it.sellingPrice - it.purchasePrice) * it.quantity }
                ProductProfitData(
                    productName = productName,
                    quantity = totalQty,
                    totalSales = totalSales,
                    totalProfit = totalProfit
                )
            }
            .sortedByDescending { it.totalProfit }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = {
                    Text(
                        text = "အမြတ်စာရင်း",
                        fontWeight = FontWeight.Bold,
                        fontSize = 18.sp,
                        color = AppTextColor
                    )
                },
                navigationIcon = {
                    IconButton(onClick = { navController.popBackStack() }) {
                        Icon(imageVector = Icons.Filled.ArrowBack, contentDescription = "Back", tint = AppTextColor)
                    }
                },
                actions = {
                    IconButton(onClick = { showDatePicker = true }) {
                        Icon(
                            imageVector = Icons.Filled.DateRange,
                            contentDescription = "Select Date Range",
                            tint = BrandPurple
                        )
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.White)
            )
        },
        bottomBar = {
            if (productProfitList.isNotEmpty()) {
                Surface(
                    tonalElevation = 8.dp,
                    shadowElevation = 8.dp,
                    color = Color.White,
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Column(
                        modifier = Modifier
                            .navigationBarsPadding()
                            .fillMaxWidth()
                            .padding(horizontal = 16.dp, vertical = 14.dp)
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Text(
                                text = "စုစုပေါင်း အမြတ်",
                                fontWeight = FontWeight.Bold,
                                fontSize = 15.sp,
                                color = AppTextColor,
                                modifier = Modifier.weight(2f)
                            )
                            Text(
                                text = "${productProfitList.sumOf { it.quantity }}",
                                fontWeight = FontWeight.Bold,
                                fontSize = 15.sp,
                                color = AppTextColor,
                                textAlign = TextAlign.Center,
                                modifier = Modifier.weight(1f)
                            )
                            Text(
                                text = "${String.format("%,.0f", productProfitList.sumOf { it.totalProfit })} $selectedCurrency",
                                fontWeight = FontWeight.Bold,
                                fontSize = 15.sp,
                                color = BrandPurple,
                                textAlign = TextAlign.End,
                                modifier = Modifier.weight(1.5f)
                            )
                        }
                    }
                }
            }
        },
        modifier = Modifier.fillMaxSize()
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .background(Color(0xFFFAF9FD))
                .padding(innerPadding)
        ) {
            // Date Range under ActionBar
            Card(
                colors = CardDefaults.cardColors(containerColor = Color.White),
                shape = RoundedCornerShape(0.dp),
                modifier = Modifier
                    .fillMaxWidth()
                    .clickable { showDatePicker = true }
            ) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 16.dp, vertical = 12.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.SpaceBetween
                ) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Icon(
                            imageVector = Icons.Filled.DateRange,
                            contentDescription = null,
                            tint = Color.Gray,
                            modifier = Modifier.size(18.dp)
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(
                            text = "${dateFormatter.format(Date(startDate))} မှ ${dateFormatter.format(Date(endDate))} အထိ",
                            fontSize = 14.sp,
                            fontWeight = FontWeight.Medium,
                            color = Color.DarkGray
                        )
                    }
                    Icon(
                        imageVector = Icons.Filled.ChevronRight,
                        contentDescription = "Edit Date Range",
                        tint = Color.Gray,
                        modifier = Modifier.size(16.dp)
                    )
                }
            }

            // Header row: ကုန်စည်အမည် | အရေအတွက် | အမြတ်
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(Color(0xFFEFEBF9))
                    .padding(horizontal = 16.dp, vertical = 12.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = "ကုန်စည်အမည်",
                    fontWeight = FontWeight.Bold,
                    fontSize = 14.sp,
                    color = AppTextColor,
                    modifier = Modifier.weight(2f)
                )
                Text(
                    text = "အရေအတွက်",
                    fontWeight = FontWeight.Bold,
                    fontSize = 14.sp,
                    color = AppTextColor,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.weight(1f)
                )
                Text(
                    text = "အမြတ်",
                    fontWeight = FontWeight.Bold,
                    fontSize = 14.sp,
                    color = AppTextColor,
                    textAlign = TextAlign.End,
                    modifier = Modifier.weight(1.5f)
                )
            }

            if (productProfitList.isEmpty()) {
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .weight(1f),
                    contentAlignment = Alignment.Center
                ) {
                    Text("ရောင်းအားမှတ်တမ်း မရှိသေးပါ", color = Color.Gray, fontSize = 15.sp)
                }
            } else {
                LazyColumn(
                    modifier = Modifier
                        .fillMaxSize()
                        .weight(1f)
                ) {
                    items(productProfitList) { item ->
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clickable {
                                    navController.navigate("sales_product_detail/${Uri.encode(item.productName)}/$startDate/$endDate")
                                }
                                .padding(horizontal = 16.dp, vertical = 14.dp)
                        ) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = item.productName,
                                    fontSize = 15.sp,
                                    fontWeight = FontWeight.Medium,
                                    color = AppTextColor,
                                    modifier = Modifier.weight(2f)
                                )
                                Text(
                                    text = "${item.quantity}",
                                    fontSize = 15.sp,
                                    color = AppTextColor,
                                    textAlign = TextAlign.Center,
                                    modifier = Modifier.weight(1f)
                                )
                                Text(
                                    text = "${String.format("%,.0f", item.totalProfit)} $selectedCurrency",
                                    fontSize = 15.sp,
                                    fontWeight = FontWeight.SemiBold,
                                    color = if (item.totalProfit >= 0) BrandPurple else Color.Red,
                                    textAlign = TextAlign.End,
                                    modifier = Modifier.weight(1.5f)
                                )
                            }
                            HorizontalDivider(
                                modifier = Modifier.padding(top = 12.dp),
                                color = Color(0xFFF0EDF7)
                            )
                        }
                    }
                }
            }
        }
    }

    if (showDatePicker) {
        MyDateRangePickerDialog(
            onDismissRequest = { showDatePicker = false },
            onDateRangeSelected = { start, end ->
                if (start != null && end != null) {
                    val utcStartCal = java.util.Calendar.getInstance(java.util.TimeZone.getTimeZone("UTC")).apply {
                        timeInMillis = start
                    }
                    val localStartCal = java.util.Calendar.getInstance().apply {
                        set(java.util.Calendar.YEAR, utcStartCal.get(java.util.Calendar.YEAR))
                        set(java.util.Calendar.MONTH, utcStartCal.get(java.util.Calendar.MONTH))
                        set(java.util.Calendar.DAY_OF_MONTH, utcStartCal.get(java.util.Calendar.DAY_OF_MONTH))
                        set(java.util.Calendar.HOUR_OF_DAY, 0)
                        set(java.util.Calendar.MINUTE, 0)
                        set(java.util.Calendar.SECOND, 0)
                        set(java.util.Calendar.MILLISECOND, 0)
                    }
                    startDate = localStartCal.timeInMillis

                    val utcEndCal = java.util.Calendar.getInstance(java.util.TimeZone.getTimeZone("UTC")).apply {
                        timeInMillis = end
                    }
                    val localEndCal = java.util.Calendar.getInstance().apply {
                        set(java.util.Calendar.YEAR, utcEndCal.get(java.util.Calendar.YEAR))
                        set(java.util.Calendar.MONTH, utcEndCal.get(java.util.Calendar.MONTH))
                        set(java.util.Calendar.DAY_OF_MONTH, utcEndCal.get(java.util.Calendar.DAY_OF_MONTH))
                        set(java.util.Calendar.HOUR_OF_DAY, 23)
                        set(java.util.Calendar.MINUTE, 59)
                        set(java.util.Calendar.SECOND, 59)
                        set(java.util.Calendar.MILLISECOND, 999)
                    }
                    endDate = localEndCal.timeInMillis
                }
            }
        )
    }
}

fun getExpenseIcon(iconName: String): ImageVector {
    return when (iconName) {
        "LocalGasStation", "Gas" -> Icons.Filled.LocalGasStation
        "Store" -> Icons.Filled.Store
        "ShoppingBag" -> Icons.Filled.ShoppingBag
        "AttachMoney" -> Icons.Filled.AttachMoney
        "Checkroom", "Glasses" -> Icons.Filled.ShoppingBag
        "Restaurant" -> Icons.Filled.Restaurant
        "LocalBar" -> Icons.Filled.LocalBar
        "LocalTaxi" -> Icons.Filled.LocalTaxi
        "DirectionsCar" -> Icons.Filled.DirectionsCar
        "DirectionsBus" -> Icons.Filled.DirectionsBus
        "DirectionsBike" -> Icons.Filled.DirectionsBike
        "Flight" -> Icons.Filled.Flight
        "Build" -> Icons.Filled.Build
        "MedicalServices" -> Icons.Filled.MedicalServices
        "School" -> Icons.Filled.School
        "Home" -> Icons.Filled.Home
        "Phone" -> Icons.Filled.Phone
        "Wifi" -> Icons.Filled.Wifi
        "Email" -> Icons.Filled.Email
        "CameraAlt" -> Icons.Filled.CameraAlt
        "Star" -> Icons.Filled.Star
        "Work" -> Icons.Filled.Work
        "AccountBalance" -> Icons.Filled.AccountBalance
        else -> Icons.Filled.ShoppingCart
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AddExpenseScreen(
    navController: NavController,
    viewModel: POSViewModel,
    expenseId: Long = 0L
) {
    val context = LocalContext.current
    val scope = rememberCoroutineScope()

    val selectedCategoryName by viewModel.selectedExpenseCategoryName.collectAsState()
    val selectedCategoryIcon by viewModel.selectedExpenseCategoryIcon.collectAsState()
    val payments by viewModel.allPayments.collectAsState()

    var description by remember { mutableStateOf("") }
    var amountText by remember { mutableStateOf("") }
    var paymentMethod by remember { mutableStateOf("CASH") }
    var note by remember { mutableStateOf("") }

    val calendar = remember { Calendar.getInstance() }
    var dateString by remember { mutableStateOf(SimpleDateFormat("yyyy-MM-dd", Locale.US).format(calendar.time)) }
    var timeString by remember { mutableStateOf(SimpleDateFormat("h:mm a", Locale.US).format(calendar.time).uppercase()) }
    var timestamp by remember { mutableStateOf(calendar.timeInMillis) }

    var showDatePicker by remember { mutableStateOf(false) }
    var showTimePicker by remember { mutableStateOf(false) }

    val drawerState = rememberDrawerState(initialValue = DrawerValue.Closed)
    val snackbarHostState = remember { SnackbarHostState() }

    LaunchedEffect(expenseId) {
        if (expenseId > 0L) {
            val existing = viewModel.getExpenseById(expenseId)
            if (existing != null) {
                if (viewModel.selectedExpenseCategoryName.value.isBlank()) {
                    viewModel.selectedExpenseCategoryName.value = existing.categoryName
                }
                description = existing.description
                amountText = if (existing.amount % 1.0 == 0.0) String.format("%.1f", existing.amount) else existing.amount.toString()
                paymentMethod = existing.paymentMethod
                note = existing.note
                timestamp = existing.timestamp
                dateString = existing.dateString.ifBlank { SimpleDateFormat("yyyy-MM-dd", Locale.US).format(Date(existing.timestamp)) }
                timeString = existing.timeString.ifBlank { SimpleDateFormat("h:mm a", Locale.US).format(Date(existing.timestamp)).uppercase() }
            }
        }
    }

    CompositionLocalProvider(LocalLayoutDirection provides LayoutDirection.Rtl) {
        ModalNavigationDrawer(
            drawerState = drawerState,
            drawerContent = {
                CompositionLocalProvider(LocalLayoutDirection provides LayoutDirection.Ltr) {
                    ModalDrawerSheet(
                        drawerContainerColor = Color.White,
                        modifier = Modifier.width(320.dp)
                    ) {
                        Column(
                            modifier = Modifier
                                .fillMaxSize()
                                .padding(16.dp)
                        ) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = "ငွေပေးချေမှု ရွေးချယ်ပါ",
                                    fontSize = 18.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = AppTextColor
                                )
                                IconButton(onClick = { scope.launch { drawerState.close() } }) {
                                    Icon(imageVector = Icons.Filled.Close, contentDescription = "Close", tint = Color.Gray)
                                }
                            }

                            Spacer(modifier = Modifier.height(12.dp))

                            var searchPayment by remember { mutableStateOf("") }
                            OutlinedTextField(
                                value = searchPayment,
                                onValueChange = { searchPayment = it },
                                placeholder = { Text("ရှာဖွေရန်") },
                                leadingIcon = { Icon(Icons.Filled.Search, contentDescription = null, tint = Color.Gray) },
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(bottom = 12.dp),
                                shape = RoundedCornerShape(12.dp),
                                singleLine = true,
                                colors = OutlinedTextFieldDefaults.colors(
                                    focusedBorderColor = BrandPurple,
                                    unfocusedBorderColor = Color.LightGray
                                )
                            )

                            val availablePaymentMethods = remember(payments) {
                                val list = mutableListOf<String>()
                                if (payments.isNotEmpty()) {
                                    payments.map { it.method }.distinct().forEach { method ->
                                        if (method.isNotBlank()) list.add(method)
                                    }
                                }
                                if (!list.any { it.equals("Cash", ignoreCase = true) || it.equals("CASH", ignoreCase = true) }) {
                                    list.add(0, "CASH")
                                }
                                if (!list.any { it.equals("Credit", ignoreCase = true) || it.equals("CREDIT", ignoreCase = true) }) {
                                    list.add(1, "CREDIT")
                                }
                                list.distinct()
                            }

                            val filteredPaymentMethods = availablePaymentMethods.filter {
                                it.contains(searchPayment, ignoreCase = true)
                            }

                            LazyColumn(
                                modifier = Modifier.fillMaxWidth(),
                                verticalArrangement = Arrangement.spacedBy(4.dp)
                            ) {
                                items(filteredPaymentMethods) { method ->
                                    val isSelected = paymentMethod.equals(method, ignoreCase = true)
                                    Row(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .clip(RoundedCornerShape(8.dp))
                                            .background(
                                                if (isSelected) BrandPurple.copy(alpha = 0.1f)
                                                else Color.Transparent
                                            )
                                            .clickable {
                                                paymentMethod = method
                                                scope.launch { drawerState.close() }
                                            }
                                            .padding(vertical = 12.dp, horizontal = 12.dp),
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Box(
                                            modifier = Modifier
                                                .size(36.dp)
                                                .clip(RoundedCornerShape(8.dp))
                                                .background(Color(0xFFECE6F0)),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Icon(
                                                imageVector = Icons.Filled.CreditCard,
                                                contentDescription = null,
                                                tint = BrandPurple,
                                                modifier = Modifier.size(20.dp)
                                            )
                                        }
                                        Spacer(modifier = Modifier.width(12.dp))
                                        Text(
                                            text = method,
                                            fontSize = 15.sp,
                                            fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Normal,
                                            color = AppTextColor,
                                            modifier = Modifier.weight(1f)
                                        )
                                        if (isSelected) {
                                            Icon(
                                                imageVector = Icons.Filled.Check,
                                                contentDescription = null,
                                                tint = BrandPurple,
                                                modifier = Modifier.size(20.dp)
                                            )
                                        }
                                    }
                                    HorizontalDivider(color = Color(0xFFF0EDF7))
                                }
                            }
                        }
                    }
                }
            }
        ) {
            CompositionLocalProvider(LocalLayoutDirection provides LayoutDirection.Ltr) {
                Scaffold(
                    snackbarHost = { SnackbarHost(snackbarHostState) },
                    topBar = {
                        TopAppBar(
                            title = { Text("") },
                            navigationIcon = {
                                IconButton(onClick = {
                                    viewModel.selectedExpenseCategoryName.value = ""
                                    navController.popBackStack()
                                }) {
                                    Icon(imageVector = Icons.Filled.ArrowBack, contentDescription = "Back", tint = AppTextColor)
                                }
                            },
                            actions = {
                                if (expenseId > 0L) {
                                    var showDeleteDialog by remember { mutableStateOf(false) }
                                    IconButton(onClick = { showDeleteDialog = true }) {
                                        Icon(imageVector = Icons.Filled.Delete, contentDescription = "Delete Expense", tint = Color.Red)
                                    }
                                    if (showDeleteDialog) {
                                        AlertDialog(
                                            onDismissRequest = { showDeleteDialog = false },
                                            title = { Text("ကုန်ကျစရိတ် ဖျက်ရန်") },
                                            text = { Text("ဤကုန်ကျစရိတ်ကို ဖျက်ရန် သေချာပါသလား။") },
                                            confirmButton = {
                                                TextButton(
                                                    onClick = {
                                                        showDeleteDialog = false
                                                        val expense = Expense(
                                                            id = expenseId,
                                                            categoryName = selectedCategoryName,
                                                            description = description,
                                                            amount = amountText.toDoubleOrNull() ?: 0.0,
                                                            paymentMethod = paymentMethod,
                                                            note = note,
                                                            timestamp = timestamp,
                                                            dateString = dateString,
                                                            timeString = timeString
                                                        )
                                                        viewModel.deleteExpense(expense)
                                                        Toast.makeText(context, "Deleted", Toast.LENGTH_SHORT).show()
                                                        navController.popBackStack()
                                                    }
                                                ) {
                                                    Text("ဖျက်မည်", color = Color.Red)
                                                }
                                            },
                                            dismissButton = {
                                                TextButton(onClick = { showDeleteDialog = false }) {
                                                    Text("မဖျက်ပါ")
                                                }
                                            }
                                        )
                                    }
                                }
                            },
                            colors = TopAppBarDefaults.topAppBarColors(containerColor = Color(0xFFF3EDF7))
                        )
                    }
                ) { innerPadding ->
                    Column(
                        modifier = Modifier
                            .fillMaxSize()
                            .background(Color(0xFFF3EDF7))
                            .padding(innerPadding)
                            .verticalScroll(rememberScrollState())
                            .padding(16.dp),
                        verticalArrangement = Arrangement.spacedBy(16.dp)
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.spacedBy(12.dp)
                        ) {
                            Column(modifier = Modifier.weight(1f)) {
                                Text("Date", fontSize = 14.sp, color = Color.DarkGray, modifier = Modifier.padding(bottom = 4.dp))
                                Surface(
                                    shape = RoundedCornerShape(12.dp),
                                    color = Color(0xFFECE6F0),
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable { showDatePicker = true }
                                ) {
                                    Box(modifier = Modifier.padding(horizontal = 16.dp, vertical = 14.dp)) {
                                        Text(dateString, fontSize = 15.sp, color = AppTextColor)
                                    }
                                }
                            }

                            Column(modifier = Modifier.weight(1f)) {
                                Text("Time", fontSize = 14.sp, color = Color.DarkGray, modifier = Modifier.padding(bottom = 4.dp))
                                Surface(
                                    shape = RoundedCornerShape(12.dp),
                                    color = Color(0xFFECE6F0),
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable { showTimePicker = true }
                                ) {
                                    Box(modifier = Modifier.padding(horizontal = 16.dp, vertical = 14.dp)) {
                                        Text(timeString, fontSize = 15.sp, color = AppTextColor)
                                    }
                                }
                            }
                        }

                        Column(modifier = Modifier.fillMaxWidth()) {
                            Text("ခေါင်းစဉ်", fontSize = 14.sp, color = Color.DarkGray, modifier = Modifier.padding(bottom = 4.dp))
                            Surface(
                                shape = RoundedCornerShape(12.dp),
                                color = Color(0xFFECE6F0),
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable { navController.navigate("expense_categories") }
                            ) {
                                Box(modifier = Modifier.padding(horizontal = 16.dp, vertical = 16.dp)) {
                                    Text(
                                        text = if (selectedCategoryName.isBlank()) "No Category" else selectedCategoryName,
                                        fontSize = 15.sp,
                                        color = AppTextColor
                                    )
                                }
                            }
                        }

                        Column(modifier = Modifier.fillMaxWidth()) {
                            Text("အကြောင်းအရာ", fontSize = 14.sp, color = Color.DarkGray, modifier = Modifier.padding(bottom = 4.dp))
                            TextField(
                                value = description,
                                onValueChange = { description = it },
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .heightIn(min = 56.dp),
                                shape = RoundedCornerShape(12.dp),
                                colors = TextFieldDefaults.colors(
                                    focusedContainerColor = Color(0xFFECE6F0),
                                    unfocusedContainerColor = Color(0xFFECE6F0),
                                    disabledContainerColor = Color(0xFFECE6F0),
                                    focusedIndicatorColor = Color.Transparent,
                                    unfocusedIndicatorColor = Color.Transparent
                                ),
                                singleLine = true
                            )
                        }

                        Column(modifier = Modifier.fillMaxWidth()) {
                            Text("ပမာဏ", fontSize = 14.sp, color = Color.DarkGray, modifier = Modifier.padding(bottom = 4.dp))
                            TextField(
                                value = amountText,
                                onValueChange = { amountText = it },
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(12.dp),
                                colors = TextFieldDefaults.colors(
                                    focusedContainerColor = Color(0xFFECE6F0),
                                    unfocusedContainerColor = Color(0xFFECE6F0),
                                    disabledContainerColor = Color(0xFFECE6F0),
                                    focusedIndicatorColor = Color.Transparent,
                                    unfocusedIndicatorColor = Color.Transparent
                                ),
                                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                                singleLine = true
                            )
                        }

                        Column(modifier = Modifier.fillMaxWidth()) {
                            Text("ငွေပေးချေမှု", fontSize = 14.sp, color = Color.DarkGray, modifier = Modifier.padding(bottom = 4.dp))
                            Surface(
                                shape = RoundedCornerShape(12.dp),
                                color = Color(0xFFECE6F0),
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable { scope.launch { drawerState.open() } }
                            ) {
                                Box(modifier = Modifier.padding(horizontal = 16.dp, vertical = 16.dp)) {
                                    Text(
                                        text = if (paymentMethod.isBlank()) "No Payment" else paymentMethod,
                                        fontSize = 15.sp,
                                        color = AppTextColor
                                    )
                                }
                            }
                        }

                        Column(modifier = Modifier.fillMaxWidth()) {
                            Text("မှတ်ချက်", fontSize = 14.sp, color = Color.DarkGray, modifier = Modifier.padding(bottom = 4.dp))
                            TextField(
                                value = note,
                                onValueChange = { note = it },
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(100.dp),
                                shape = RoundedCornerShape(12.dp),
                                colors = TextFieldDefaults.colors(
                                    focusedContainerColor = Color(0xFFECE6F0),
                                    unfocusedContainerColor = Color(0xFFECE6F0),
                                    disabledContainerColor = Color(0xFFECE6F0),
                                    focusedIndicatorColor = Color.Transparent,
                                    unfocusedIndicatorColor = Color.Transparent
                                )
                            )
                        }

                        Spacer(modifier = Modifier.height(16.dp))

                        Button(
                            onClick = {
                                if (selectedCategoryName.isBlank() || selectedCategoryName == "No Category") {
                                    scope.launch {
                                        snackbarHostState.showSnackbar("ခေါင်းစဉ်ရွေးချယ်ရန်လိုအပ်ပါသည်။")
                                    }
                                } else {
                                    val amt = amountText.toDoubleOrNull() ?: 0.0
                                    val expense = Expense(
                                        id = expenseId,
                                        categoryName = selectedCategoryName,
                                        description = description,
                                        amount = amt,
                                        paymentMethod = if (paymentMethod == "No Payment") "CASH" else paymentMethod,
                                        note = note,
                                        timestamp = timestamp,
                                        dateString = dateString,
                                        timeString = timeString
                                    )
                                    viewModel.saveExpense(expense) {
                                        Toast.makeText(context, "Saved", Toast.LENGTH_SHORT).show()
                                        viewModel.selectedExpenseCategoryName.value = ""
                                        navController.navigate("expenses_list") {
                                            popUpTo("add_expense") { inclusive = true }
                                        }
                                    }
                                }
                            },
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(52.dp),
                            shape = RoundedCornerShape(12.dp),
                            colors = ButtonDefaults.buttonColors(containerColor = BrandPurple)
                        ) {
                            Text("Save", fontSize = 16.sp, fontWeight = FontWeight.Bold, color = Color.White)
                        }
                    }
                }
            }
        }
    }

    if (showDatePicker) {
        val dateSetListener = android.app.DatePickerDialog.OnDateSetListener { _, year, month, dayOfMonth ->
            calendar.set(Calendar.YEAR, year)
            calendar.set(Calendar.MONTH, month)
            calendar.set(Calendar.DAY_OF_MONTH, dayOfMonth)
            timestamp = calendar.timeInMillis
            dateString = SimpleDateFormat("yyyy-MM-dd", Locale.US).format(calendar.time)
            showDatePicker = false
        }
        android.app.DatePickerDialog(
            context,
            dateSetListener,
            calendar.get(Calendar.YEAR),
            calendar.get(Calendar.MONTH),
            calendar.get(Calendar.DAY_OF_MONTH)
        ).show()
        showDatePicker = false
    }

    if (showTimePicker) {
        val timeSetListener = android.app.TimePickerDialog.OnTimeSetListener { _, hourOfDay, minute ->
            calendar.set(Calendar.HOUR_OF_DAY, hourOfDay)
            calendar.set(Calendar.MINUTE, minute)
            timestamp = calendar.timeInMillis
            timeString = SimpleDateFormat("h:mm a", Locale.US).format(calendar.time).uppercase()
            showTimePicker = false
        }
        android.app.TimePickerDialog(
            context,
            timeSetListener,
            calendar.get(Calendar.HOUR_OF_DAY),
            calendar.get(Calendar.MINUTE),
            false
        ).show()
        showTimePicker = false
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun ExpenseCategoriesScreen(
    navController: NavController,
    viewModel: POSViewModel
) {
    val categories by viewModel.allExpenseCategories.collectAsState()
    var searchQuery by remember { mutableStateOf("") }
    var isSearching by remember { mutableStateOf(false) }

    val filteredCategories = remember(categories, searchQuery) {
        if (searchQuery.isBlank()) categories
        else categories.filter { it.name.contains(searchQuery, ignoreCase = true) }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = {
                    if (isSearching) {
                        TextField(
                            value = searchQuery,
                            onValueChange = { searchQuery = it },
                            placeholder = { Text("ခေါင်းစဉ် ရှာဖွေရန်...", color = Color.Gray) },
                            singleLine = true,
                            colors = TextFieldDefaults.colors(
                                focusedContainerColor = Color.Transparent,
                                unfocusedContainerColor = Color.Transparent,
                                focusedIndicatorColor = Color.Transparent,
                                unfocusedIndicatorColor = Color.Transparent
                            ),
                            modifier = Modifier.fillMaxWidth()
                        )
                    } else {
                        Text("ခေါင်းစဉ်", fontWeight = FontWeight.Bold, color = AppTextColor)
                    }
                },
                navigationIcon = {
                    IconButton(onClick = {
                        if (isSearching) {
                            isSearching = false
                            searchQuery = ""
                        } else {
                            navController.popBackStack()
                        }
                    }) {
                        Icon(imageVector = Icons.Filled.ArrowBack, contentDescription = "Back", tint = AppTextColor)
                    }
                },
                actions = {
                    if (isSearching) {
                        if (searchQuery.isNotEmpty()) {
                            IconButton(onClick = { searchQuery = "" }) {
                                Icon(imageVector = Icons.Filled.Close, contentDescription = "Clear", tint = AppTextColor)
                            }
                        }
                    } else {
                        IconButton(onClick = { isSearching = true }) {
                            Icon(imageVector = Icons.Filled.Search, contentDescription = "Search", tint = AppTextColor)
                        }
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.White)
            )
        },
        floatingActionButton = {
            FloatingActionButton(
                onClick = { navController.navigate("add_expense_category") },
                containerColor = Color(0xFFECE6F0),
                contentColor = AppTextColor,
                shape = RoundedCornerShape(16.dp)
            ) {
                Icon(imageVector = Icons.Filled.Add, contentDescription = "Add Category")
            }
        },
        modifier = Modifier.fillMaxSize()
    ) { innerPadding ->
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(Color(0xFFFAF9FD))
                .padding(innerPadding)
        ) {
            if (filteredCategories.isEmpty()) {
                Column(
                    modifier = Modifier.fillMaxSize(),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.Center
                ) {
                    Box(
                        modifier = Modifier
                            .size(64.dp)
                            .clip(CircleShape)
                            .background(Color(0xFFECE6F0)),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(
                            imageVector = Icons.Filled.Inventory2,
                            contentDescription = null,
                            tint = BrandPurple,
                            modifier = Modifier.size(32.dp)
                        )
                    }
                    Spacer(modifier = Modifier.height(12.dp))
                    Text("No Category Found", fontSize = 15.sp, color = AppTextColor)
                }
            } else {
                LazyColumn(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(vertical = 8.dp)
                ) {
                    items(filteredCategories) { category ->
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clickable {
                                    viewModel.selectedExpenseCategoryName.value = category.name
                                    viewModel.selectedExpenseCategoryIcon.value = category.iconName
                                    navController.popBackStack()
                                }
                                .padding(horizontal = 16.dp, vertical = 12.dp)
                        ) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(44.dp)
                                        .clip(RoundedCornerShape(10.dp))
                                        .background(Color(0xFFECE6F0)),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        imageVector = getExpenseIcon(category.iconName),
                                        contentDescription = null,
                                        tint = BrandPurple,
                                        modifier = Modifier.size(24.dp)
                                    )
                                }
                                Spacer(modifier = Modifier.width(16.dp))
                                Text(
                                    text = category.name,
                                    fontSize = 16.sp,
                                    fontWeight = FontWeight.Medium,
                                    color = AppTextColor,
                                    modifier = Modifier.weight(1f)
                                )
                            }
                            HorizontalDivider(
                                modifier = Modifier.padding(top = 12.dp),
                                color = Color(0xFFF0EDF7)
                            )
                        }
                    }
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AddExpenseCategoryScreen(
    navController: NavController,
    viewModel: POSViewModel
) {
    var categoryName by remember { mutableStateOf("") }
    var selectedIconName by remember { mutableStateOf("ShoppingCart") }
    var showIconPicker by remember { mutableStateOf(false) }

    val iconOptions = listOf(
        "ShoppingCart", "Store", "ShoppingBag", "AttachMoney", "Glasses",
        "Restaurant", "LocalBar", "LocalTaxi", "DirectionsCar", "DirectionsBus",
        "DirectionsBike", "Flight", "Build", "MedicalServices", "School",
        "Home", "Phone", "Wifi", "Email", "CameraAlt", "Star", "Work", "AccountBalance"
    )

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("") },
                navigationIcon = {
                    IconButton(onClick = { navController.popBackStack() }) {
                        Icon(imageVector = Icons.Filled.ArrowBack, contentDescription = "Back", tint = AppTextColor)
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = Color(0xFFF3EDF7))
            )
        }
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .background(Color(0xFFF3EDF7))
                .padding(innerPadding)
                .padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(12.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Column(modifier = Modifier.weight(1f)) {
                    Text("ခေါင်းစဉ်အမည်", fontSize = 14.sp, color = Color.DarkGray, modifier = Modifier.padding(bottom = 4.dp))
                    TextField(
                        value = categoryName,
                        onValueChange = { categoryName = it },
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(12.dp),
                        colors = TextFieldDefaults.colors(
                            focusedContainerColor = Color(0xFFECE6F0),
                            unfocusedContainerColor = Color(0xFFECE6F0),
                            disabledContainerColor = Color(0xFFECE6F0),
                            focusedIndicatorColor = Color.Transparent,
                            unfocusedIndicatorColor = Color.Transparent
                        ),
                        singleLine = true
                    )
                }

                Column {
                    Text("Icon", fontSize = 14.sp, color = Color.DarkGray, modifier = Modifier.padding(bottom = 4.dp))
                    Surface(
                        shape = RoundedCornerShape(12.dp),
                        color = Color(0xFFECE6F0),
                        modifier = Modifier
                            .size(56.dp)
                            .clickable { showIconPicker = true }
                    ) {
                        Box(contentAlignment = Alignment.Center) {
                            Icon(
                                imageVector = getExpenseIcon(selectedIconName),
                                contentDescription = null,
                                tint = AppTextColor
                            )
                        }
                    }
                }
            }

            Spacer(modifier = Modifier.height(8.dp))

            Button(
                onClick = {
                    if (categoryName.isNotBlank()) {
                        viewModel.addExpenseCategory(categoryName, selectedIconName)
                        navController.popBackStack()
                    }
                },
                modifier = Modifier
                    .fillMaxWidth()
                    .height(52.dp),
                shape = RoundedCornerShape(12.dp),
                colors = ButtonDefaults.buttonColors(containerColor = BrandPurple)
            ) {
                Text("SAVE", fontSize = 16.sp, fontWeight = FontWeight.Bold, color = Color.White)
            }
        }
    }

    if (showIconPicker) {
        Dialog(onDismissRequest = { showIconPicker = false }) {
            Surface(
                shape = RoundedCornerShape(16.dp),
                color = Color.White,
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(16.dp)
            ) {
                Column(
                    modifier = Modifier.padding(16.dp)
                ) {
                    Text("Select Icon", fontWeight = FontWeight.Bold, fontSize = 16.sp, modifier = Modifier.padding(bottom = 12.dp))
                    LazyVerticalGrid(
                        columns = GridCells.Fixed(5),
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalArrangement = Arrangement.spacedBy(8.dp),
                        modifier = Modifier.height(280.dp)
                    ) {
                        items(iconOptions) { iconName ->
                            Surface(
                                shape = RoundedCornerShape(8.dp),
                                color = if (selectedIconName == iconName) BrandPurple else Color(0xFFECE6F0),
                                modifier = Modifier
                                    .size(44.dp)
                                    .clickable {
                                        selectedIconName = iconName
                                        showIconPicker = false
                                    }
                            ) {
                                Box(contentAlignment = Alignment.Center) {
                                    Icon(
                                        imageVector = getExpenseIcon(iconName),
                                        contentDescription = null,
                                        tint = if (selectedIconName == iconName) Color.White else AppTextColor
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun ExpensesListScreen(
    navController: NavController,
    viewModel: POSViewModel
) {
    val expenses by viewModel.allExpenses.collectAsState()
    val selectedCurrency by viewModel.selectedCurrency.collectAsState()

    val calendar = remember { Calendar.getInstance() }
    val todayMillis = calendar.timeInMillis
    val firstDayOfMonthMillis = remember {
        val cal = Calendar.getInstance()
        cal.set(Calendar.DAY_OF_MONTH, 1)
        cal.set(Calendar.HOUR_OF_DAY, 0)
        cal.set(Calendar.MINUTE, 0)
        cal.set(Calendar.SECOND, 0)
        cal.set(Calendar.MILLISECOND, 0)
        cal.timeInMillis
    }

    var startDate by remember { mutableStateOf(firstDayOfMonthMillis) }
    var endDate by remember { mutableStateOf(todayMillis) }
    var showDatePicker by remember { mutableStateOf(false) }

    val dateFormatter = remember { SimpleDateFormat("dd/MM/yyyy", Locale.US) }

    val filteredExpenses = remember(expenses, startDate, endDate) {
        expenses.filter { it.timestamp in startDate..endDate }
    }
    val totalAmount = remember(filteredExpenses) { filteredExpenses.sumOf { it.amount } }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("ကုန်ကျစရိတ်များ", fontWeight = FontWeight.Bold, color = AppTextColor) },
                navigationIcon = {
                    IconButton(onClick = { navController.popBackStack() }) {
                        Icon(imageVector = Icons.Filled.ArrowBack, contentDescription = "Back", tint = AppTextColor)
                    }
                },
                actions = {
                    IconButton(onClick = { showDatePicker = true }) {
                        Icon(imageVector = Icons.Filled.DateRange, contentDescription = "Select Date Range", tint = BrandPurple)
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.White)
            )
        },
        bottomBar = {
            Surface(
                color = Color.White,
                shadowElevation = 8.dp,
                modifier = Modifier.fillMaxWidth()
            ) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 16.dp, vertical = 14.dp),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = "စုစုပေါင်း (${filteredExpenses.size})",
                        fontSize = 16.sp,
                        fontWeight = FontWeight.Bold,
                        color = AppTextColor
                    )
                    Text(
                        text = "${String.format("%,.0f", totalAmount)} $selectedCurrency",
                        fontSize = 18.sp,
                        fontWeight = FontWeight.Bold,
                        color = BrandPurple
                    )
                }
            }
        },
        modifier = Modifier.fillMaxSize()
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .background(Color(0xFFFAF9FD))
                .padding(innerPadding)
        ) {
            Card(
                colors = CardDefaults.cardColors(containerColor = Color.White),
                shape = RoundedCornerShape(0.dp),
                modifier = Modifier
                    .fillMaxWidth()
                    .clickable { showDatePicker = true }
            ) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 16.dp, vertical = 12.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.SpaceBetween
                ) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Icon(
                            imageVector = Icons.Filled.DateRange,
                            contentDescription = null,
                            tint = Color.Gray,
                            modifier = Modifier.size(18.dp)
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(
                            text = "${dateFormatter.format(Date(startDate))} မှ ${dateFormatter.format(Date(endDate))} အထိ",
                            fontSize = 14.sp,
                            fontWeight = FontWeight.Medium,
                            color = Color.DarkGray
                        )
                    }
                    Icon(
                        imageVector = Icons.Filled.ChevronRight,
                        contentDescription = "Edit Date Range",
                        tint = Color.Gray,
                        modifier = Modifier.size(16.dp)
                    )
                }
            }

            if (filteredExpenses.isEmpty()) {
                Box(
                    modifier = Modifier.fillMaxSize(),
                    contentAlignment = Alignment.Center
                ) {
                    Text("ကုန်ကျစရိတ် မှတ်တမ်း မရှိသေးပါ", color = Color.Gray, fontSize = 15.sp)
                }
            } else {
                LazyColumn(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(vertical = 8.dp)
                ) {
                    items(filteredExpenses) { expense ->
                        val dateFormatted = remember(expense.timestamp) {
                            if (expense.dateString.isNotBlank()) expense.dateString else dateFormatter.format(Date(expense.timestamp))
                        }

                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clickable {
                                    navController.navigate("add_expense?expenseId=${expense.id}")
                                }
                                .padding(horizontal = 16.dp, vertical = 12.dp)
                        ) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(44.dp)
                                        .clip(RoundedCornerShape(10.dp))
                                        .background(Color(0xFFECE6F0)),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        imageVector = Icons.Filled.ShoppingCart,
                                        contentDescription = null,
                                        tint = BrandPurple,
                                        modifier = Modifier.size(24.dp)
                                    )
                                }
                                Spacer(modifier = Modifier.width(14.dp))
                                Column(modifier = Modifier.weight(1f)) {
                                    Text(
                                        text = expense.categoryName,
                                        fontSize = 15.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = AppTextColor
                                    )
                                    if (expense.description.isNotBlank()) {
                                        Text(
                                            text = expense.description,
                                            fontSize = 13.sp,
                                            color = Color.Gray
                                        )
                                    } else {
                                        Text(
                                            text = dateFormatted,
                                            fontSize = 12.sp,
                                            color = Color.Gray
                                        )
                                    }
                                }
                                Column(horizontalAlignment = Alignment.End) {
                                    Text(
                                        text = "${String.format("%,.0f", expense.amount)} $selectedCurrency",
                                        fontSize = 15.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = AppTextColor
                                    )
                                    if (expense.paymentMethod.isNotBlank()) {
                                        Text(
                                            text = expense.paymentMethod,
                                            fontSize = 12.sp,
                                            color = Color.Gray
                                        )
                                    }
                                }
                            }
                            HorizontalDivider(
                                modifier = Modifier.padding(top = 12.dp),
                                color = Color(0xFFF0EDF7)
                            )
                        }
                    }
                }
            }
        }
    }

    if (showDatePicker) {
        MyDateRangePickerDialog(
            onDismissRequest = { showDatePicker = false },
            onDateRangeSelected = { start, end ->
                if (start != null && end != null) {
                    val localStartCal = Calendar.getInstance().apply {
                        timeInMillis = start
                        set(Calendar.HOUR_OF_DAY, 0)
                        set(Calendar.MINUTE, 0)
                        set(Calendar.SECOND, 0)
                        set(Calendar.MILLISECOND, 0)
                    }
                    startDate = localStartCal.timeInMillis

                    val localEndCal = Calendar.getInstance().apply {
                        timeInMillis = end
                        set(Calendar.HOUR_OF_DAY, 23)
                        set(Calendar.MINUTE, 59)
                        set(Calendar.SECOND, 59)
                        set(Calendar.MILLISECOND, 999)
                    }
                    endDate = localEndCal.timeInMillis
                }
            }
        )
    }
}

